	}
}

NAstatsUI.createInstance = function(className, properties, parent)
	const inst = InstanceNew(className)
	for prop, value in properties do
		inst[prop] = value
	end
	if parent then
		inst.Parent = parent
	end
	return inst
end

function NAstatsUI.colorToHex(c)
	return Format("#%02X%02X%02X", math.floor(c.R * 255), math.floor(c.G * 255), math.floor(c.B * 255))
end

function NAstatsUI.ensureSingle(key, buildFn)
	const existing = windowRegistry[key]
	if existing and existing.screenGui and existing.screenGui.Parent then
		existing.bringToFront()
		return existing
	end

	const newUi = buildFn()
	windowRegistry[key] = newUi

	const function cleanup()
		if windowRegistry[key] == newUi then
			windowRegistry[key] = nil
			NAlib.disconnect("UI:"..key)
		end
	end
	newUi.screenGui.Destroying:Connect(cleanup)
	MouseButtonFix(newUi.closeButton, function()
		cleanup()
		newUi.screenGui:Destroy()
	end)
	return newUi
end

function NAstatsUI.createWindow(position, baseSize, titleText, compact)
	windowCounter += 1
	const T = NAstatsUI.Theme
	const topH = compact and (IsOnMobile and 34 or 28) or T.Sizes.TopBarHeight
	const actSize = compact and (IsOnMobile and 26 or 22) or T.Sizes.ActionButton
	const hasBody = not compact or baseSize.Y.Offset > topH

	const screenGui = NAstatsUI.createInstance("ScreenGui", {
		ResetOnSpawn = false,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		DisplayOrder = 100 + windowCounter,
	})
	NAgui.NaProtectUI(screenGui)

	const holder = NAstatsUI.createInstance("Frame", {
		Name = "Holder",
		BackgroundTransparency = 1,
		AnchorPoint = compact and Vector2.new(1, 0) or Vector2.new(0.5, 0.5),
		Position = position or UDim2.new(0.5, 0, 0.3, 0),
		Size = compact and UDim2.new(1, -16, 0, baseSize.Y.Offset) or baseSize,
		Parent = screenGui,
	})

	if compact then
		NAstatsUI.createInstance("UISizeConstraint", {
			MaxSize = Vector2.new(baseSize.X.Offset, baseSize.Y.Offset),
		}, holder)
	end

	const window = NAstatsUI.createInstance("Frame", {
		Name = "Window",
		BackgroundColor3 = T.Colors.Primary,
		BackgroundTransparency = compact and 0.12 or 0.46,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 1, 0),
		Parent = holder
	})
	NAstatsUI.createInstance("UICorner", { CornerRadius = UDim.new(0, 6) }, window)
	NAstatsUI.createInstance("UIStroke", {
		Color = T.Colors.Border,
		Thickness = compact and 1 or 4,
		Transparency = compact and 0.72 or 0.05,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border
	}, window)
	NAstatsUI.createInstance("UIGradient", {
		Color = ColorSequence.new({
			ColorSequenceKeypoint.new(0, Color3.fromRGB(10, 10, 11)),
			ColorSequenceKeypoint.new(1, T.Colors.Primary),
		}),
		Rotation = 90,
	}, window)

	const topBar = NAstatsUI.createInstance("Frame", {
		Name = "TopBar",
		BackgroundColor3 = T.Colors.Primary,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, topH),
		ZIndex = 2,
		Parent = window,
	})
	NAstatsUI.createInstance("UICorner", {
		CornerRadius = UDim.new(0, 6),
	}, topBar)

	NAstatsUI.createInstance("UIPadding", {
		PaddingLeft = UDim.new(0, 9),
		PaddingRight = UDim.new(0, 7),
	}, topBar)

	const title = NAstatsUI.createInstance("TextLabel", {
		Name = "Title",
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 0, 0, 0),
		Size = UDim2.new(1, -(actSize * (hasBody and 2 or 1) + (compact and 12 or 28)), 1, 0),
		Font = T.Fonts.BodyBold,
		Text = titleText,
		TextColor3 = T.Colors.Text,
		TextSize = compact and (IsOnMobile and 14 or 13) or (IsOnMobile and 20 or 18),
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Center,
		TextTruncate = Enum.TextTruncate.AtEnd,
		RichText = true,
		ZIndex = 3,
		Parent = topBar,
	})

	const function createActionButton(name, text, color, order)
		const btn = NAstatsUI.createInstance("TextButton", {
			Name = name,
			BackgroundColor3 = color,
			BackgroundTransparency = 0.08,
			AutoButtonColor = true,
			Size = UDim2.fromOffset(actSize, actSize),
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, -(2 + (order - 1) * (actSize + (compact and 4 or 6))), 0.5, 0),
			Font = T.Fonts.BodyBold,
			Text = text,
			TextScaled = false,
			TextSize = compact and 15 or (IsOnMobile and 20 or 17),
			TextColor3 = Color3.new(1, 1, 1),
			ZIndex = 3,
			RichText = true,
			Parent = topBar,
		})
		NAstatsUI.createInstance("UICorner", { CornerRadius = UDim.new(0, 6) }, btn)
		NAstatsUI.createInstance("UIStroke", {
			Color = T.Colors.Border,
			Thickness = compact and 1 or 2,
			Transparency = compact and 0.75 or 0.18,
			ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		}, btn)
		return btn
	end

	const minimizeButton = hasBody and createActionButton("Minimize", "", compact and T.Colors.Secondary or T.Colors.Minimize, 2)
	if minimizeButton then NAmanage.SetIcon(minimizeButton, "minus") end
	const closeButton = createActionButton("Close", compact and "×" or "X", compact and T.Colors.Secondary or T.Colors.Close, 1)
	local content
	if hasBody then
		const margin = compact and 6 or 8
		content = NAstatsUI.createInstance("Frame", {
			Name = "Content",
			BackgroundTransparency = 1,
			Position = UDim2.fromOffset(margin, topH),
			Size = UDim2.new(1, -margin * 2, 1, -(topH + margin)),
			ZIndex = 2,
			Parent = window,
		})
		if not compact then
			NAstatsUI.createInstance("UIPadding", {
				PaddingLeft = UDim.new(0, 6),
				PaddingRight = UDim.new(0, 6),
				PaddingTop = UDim.new(0, 2),
				PaddingBottom = UDim.new(0, 4),
			}, content)
		end
	end

	NAgui.draggerV2(holder, topBar)
	local collapsed = false
	local baseTitleText = titleText
	local collapsedTitleText = titleText
	if minimizeButton then
		const openSize = holder.Size
		MouseButtonFix(minimizeButton, function()
			collapsed = not collapsed
			content.Visible = not collapsed
			if collapsed then
				holder.Size = UDim2.new(openSize.X.Scale, openSize.X.Offset, 0, topH + (compact and 0 or 6))
				title.Text = collapsedTitleText
			else
				holder.Size = openSize
				title.Text = baseTitleText
			end
			if compact then
				NAmanage.SetIcon(minimizeButton, collapsed and "plus" or "minus")
			end
		end)
	end

	return {
		screenGui = screenGui,
		holder = holder,
		window = window,
		title = title,
		content = content,
		closeButton = closeButton,
		minimizeButton = minimizeButton,
		setBaseTitle = function(t)
			baseTitleText = t
			if not collapsed and title.Text ~= t then
				title.Text = t
			end
		end,
		setCollapsedTitle = function(t)
			collapsedTitleText = t
			if collapsed and title.Text ~= t then
				title.Text = t
			end
		end,
		bringToFront = function()
			windowCounter += 1
			screenGui.DisplayOrder = 100 + windowCounter
		end,
	}
end

function NAstatsUI.createStatDisplay(parent, titleText, subtitleText)
	const T = NAstatsUI.Theme
	const container = NAstatsUI.createInstance("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 1, 0),
		Parent = parent,
	})

	NAstatsUI.createInstance("UIPadding", {
		PaddingTop = UDim.new(0, 2),
		PaddingBottom = UDim.new(0, 2),
		PaddingLeft = UDim.new(0, 4),
		PaddingRight = UDim.new(0, 4),
	}, container)

	const titleHeight = IsOnMobile and 16 or 14
	const valueHeight = IsOnMobile and 26 or 24

	const titleLabel = NAstatsUI.createInstance("TextLabel", {
		Name = "TitleLabel",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, titleHeight),
		Font = T.Fonts.BodySemibold,
		Text = titleText,
		TextSize = IsOnMobile and 13 or 12,
		TextColor3 = T.Colors.TextMuted,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		RichText = true,
		Parent = container,
	})

	const valueLabel = NAstatsUI.createInstance("TextLabel", {
		Name = "ValueLabel",
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 0, 0, titleHeight + 2),
		Size = UDim2.new(1, 0, 0, valueHeight),
		Font = T.Fonts.BodyBold,
		Text = "—",
		TextSize = IsOnMobile and 23 or 21,
		TextColor3 = T.Colors.TextSubtle,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		RichText = true,
		Parent = container,
	})

	const subtitleLabel = NAstatsUI.createInstance("TextLabel", {
		Name = "SubtitleLabel",
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 0, 0, titleHeight + valueHeight + 4),
		Size = UDim2.new(1, 0, 0, IsOnMobile and 16 or 14),
		Font = T.Fonts.Body,
		Text = subtitleText,
		TextSize = IsOnMobile and 12 or 12,
		TextColor3 = T.Colors.TextMuted,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		RichText = true,
		Parent = container,
	})

	return { value = valueLabel, subtitle = subtitleLabel, title = titleLabel }
end

NAmanage._makeFpsTracker = NAmanage._makeFpsTracker or function(key, signal)
	const tr = { value = 0, lastRead = os.clock() }
	local frames, elapsed = 0, 0
	tr.conn = NAlib.reconnect(key, signal:Connect(function(dt)
		if os.clock() - tr.lastRead > 2 then
			NAlib.disconnect(key)
			tr.conn = nil
			return
		end
		frames += 1
		elapsed += dt
		if elapsed >= 0.5 then
			tr.value = math.floor(frames / elapsed + 0.5)
			frames, elapsed = 0, 0
		end
	end))
	return tr
end

NAmanage.getRealFPS = NAmanage.getRealFPS or function()
	local tr = NAmanage._fpsTracker
	if not (tr and tr.conn and tr.conn.Connected) then
		tr = NAmanage._makeFpsTracker("UI:FPS_TRACKER", Services.RunService.RenderStepped)
		NAmanage._fpsTracker = tr
	end
	tr.lastRead = os.clock()
	return tr.value
end

NAmanage.getHeartbeatFPS = NAmanage.getHeartbeatFPS or function()
	local tr = NAmanage._hbTracker
	if not (tr and tr.conn and tr.conn.Connected) then
		tr = NAmanage._makeFpsTracker("UI:HB_FPS_TRACKER", Services.RunService.Heartbeat)
		NAmanage._hbTracker = tr
	end
	tr.lastRead = os.clock()
	return tr.value
end

