do
	const C = NAstatsUI.Theme.Colors
	const height = IsOnMobile and 34 or 28
	const rowH = IsOnMobile and 22 or 20
	const gap = 4

	const function fpsColor(fps)
		if fps <= 0 then return C.TextMuted end
		if fps >= 55 then return C.Good end
		if fps >= 30 then return C.Warn end
		return C.Bad
	end

	const function pingColor(ping)
		if ping == nil then return C.TextMuted end
		if ping <= 50 then return C.Good end
		if ping <= 100 then return C.Warn end
		return C.Bad
	end

	const function getPing()
		return NAmanage.GetDataPingMs and tonumber(NAmanage.GetDataPingMs()) or nil
	end

	const function valueText(value, fmt)
		return value and Format(fmt, value) or "—"
	end

	const function fpsText(fps)
		return fps > 0 and tostring(fps) or "—"
	end

	const function accent(text, color)
		return Format("<font color='%s'>%s</font>", NAstatsUI.colorToHex(color), text)
	end

	const function startOverlay(key, title, width, rows, slot, build)
		return NAstatsUI.ensureSingle(key, function()
			const pos = UDim2.new(1, -8, 0, 8 + slot * (height + gap))
			const body = rows > 0 and (rows * (rowH + gap) - gap + 6) or 0
			const ui = NAstatsUI.createWindow(pos, UDim2.fromOffset(width, height + body), title, true)
			const refresh = build(ui)
			refresh()
			local elapsed = 0
			NAlib.reconnect("UI:"..key, Services.RunService.Heartbeat:Connect(function(dt)
				elapsed += dt
				if elapsed >= 0.5 and ui.screenGui.Parent then
					elapsed %= 0.5
					refresh()
				end
			end))
			return ui
		end)
	end

	cmd.register({
		name = "ping",
		description = "Shows your network latency",
		callback = function()
			startOverlay("Ping", "Ping", 132, 0, 0, function(ui)
				return function()
					const ping = getPing()
					ui.setBaseTitle("Ping  "..accent(valueText(ping, "%.0f ms"), pingColor(ping)))
				end
			end)
		end,
	})

	cmd.register({
		name = "fps",
		description = "Shows your frames per second",
		callback = function()
			startOverlay("FPS", "FPS", 116, 0, 1, function(ui)
				return function()
					const fps = NAmanage.getRealFPS()
					ui.setBaseTitle("FPS  "..accent(fpsText(fps), fpsColor(fps)))
				end
			end)
		end,
	})

	cmd.register({
		name = "fpsping",
		aliases = { "pingfps", "fpsp", "pfps" },
		description = "Shows FPS and ping in one strip",
		usage = "fpsping (pingfps)",
		callback = function()
			startOverlay("FPSPing", "FPS / Ping", 202, 0, 2, function(ui)
				return function()
					const fps = NAmanage.getRealFPS()
					const ping = getPing()
					ui.setBaseTitle(accent(fpsText(fps), fpsColor(fps)).." FPS   ·   "..accent(valueText(ping, "%.0f ms"), pingColor(ping)))
				end
			end)
		end,
	})

	cmd.register({
		name = "stats",
		aliases = { "devstats", "loadstats" },
		description = "Shows FPS, physics, network and memory stats",
		usage = "stats (devstats, loadstats)",
		callback = function()
			const names = { "Render FPS", "Ping", "Heartbeat", "Physics FPS", "Receive", "Send", "Memory", "Instances", "Speed", "Velocity", "Humanoid" }
			startOverlay("Stats", "Stats", 304, math.ceil(#names / 2), 3, function(ui)
				const T = NAstatsUI.Theme
				const make = NAstatsUI.createInstance
				make("UIGridLayout", {
					CellSize = UDim2.new(0.5, -gap / 2, 0, rowH),
					CellPadding = UDim2.fromOffset(gap, gap),
					FillDirectionMaxCells = 2,
					SortOrder = Enum.SortOrder.LayoutOrder,
				}, ui.content)

				const labels = {}
				for i, name in names do
					const cell = make("Frame", {
						Name = name,
						LayoutOrder = i,
						BackgroundColor3 = C.Secondary,
						BackgroundTransparency = 0.18,
						BorderSizePixel = 0,
					}, ui.content)
					make("UICorner", { CornerRadius = UDim.new(0, 4) }, cell)
					make("TextLabel", {
						BackgroundTransparency = 1,
						Position = UDim2.fromOffset(5, 0),
						Size = UDim2.new(0.5, 0, 1, 0),
						Font = T.Fonts.Body,
						Text = name,
						TextColor3 = C.TextMuted,
						TextSize = 11,
						TextTruncate = Enum.TextTruncate.AtEnd,
						TextXAlignment = Enum.TextXAlignment.Left,
					}, cell)
					labels[i] = make("TextLabel", {
						Name = "Value",
						BackgroundTransparency = 1,
						Position = UDim2.new(0.5, 5, 0, 0),
						Size = UDim2.new(0.5, -10, 1, 0),
						Font = T.Fonts.BodySemibold,
						Text = "—",
						TextColor3 = C.Text,
						TextSize = 11,
						TextTruncate = Enum.TextTruncate.AtEnd,
						TextXAlignment = Enum.TextXAlignment.Right,
					}, cell)
				end

				const stats = Services.Stats
				return function()
					const fps = NAmanage.getRealFPS()
					const ping = getPing()
					const fpsCol, pingCol = fpsColor(fps), pingColor(ping)
					ui.setCollapsedTitle("Stats   "..accent(fpsText(fps), fpsCol).." FPS   ·   "..accent(valueText(ping, "%.0f ms"), pingCol))
					if not ui.content.Visible then
						return
					end

					const char = getChar()
					const root = char and getRoot(char)
					const vel = root and root.AssemblyLinearVelocity
					const hum = getHum()
					const values = {
						fpsText(fps),
						valueText(ping, "%.0f ms"),
						fpsText(NAmanage.getHeartbeatFPS()),
						valueText(NAmanage.getRealPhysicsFPS(), "%.0f"),
						valueText(stats and stats.DataReceiveKbps, "%.1f kb/s"),
						valueText(stats and stats.DataSendKbps, "%.1f kb/s"),
						valueText(NAmanage.getMemoryMb(), "%.0f MB"),
						valueText(stats and stats.InstanceCount, "%.0f"),
						valueText(vel and Vector3.new(vel.X, 0, vel.Z).Magnitude, "%.1f st/s"),
						valueText(vel and vel.Magnitude, "%.1f st/s"),
						hum and hum:GetState().Name or "—",
					}
					for i, value in values do
						if labels[i].Text ~= value then
							labels[i].Text = value
						end
					end
					if labels[1].TextColor3 ~= fpsCol then labels[1].TextColor3 = fpsCol end
					if labels[2].TextColor3 ~= pingCol then labels[2].TextColor3 = pingCol end
				end
			end)
		end,
	})
end

