			values[key] = val
			card.BackgroundTransparency = 0.35
			__lt.cm("TweenService", "Create", card, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundTransparency = 0.15}):Play()
		end

