	description = "Disable Rolewatch monitoring",
	callback = function()
		const data = NAStuff.RolewatchData
		data.Group = 0
		data.Role = ""
		data.RoleLower = ""
		data.Leave = false
		DoNotif("Rolewatch disabled.", 3, "Rolewatch")
	end,
})

cmd.register({
