cmd.register({
	name = "joingroup",
	aliases = { "groupjoin" },
	description = "Open the Pedoblox join prompt for a group",
	usage = "joingroup [groupId] (groupjoin)",
	callback = function(groupIdArg)
		const supplied = tostring(groupIdArg or "")
		const hasInput = supplied ~= ""
		local targetId = tonumber(groupIdArg)

		if hasInput and (not targetId or targetId <= 0) then
			DoNotif("Please provide a valid numeric group id.", 4)
			return
		end

		if not targetId or targetId <= 0 then
			if game.CreatorType == Enum.CreatorType.Group and tonumber(game.CreatorId) then
				targetId = tonumber(game.CreatorId)
			else
				DoNotif("Provide a group id; this game is not owned by a group.", 4)
				return
			end
		end

		const groupService = SafeGetService("GroupService",false)
		if not groupService or type(groupService.PromptJoinAsync) ~= "function" then
			DoNotif("GroupService.PromptJoinAsync is unavailable.", 4)
			return
		end

		local ok, res = pcall(function()
			return groupService:PromptJoinAsync(targetId)
		end)

		if ok then
			const groupName = res and res.Name or ("group "..tostring(targetId))
			DebugNotif("Join prompt opened for "..groupName, 3)
		else
			DebugNotif("Failed to open join prompt: "..tostring(res), 4)
		end
	end,
})

cmd.register({
	name = "trackstaff",
	aliases = { "staffwatch" },
	description = "Track, highlight, and notify when a staff member joins the server",
	usage = "trackstaff (staffwatch)",
	callback = function()
		NAmanage.StaffwatchClearAll()

		if game.CreatorType == Enum.CreatorType.Group then
			NAStuff.StaffwatchState.active = true
			NAlib.connect("staffNotifier", Services.Players.PlayerAdded:Connect(function(player)
				NAmanage.StaffwatchHandlePlayer(player, true)
			end))
			NAlib.connect("staffNotifierRemoving", Services.Players.PlayerRemoving:Connect(function(player)
				NAmanage.StaffwatchClearPlayer(player)
			end))
			Spawn(function()
				local staffCount = 0
				const scanStart = os.clock()
				const players = Services.Players:GetPlayers()
				for i, player in players do
					if not (NAStuff.StaffwatchState and NAStuff.StaffwatchState.active) then
						return
					end
					local okInfo, info = pcall(NAmanage.StaffwatchHandlePlayer, player, true)
					if okInfo and type(info) == "table" and info.IsStaff then
						staffCount += 1
					end
					if i % 2 == 0 or IsOnMobile == true then
						Wait()
					end
				end
				const perf = NAStuff and NAStuff.StartupPerformance
				if type(perf) == "table" and perf.finished ~= true then
					perf.staffwatchScanElapsed = os.clock() - scanStart
					perf.staffwatchScanPlayers = #players
				end
				if NAStuff.StaffwatchState and NAStuff.StaffwatchState.active then
					const status = staffCount == 0 and "Tracking enabled - no staff detected" or ("Tracking enabled - "..staffCount.." staff detected")
					DoNotif(status, 4, "Staffwatch")
				end
			end)
		else
			DoNotif("Game is not owned by a Group", 4, "Staffwatch")
		end
	end,
})

cmd.register({
	name = "stoptrackstaff",
	aliases = { "untrackstaff", "unstaffwatch" },
	description = "Stop tracking staff members",
	usage = "stoptrackstaff (untrackstaff, unstaffwatch)",
	callback = function()
		NAmanage.StaffwatchClearAll()
		DoNotif("Tracking disabled", 3, "Staffwatch")
	end,
})

NAStuff.AntiStaffState = NAStuff.AntiStaffState or {
	active = false;
	mode = "serverhop";
	triggered = false;
	token = 0;
}

NAmanage.AntiStaffNormalizeMode = function(mode)
	const normalized = Lower(tostring(mode or "")):gsub("[%s_%-%+]+", "")
	if normalized == "" or normalized == "serverhop" or normalized == "hop" or normalized == "shop" or normalized == "advanced" or normalized == "advancedserverhop" then
		return "serverhop"
	end
	if normalized == "leave" or normalized == "exit" or normalized == "shutdown" then
		return "leave"
	end
	return nil
end

NAmanage.AntiStaffStop = function()
	NAlib.disconnect("antiStaffNotifier")
	local state = NAStuff.AntiStaffState
	if type(state) ~= "table" then
		state = { active = false; mode = "serverhop"; triggered = false; token = 0; }
		NAStuff.AntiStaffState = state
	end
	state.active = false
	state.triggered = false
	state.token = (tonumber(state.token) or 0) + 1
end

NAmanage.AntiStaffAct = function(player, info)
	const state = NAStuff.AntiStaffState
	if type(state) ~= "table" or state.active ~= true or state.triggered == true then
		return false
	end

	state.triggered = true
	const token = tonumber(state.token) or 0
	local role = type(info) == "table" and tostring(info.Role or "Staff") or "Staff"
	if role == "" or role == "Guest" then
		role = "Staff"
	end
	const detectedName = nameChecker(player)

	if state.mode == "leave" then
		DoNotif("Staff detected: "..detectedName.." ("..role.."). Leaving server.", 6, "Anti Staff")
		local exited = false
		if cmd and type(cmd.run) == "function" then
			exited = pcall(function()
				cmd.run({"exit"})
			end)
		end
		if not exited then
			exited = pcall(function()
				game:Shutdown()
			end)
		end
		if not exited and LocalPlayer then
			pcall(function()
				LocalPlayer:Kick("\n\nAnti Staff\nStaff detected: "..detectedName.." ("..role..")\n")
			end)
		end
		return true
	end

	DoNotif("Staff detected: "..detectedName.." ("..role.."). Starting advanced serverhop.", 6, "Anti Staff")
	Spawn(function()
		local ok, success, reason = pcall(function()
			if type(NAmanage.ServerhopAdvanced) ~= "function" then
				return false, "advanced serverhop is unavailable"
			end
			return NAmanage.ServerhopAdvanced()
		end)
		if not ok then
			reason = success
			success = false
		end
		if success ~= true and state.active == true and (tonumber(state.token) or 0) == token then
			state.triggered = false
			DoNotif("Advanced serverhop failed"..(reason and (": "..tostring(reason)) or "")..". Monitoring remains enabled.", 5, "Anti Staff")
		end
	end)
	return true
end

NAmanage.AntiStaffHandlePlayer = function(player)
	if typeof(player) ~= "Instance" or not player:IsA("Player") or not player.Parent then
		return false
	end
	if player == LocalPlayer and NAStuff.StaffwatchIgnoreLocal ~= false then
		return false
	end
	local ok, info = pcall(groupRole, player)
	if not ok or type(info) ~= "table" or info.IsStaff ~= true then
		return false
	end
	return NAmanage.AntiStaffAct(player, info)
end

NAmanage.AntiStaffStart = function(mode)
	const normalizedMode = NAmanage.AntiStaffNormalizeMode(mode)
	if not normalizedMode then
		DoNotif("Usage: antistaff [leave/serverhop]", 4, "Anti Staff")
		return false
	end

	NAmanage.AntiStaffStop()
	if game.CreatorType ~= Enum.CreatorType.Group then
		DoNotif("Game is not owned by a Group", 4, "Anti Staff")
		return false
	end

	const state = NAStuff.AntiStaffState
	state.active = true
	state.mode = normalizedMode
	state.triggered = false
	state.token = (tonumber(state.token) or 0) + 1
	const token = state.token

	NAlib.connect("antiStaffNotifier", Services.Players.PlayerAdded:Connect(function(player)
		Spawn(function()
			if state.active == true and state.token == token and state.triggered ~= true then
				NAmanage.AntiStaffHandlePlayer(player)
			end
		end)
	end))

	Spawn(function()
		const players = Services.Players:GetPlayers()
		for index, player in players do
			if state.active ~= true or state.token ~= token or state.triggered == true then
				return
			end
			if NAmanage.AntiStaffHandlePlayer(player) then
				return
			end
			if index % 2 == 0 or IsOnMobile == true then
				Wait()
			end
		end
		if state.active == true and state.token == token and state.triggered ~= true then
			const actionText = normalizedMode == "leave" and "leave" or "advanced serverhop"
			DoNotif("Enabled - will "..actionText.." when staff is detected.", 4, "Anti Staff")
		end
	end)
	return true
end

cmd.register({
	name = "antistaff",
	aliases = { "staffescape", "staffavoid" },
	description = "Automatically leave or advanced-serverhop when staff is detected",
	usage = "antistaff [leave/serverhop] (staffescape, staffavoid)",
	callback = function(mode)
		NAmanage.AntiStaffStart(mode)
	end,
})

cmd.register({
	name = "unantistaff",
	aliases = { "unstaffescape", "unstaffavoid" },
	description = "Disable automatic staff avoidance",
	usage = "unantistaff (unstaffescape, unstaffavoid)",
	callback = function()
		NAmanage.AntiStaffStop()
		DoNotif("Disabled", 3, "Anti Staff")
	end,
})

NAStuff.Rewind = NAStuff.Rewind or {
	Enabled = false;
	Key = Enum.KeyCode.R;
	Seconds = 120;
	Speed = 1;
	History = {};
	IsRewinding = false;
	LastCharacter = nil;
	AnimateOriginalDisabled = nil;
	MobileActive = false;
	MobileGui = nil;
	MobileButton = nil;
}

NAmanage.RewindState = function()
	local state = NAStuff.Rewind
	if type(state) ~= "table" then
		state = {}
		NAStuff.Rewind = state
	end
	state.Key = typeof(state.Key) == "EnumItem" and state.Key or Enum.KeyCode.R
	state.Seconds = math.max(1, math.min(600, math.floor(tonumber(state.Seconds) or 120)))
	state.Speed = math.max(1, math.min(60, math.floor(tonumber(state.Speed) or 1)))
	if type(state.History) ~= "table" then
		state.History = {}
	end
	state.MobileActive = state.MobileActive == true
	if typeof(state.MobileGui) ~= "Instance" then
		state.MobileGui = nil
	end
	if typeof(state.MobileButton) ~= "Instance" then
		state.MobileButton = nil
	end
	return state
end

NAmanage.RewindSyncMobileButton = function()
	const state = NAmanage.RewindState()
	const button = state.MobileButton
	if typeof(button) ~= "Instance" or not button.Parent then
		return
	end
	const active = state.MobileActive == true
	button.Text = active and "STOP" or "REW"
	button.BackgroundColor3 = active and Color3.fromRGB(0, 170, 0) or Color3.fromRGB(30, 30, 30)
end

NAmanage.RewindSetMobileActive = function(active)
	const state = NAmanage.RewindState()
	state.MobileActive = active == true and state.Enabled == true
	NAmanage.RewindSyncMobileButton()
end

NAmanage.RewindDestroyMobileButton = function()
	const state = NAmanage.RewindState()
	state.MobileActive = false
	if typeof(state.MobileGui) == "Instance" then
		pcall(function()
			state.MobileGui:Destroy()
		end)
	end
	state.MobileGui = nil
	state.MobileButton = nil
end

-- PART 11
NAmanage.RewindCreateMobileButton = function()
	if not IsOnMobile then
		return
	end
	NAmanage.RewindDestroyMobileButton()
	const state = NAmanage.RewindState()
	const gui = InstanceNew("ScreenGui")
	const button = InstanceNew("TextButton")
	const corner = InstanceNew("UICorner")
	corner.CornerRadius = UDim.new(0, 6)
	const aspect = InstanceNew("UIAspectRatioConstraint")

	NAgui.NaProtectUI(gui)
	gui.Name = "NARewindMobile"
	gui.ResetOnSpawn = false

	button.Name = "RewindMainButton"
	button.Parent = gui
	button.BackgroundColor3 = Color3.fromRGB(30, 30, 30)
	button.BackgroundTransparency = 0.1
	button.Position = UDim2.new(0.8, 0, 0.5, 0)
	button.Size = UDim2.new(0.08, 0, 0.1, 0)
	button.Font = Enum.Font.GothamBold
	button.Text = "REW"
	button.TextColor3 = Color3.fromRGB(255, 255, 255)
	button.TextSize = 18
	button.TextWrapped = true
	button.Active = true
	button.TextScaled = true

	corner.CornerRadius = UDim.new(0, 6)
	corner.Parent = button

	aspect.Parent = button
	aspect.AspectRatio = 1

	state.MobileGui = gui
	state.MobileButton = button

	MouseButtonFix(button, function()
		if state.Enabled ~= true then
			return
		end
		NAmanage.RewindSetMobileActive(state.MobileActive ~= true)
	end)

	NAgui.draggerV2(button)
	NAmanage.RewindSyncMobileButton()
end

NAmanage.RewindClearHistory = function()
	const state = NAmanage.RewindState()
	if type(state.History) == "table" then
		table.clear(state.History)
	else
		state.History = {}
	end
end

NAmanage.RewindSetAnimate = function(char, disabled)
	const state = NAmanage.RewindState()
	const animate = char and char:FindFirstChild("Animate")
	if not animate then
		return
	end
	if disabled then
		if state.AnimateOriginalDisabled == nil then
			local ok, value = pcall(function()
				return animate.Disabled
			end)
			state.AnimateOriginalDisabled = ok and value or false
		end
		pcall(function()
			if animate.Disabled ~= true then
				animate.Disabled = true
			end
		end)
		return
	end
	local restoreValue = state.AnimateOriginalDisabled
	state.AnimateOriginalDisabled = nil
	if restoreValue == nil then
		restoreValue = false
	end
	pcall(function()
		if animate.Disabled ~= restoreValue then
			animate.Disabled = restoreValue
		end
	end)
end

NAmanage.RewindStopPlayback = function(char, hum)
	const state = NAmanage.RewindState()
	state.IsRewinding = false
	NAmanage.RewindSetAnimate(char or getChar(), false)
	if hum then
		local ok, tracks = pcall(function()
			return hum:GetPlayingAnimationTracks()
		end)
		if ok and type(tracks) == "table" then
			for _, track in tracks do
				pcall(function()
					track:AdjustSpeed(1)
				end)
				pcall(function()
					track:Stop(0.1)
				end)
			end
		end
	end
end

NAmanage.RewindCaptureAnimations = function(hum)
	const currentAnims = {}
	if not hum then
		return currentAnims
	end
	local ok, tracks = pcall(function()
		return hum:GetPlayingAnimationTracks()
	end)
	if not (ok and type(tracks) == "table") then
		return currentAnims
	end
	for _, track in tracks do
		local weight = 0
		pcall(function()
			weight = tonumber(track.WeightCurrent) or 0
		end)
		if weight > 0 then
			Insert(currentAnims, {
				Track = track;
				Position = track.TimePosition;
				Weight = weight;
			})
		end
	end
	return currentAnims
end

NAmanage.RewindApplySnapshot = function(state, char, root, snapshot)
	if type(snapshot) ~= "table" or typeof(snapshot.CFrame) ~= "CFrame" then
		return
	end
	local currentCF
	local okPivot, pivot = pcall(function()
		return char:GetPivot()
	end)
	if okPivot and typeof(pivot) == "CFrame" then
		currentCF = pivot
	else
		currentCF = root and root.CFrame or snapshot.CFrame
	end
	const targetCF = currentCF:Lerp(snapshot.CFrame, 0.5)
	if NAmanage.UG_pivotModel then
		NAmanage.UG_pivotModel(char, targetCF)
	elseif root then
		pcall(function()
			root.CFrame = targetCF
		end)
	end
	if root then
		pcall(function()
			if root.AssemblyLinearVelocity ~= Vector3.zero then
				root.AssemblyLinearVelocity = Vector3.zero
			end
		end)
		pcall(function()
			if root.AssemblyAngularVelocity ~= Vector3.zero then
				root.AssemblyAngularVelocity = Vector3.zero
			end
		end)
	end
	if type(snapshot.Anims) == "table" then
		for _, animData in snapshot.Anims do
			const track = type(animData) == "table" and animData.Track or nil
			if track then
				pcall(function()
					if not track.IsPlaying then
						track:Play(0)
					end
				end)
				pcall(function()
					track.TimePosition = animData.Position or 0
				end)
				pcall(function()
					track:AdjustSpeed(0)
				end)
				pcall(function()
					track:AdjustWeight(animData.Weight or 1)
				end)
			end
		end
	end
end

NAmanage.RewindStep = function()
	const state = NAmanage.RewindState()
	if state.Enabled ~= true then
		NAlib.disconnect("NARewind")
		return
	end

	const char = getChar()
	const root = char and getRoot(char)
	const hum = char and getHum(char)

	if char ~= state.LastCharacter then
		NAmanage.RewindStopPlayback(state.LastCharacter, nil)
		NAmanage.RewindSetMobileActive(false)
		state.LastCharacter = char
		state.IsRewinding = false
		state.AnimateOriginalDisabled = nil
		NAmanage.RewindClearHistory()
	end

	local dead = false
	if hum and hum:IsA("Humanoid") then
		local okHealth, health = pcall(function()
			return hum.Health
		end)
		dead = okHealth and tonumber(health) and health <= 0
	end

	if not (char and root and hum) or dead then
		if state.IsRewinding then
			NAmanage.RewindStopPlayback(char, hum)
		end
		NAmanage.RewindSetMobileActive(false)
		NAmanage.RewindClearHistory()
		return
	end

	const inputActive = NAmanage.isAnyNAInputActive and NAmanage.isAnyNAInputActive()
	local keyDown = state.MobileActive == true
	if not keyDown and not inputActive then
		local okKey, down = pcall(function()
			return __lt.cm("UserInputService", "IsKeyDown", state.Key)
		end)
		keyDown = okKey and down == true
	end

	if keyDown then
		state.IsRewinding = true
		NAmanage.RewindSetAnimate(char, true)
		local foundSnapshot = false
		for i = 1, state.Speed do
			const snapshot = table.remove(state.History, #state.History)
			if not snapshot then
				break
			end
			foundSnapshot = true
			if i == state.Speed or #state.History == 0 then
				NAmanage.RewindApplySnapshot(state, char, root, snapshot)
			end
		end
		if not foundSnapshot and state.MobileActive == true then
			NAmanage.RewindSetMobileActive(false)
			NAmanage.RewindStopPlayback(char, hum)
		end
		return
	end

	if state.IsRewinding then
		NAmanage.RewindStopPlayback(char, hum)
	end

	local cf
	local okPivot, pivot = pcall(function()
		return char:GetPivot()
	end)
	if okPivot and typeof(pivot) == "CFrame" then
		cf = pivot
	else
		cf = root.CFrame
	end

	Insert(state.History, {
		CFrame = cf;
		Anims = NAmanage.RewindCaptureAnimations(hum);
	})

	const maxStored = math.max(1, state.Seconds * 60)
	while #state.History > maxStored do
		table.remove(state.History, 1)
	end
end

NAmanage.RewindStart = function(secondsArg)
	const state = NAmanage.RewindState()
	const seconds = tonumber(secondsArg)
	if seconds then
		state.Seconds = math.max(1, math.min(600, math.floor(seconds)))
	end
	state.Enabled = true
	state.IsRewinding = false
	state.AnimateOriginalDisabled = nil
	state.MobileActive = false
	NAmanage.RewindClearHistory()
	NAlib.reconnect("NARewind", Services.RunService.Heartbeat:Connect(NAmanage.RewindStep))
	if IsOnMobile then
		NAmanage.RewindCreateMobileButton()
		DebugNotif(("Rewind enabled. Tap REW to start or stop rewinding. Capture: %ds. Speed: %dx."):format(state.Seconds, state.Speed), 4, "Rewind")
	else
		NAmanage.RewindDestroyMobileButton()
		DebugNotif(("Rewind enabled. Hold %s to rewind. Capture: %ds. Speed: %dx."):format(state.Key.Name, state.Seconds, state.Speed), 4, "Rewind")
	end
end

NAmanage.RewindStop = function(showNotif)
	const state = NAmanage.RewindState()
	state.Enabled = false
	NAmanage.RewindSetMobileActive(false)
	NAmanage.RewindStopPlayback(getChar(), getHum())
	NAmanage.RewindClearHistory()
	NAmanage.RewindDestroyMobileButton()
	NAlib.disconnect("NARewind")
	if showNotif ~= false then
		DebugNotif("Rewind disabled.", 3, "Rewind")
	end
end

