--Mobile Commands for the screen
if IsOnMobile then
	originalIO.setScreenOrientation=function(target)
		if target == "Default" then
			PlrGui.ScreenOrientation = Services.StarterGui.ScreenOrientation
			return "Default"
		end
		if typeof(target) == "EnumItem" then
			PlrGui.ScreenOrientation = target
			return target.Name
		end
	end

	originalIO.screenOrientationButtons=function()
		const buttons = {}
		Insert(buttons, {
			Text = "Default",
			Callback = function()
				originalIO.setScreenOrientation("Default")
			end
		})
		for _, so in Enum.ScreenOrientation:GetEnumItems() do
			Insert(buttons, {
				Text = so.Name,
				Callback = function()
					originalIO.setScreenOrientation(so)
				end
			})
		end
		return buttons
	end

	originalIO.screenOrientationCommand=function(...)
		const args = {...}
		const target = args[1]
		const buttons = originalIO.screenOrientationButtons()
		if target and target ~= "" then
			const q = Lower(tostring(target))
			local hit
			const hits = {}
			for _, btn in buttons do
				if Lower(btn.Text) == q then
					hit = btn
					break
				end
				if Find(Lower(btn.Text), q, 1, true) then
					Insert(hits, btn)
				end
			end
			if not hit and #hits == 1 then
				hit = hits[1]
			end
			if hit then
				hit.Callback()
				DebugNotif("ScreenOrientation set to "..hit.Text, 3)
			elseif #hits > 1 then
				const names = {}
				for i = 1, #hits do
					names[i] = hits[i].Text
				end
				DebugNotif("Multiple ScreenOrientation matches: "..Concat(names, ", "), 3)
			else
				DebugNotif("No matching ScreenOrientation for: "..tostring(target), 3)
			end
		else
			Window({
				Title = "Screen Orientation Options",
				Buttons = buttons
			})
		end
	end

	cmd.register({
		name = "screenorientation",
		aliases = { "screenorient", "scrorientation", "scrorient", "screenrotation", "scrrotation", "scrrot", "so" },
		description = "Manage ScreenOrientation",
		usage = "screenorientation [type]",
		callback = originalIO.screenOrientationCommand,
	})

	cmd.register({
		name = "sensorrotationscreen",
		aliases = { "sensorscreen", "senscreen" },
		description = "Changes ScreenOrientation to Sensor",
		callback = function()
			originalIO.screenOrientationCommand("Sensor")
		end,
	})

	cmd.register({
		name = "landscaperotationscreen",
		aliases = { "landscapescreen", "landscreen" },
		description = "Changes ScreenOrientation to Landscape Sensor",
		callback = function()
			originalIO.screenOrientationCommand("LandscapeSensor")
		end,
	})

	cmd.register({
