cmd.register({
	name = "cancelteleportloop",
	aliases = { "canceltploop", "loopcancelteleport", "loopcanceltp" },
	description = "Repeatedly cancels in-progress teleport",
	usage = "cancelteleportloop [interval]",
	requiresArguments = true,
	callback = function(interval)
		local tickRate = tonumber(interval)
		if not tickRate then
			tickRate = 0
		end
		tickRate = math.clamp(tickRate, 0, 2)

		NAlib.disconnect("cancelteleport_loop")
		local elapsed = tickRate
		NAlib.connect("cancelteleport_loop", Services.RunService.Heartbeat:Connect(function(dt)
			elapsed += (tonumber(dt) or 0)
			if elapsed < tickRate then
				return
			end
			elapsed = 0
			pcall(function()
				__lt.cm("TeleportService", "TeleportCancel")
			end)
			if type(NAmanage.TeleportGui_Cancel) == "function" and ((NAmanage.SubplaceViewer and NAmanage.SubplaceViewer.teleportGui) or NAStuff.teleportTransition) then
				pcall(NAmanage.TeleportGui_Cancel)
			end
		end))

		DoNotif("CancelTeleport loop enabled ("..tostring(tickRate).."s interval).",2)
	end,
})

