cmd.register({
	name = "loopdroptools",
	aliases = { "loopdrop", "ldtools", "ldtls" },
	description = "Loop drops your tools",
	callback = function()
		if loopdrop then
			DebugNotif("Loop drop already running", 2)
			return
		end

		loopdrop = true
		DebugNotif("Started loop dropping tools", 2)
		SpawnCall(function()
			while loopdrop do
				if not NAmanage.dropBusy then
					NAmanage.dropBusy = true
					local ok, count = pcall(function()
						return NAmanage.dropAllToolsSafe(function()
							NAmanage.dropBusy = false
						end)
					end)

					if not ok or not count or count <= 0 then
						NAmanage.dropBusy = false
					end
				end
				Wait(0.2)
			end
			NAmanage.dropBusy = false
			DebugNotif("Stopped loop dropping tools", 2)
		end)
	end,
})

cmd.register({
	name = "unloopdroptools",
	aliases = { "unloopdrop", "unldtools", "unldtls" },
	description = "Stops loop dropping tools",
	callback = function()
		if not loopdrop then
			DebugNotif("Loop drop is not running", 2)
			return
		end
		loopdrop = false
	end,
})

