		if not ok and (prop == "Decoration" or prop == "RenderFidelity") and type(sethiddenproperty) == "function" then
			ok = pcall(sethiddenproperty, obj, prop, value)
		end
		return ok
	end
	const function change(obj, prop, value)
		const ok, old = read(obj, prop)
		if not ok or old == value then return false end
		if not write(obj, prop, value) then return false end
		local props = saved[obj]
		if not props then props = {}; saved[obj] = props end
		if props[prop] == nil then props[prop] = old end
		return true
	end
	const function unwatch(obj)
		const props = watches[obj]
		if props then
			for _, conn in props do pcall(function() conn:Disconnect() end) end
			watches[obj] = nil
		end
	end
	const function watch(obj, prop, value)
		if not option("keepEffectsOff", false) then return end
		local props = watches[obj]
		if not props then props = {}; watches[obj] = props end
		if props[prop] then return end
		const mark = rev
		local ok, conn = pcall(function()
			return obj:GetPropertyChangedSignal(prop):Connect(function()
				if active and mark == rev then
					const good, current = read(obj, prop)
					if good and current ~= value then change(obj, prop, value) end
				end
			end)
		end)
		if ok then props[prop] = conn end
	end
	const function ignore(obj)
		if not option("ignoreSelf", true) and not option("ignorePlayers", false) then return false end
		local node = obj
		while node do
			const plr = chars[node]
			if plr then
				return if plr == LocalPlayer then option("ignoreSelf", true) else option("ignorePlayers", false)
			end
			node = node.Parent
		end
		return false
	end
	const function apply(obj)
		if not active or not obj.Parent or ignore(obj) then return end
		const kind = obj.ClassName
		if obj:IsA("BasePart") then
			if option("simplifyMaterials", true) then
				change(obj, "Material", Enum.Material.Plastic)
				change(obj, "MaterialVariant", "")
			end
			if option("disableShadows", true) then change(obj, "CastShadow", false) end
			if option("zeroReflectance", true) then change(obj, "Reflectance", 0) end
			if obj:IsA("MeshPart") or obj:IsA("PartOperation") then
				if option("optimizeMeshes", true) then change(obj, "RenderFidelity", Enum.RenderFidelity.Performance) end
				if kind == "MeshPart" and option("stripTextures", true) then change(obj, "TextureID", "") end
			end
		elseif kind == "ParticleEmitter" or kind == "Trail" or kind == "Beam" or kind == "Fire" or kind == "Smoke" or kind == "Sparkles" then
			if option("stripParticles", true) then
				change(obj, "Enabled", false)
				watch(obj, "Enabled", false)
				if kind == "ParticleEmitter" or kind == "Trail" then pcall(function() obj:Clear() end) end
			elseif kind == "ParticleEmitter" then
				const rate = math.clamp(tonumber(cfg.particleRate) or 0, 0, 1000)
				if rate > 0 and obj.Rate > rate then change(obj, "Rate", rate) end
			end
		elseif obj:IsA("Light") then
			if option("stripLights", true) then change(obj, "Enabled", false); watch(obj, "Enabled", false) end
			if option("disableShadows", true) then change(obj, "Shadows", false) end
		elseif obj:IsA("PostEffect") then
			if option("stripPostFx", true) then change(obj, "Enabled", false); watch(obj, "Enabled", false) end
		elseif kind == "Highlight" then
			if option("stripHighlights", true) then change(obj, "Enabled", false); watch(obj, "Enabled", false) end
		elseif kind == "Atmosphere" then
			if option("stripAtmosphere", true) then
				for _, prop in { "Density", "Haze", "Glare" } do change(obj, prop, 0) end
			end
		elseif kind == "SurfaceAppearance" then
			if option("stripSurfaceAppearance", true) then
				const parent = obj.Parent
				if write(obj, "Parent", nil) then held[obj] = parent end
			end
		elseif kind == "Texture" then
			if option("stripTextures", true) then change(obj, "Transparency", 1) end
		elseif kind == "Decal" then
			if option("stripDecals", true) then change(obj, "Transparency", 1) end
		elseif kind == "SpecialMesh" then
			if option("stripTextures", true) then change(obj, "TextureId", "") end
		elseif kind == "Explosion" then
			if option("stripExplosions", true) then change(obj, "Visible", false) end
		elseif kind == "BillboardGui" or kind == "SurfaceGui" then
			if option("disable3dUi", false) then change(obj, "Enabled", false); watch(obj, "Enabled", false) end
		end
	end
	const function enqueue(obj)
		if not active or seen[obj] == rev or queued[obj] then return end
		if not kinds[obj.ClassName] and not obj:IsA("BasePart") and not obj:IsA("PostEffect") then return end
		queued[obj] = true
		tail += 1
		queue[tail] = obj
		if running then return end
		running = true
		const mark = rev
		Defer(function()
			local count, at = 0, os.clock()
			while active and mark == rev and head <= tail do
				const item = queue[head]
				queue[head] = nil
				head += 1
				queued[item] = nil
				if seen[item] ~= mark then seen[item] = mark; pcall(apply, item) end
				count += 1
				if count >= 64 or os.clock() - at >= 0.002 then
					Wait()
					count, at = 0, os.clock()
				end
			end
			if mark == rev then queue = {}; head, tail, running = 1, 0, false end
		end)
	end
	const function scan(root)
		if not root then return end
		const mark = rev
		const token = { cancelled = false }
		scans[#scans + 1] = token
		const function finish()
			const index = table.find(scans, token)
			if index then table.remove(scans, index) end
		end
		Defer(function()
			if not active or mark ~= rev then finish(); return end
			local ok, list = pcall(function() return root:QueryDescendants(selector) end)
			if not ok then
				NAmanage.ForEachDescendantYield(root, function(obj)
					if active and mark == rev then enqueue(obj) end
				end, { yieldEvery = 64; cancelToken = token })
				finish()
				return
			end
			for i = 1, #list do
				if not active or mark ~= rev then break end
				enqueue(list[i])
				list[i] = nil
				if i % 128 == 0 then Wait() end
			end
			finish()
		end)
	end
	const function stop()
		if restoring and not NAStuff._unloading then return end
		active = false
		rev += 1
		for _, token in scans do token.cancelled = true end
		scans = {}
		queue = {}; queued = setmetatable({}, { __mode = "k" }); head, tail, running = 1, 0, false
		for _, conn in cons do pcall(function() conn:Disconnect() end) end
		cons = {}
		for plr, rec in players do
			rec.conn:Disconnect()
			players[plr] = nil
		end
		for obj in watches do unwatch(obj) end
		restoring = true
		local count, at = 0, os.clock()
		for obj, props in saved do
			for prop, value in props do
				const ok, current = read(obj, prop)
				if ok and current ~= value then write(obj, prop, value) end
			end
			saved[obj] = nil
			count += 1
			if (count >= 64 or os.clock() - at >= 0.002) and not NAStuff._unloading then
				Wait(); count, at = 0, os.clock()
			end
		end
		for obj, parent in held do
			if not obj.Parent and parent.Parent then write(obj, "Parent", parent) end
			held[obj] = nil
		end
		seen = setmetatable({}, { __mode = "k" })
		chars = setmetatable({}, { __mode = "k" })
		restoring = false
	end
	const function start()
		while restoring and _na_env.NA_FPS_ACTIVE and not NAStuff._unloading do Wait() end
		if active or not _na_env.NA_FPS_ACTIVE or NAStuff._unloading then return end
		cfg = table.clone(NAStuff.FPSBoostOptions or {})
		rev += 1
		active = true
		const function player(plr)
			if players[plr] then return end
			const rec = { char = plr.Character }
			if rec.char then chars[rec.char] = plr end
			rec.conn = plr.CharacterAdded:Connect(function(char)
				if rec.char then chars[rec.char] = nil end
				rec.char = char
				chars[char] = plr
			end)
			players[plr] = rec
		end
		for _, plr in Services.Players:GetPlayers() do player(plr) end
		connect(Services.Players.PlayerAdded, player)
		connect(Services.Players.PlayerRemoving, function(plr)
			const rec = players[plr]
			if rec then
				rec.conn:Disconnect()
				if rec.char then chars[rec.char] = nil end
				players[plr] = nil
			end
		end)
		if option("lowQuality", true) then
			pcall(function() change(settings().Rendering, "QualityLevel", Enum.QualityLevel.Level01) end)
			pcall(function() change(__lt.cv(UserSettings():GetService("UserGameSettings")), "SavedQualityLevel", Enum.SavedQualitySetting.QualityLevel1) end)
		end
		if option("disableShadows", true) then change(Services.Lighting, "GlobalShadows", false) end
		const terrain = world:FindFirstChildOfClass("Terrain")
		if terrain then
			if option("disableGrass", true) then change(terrain, "Decoration", false) end
			if option("simpleWater", true) then
				for _, prop in { "WaterWaveSize", "WaterWaveSpeed", "WaterReflectance" } do change(terrain, prop, 0) end
			end
		end
		if option("liveUpdates", true) then
			cons[#cons + 1] = NAmanage.descSub(world, { added = enqueue; classNames = classes })
			cons[#cons + 1] = NAmanage.descSub(Services.Lighting, { added = enqueue; classNames = classes })
		end
		cons[#cons + 1] = NAmanage.descSub(world, { removing = unwatch; classNames = classes })
		cons[#cons + 1] = NAmanage.descSub(Services.Lighting, { removing = unwatch; classNames = classes })
		local camConn
		const function camera()
			if camConn then camConn:Disconnect(); camConn = nil end
			const cam = world.CurrentCamera
			if cam and not cam:IsDescendantOf(world) then
				if option("liveUpdates", true) then camConn = cam.DescendantAdded:Connect(enqueue) end
				scan(cam)
			end
		end
		connect(world:GetPropertyChangedSignal("CurrentCamera"), camera)
		cons[#cons + 1] = { Disconnect = function() if camConn then camConn:Disconnect(); camConn = nil end end }
		camera()
		scan(world)
		scan(Services.Lighting)
	end
	_na_env.NA_FPS_UNHOOK = function()
		_na_env.NA_FPS_ACTIVE = false
		stop()
	end
	_na_env.NA_FPS_REFRESH = function()
		if not _na_env.NA_FPS_ACTIVE then return end
		stop()
		start()
	end
	cmd.register({
		name = "fpsbooster",
		aliases = { "lowgraphics", "boostfps", "lowg", "antilag" },
		description = "Toggle low graphics using your FPSBooster settings",
		callback = function()
			_na_env.NA_FPS_ACTIVE = not _na_env.NA_FPS_ACTIVE
			if _na_env.NA_FPS_ACTIVE then start() else stop() end
			DebugNotif("FPSBooster: "..(_na_env.NA_FPS_ACTIVE and "ON" or "OFF"), 3)
		end,
	})
end


NAStuff.annoyLoop = false

cmd.register({
	name = "annoy",
	description = "Annoys the given player or NPC",
	usage = "annoy <player|npc:filter>",
	requiresArguments = true,
	callback = function(...)
		if NAStuff.annoyLoop then
			DoNotif("Already annoying someone. Use :unannoy first.", 3)
			return
		end

		NAStuff.annoyLoop = false
		Wait(0.2)
		NAStuff.annoyLoop = true

		const user = ...
		const targets = getPlr(user)

		if #targets == 0 then
			DoNotif("No target found.", 3)
			return
		end

		const target = targets[1]
		const initialTargetChar = NAmanage.PlayerArgChar(target)
		if not initialTargetChar or not getRoot(initialTargetChar) then
			DoNotif("Target has no character or root part.", 3)
			annoyLoop = false
			return
		end

		local myChar = getChar()
		local myRoot = myChar and getRoot(myChar)
		const originalCFrame = myRoot and (NAmanage.UG_clientCFrame(myRoot) or myRoot.CFrame)

		if not myRoot then
			DoNotif("Your character has no root part.", 3)
			annoyLoop = false
			return
		end

		math.randomseed(tick())

		repeat
			Wait(0.05)

			const targetChar = NAmanage.PlayerArgChar(target)
			const targetRoot = targetChar and getRoot(targetChar)
			myChar = getChar()
			myRoot = myChar and getRoot(myChar)

			if not targetRoot or not myRoot then
				break
			end

			const offset = Vector3.new(math.random(-3,3), math.random(0,2), math.random(-3,3))
			NAmanage.UG_setClientCFrame(myRoot, targetRoot.CFrame + offset)

			Services.RunService.RenderStepped:Wait()
		until not NAStuff.annoyLoop

		if myRoot and originalCFrame then
			NAmanage.UG_setClientCFrame(myRoot, originalCFrame)
		end
	end,
})

cmd.register({
	name = "unannoy",
	description = "Stops the annoy command",
	callback = function()
		NAStuff.annoyLoop = false
	end,
})

NAmanage.IsPlayerOrNPCPart = NAmanage.IsPlayerOrNPCPart or function(inst)
	if typeof(inst) ~= "Instance" then
		return false, nil, nil
	end

	const model = NAmanage.RigFromPart(inst)
	if not model then
		return false, nil, nil
	end
	if model == NA_GRAB_BODY.getOverride() or __lt.cm("Players", "GetPlayerFromCharacter", model) then
		return true, "player", model
	end
	if CheckIfNPC(model) then
		return true, "npc", model
	end
	return true, "humanoid", model
end

cmd.register({
	name = "deleteinvisparts",
	aliases = { "deleteinvisibleparts", "dip" },
	description = "Deletes invisible parts",
	callback = function()
		local deleted = 0
		local skippedPlayers = 0
		local skippedNPCs = 0
		local skippedHumanoids = 0

		for _, v in NAmanage.QueryDescendants(Services.Workspace, "BasePart") do
			if v.Transparency == 1 and v.CanCollide then
				local skip, kind = NAmanage.IsPlayerOrNPCPart(v)
				if skip then
					if kind == "player" then
						skippedPlayers += 1
					elseif kind == "npc" then
						skippedNPCs += 1
					else
						skippedHumanoids += 1
					end
				else
					v:Destroy()
					deleted += 1
				end
			end
		end

		DoNotif(
			"Deleted "..tostring(deleted).." invisible part(s). Skipped "..
			tostring(skippedPlayers).." player, "..
			tostring(skippedNPCs).." NPC, "..
			tostring(skippedHumanoids).." humanoid part(s).",
			4
		)
	end,
})

NAStuff.shownParts = {}

cmd.register({
	name = "invisibleparts",
	aliases = { "invisparts" },
	description = "Shows invisible parts",
	callback = function()
		for _, v in NAmanage.QueryDescendants(Services.Workspace, "BasePart") do
			if v.Transparency == 1 then
				local alreadyShown = false
				for _, p in NAStuff.shownParts do
					if p == v then
						alreadyShown = true
						break
					end
				end
				if not alreadyShown then
					Insert(NAStuff.shownParts, v)
				end
				v.Transparency = 0
			end
		end
	end,
})

cmd.register({
	name = "uninvisibleparts",
	aliases = { "uninvisparts" },
	description = "Makes parts affected by invisparts return to normal",
	callback = function()
		for _, v in NAStuff.shownParts do
			if v and v:IsA("BasePart") then
				v.Transparency = 1
			end
		end
		table.clear(NAStuff.shownParts)
	end,
})

cmd.register({
	name = "datalimit",
	description = "Set outgoing bandwidth limit in KBps",
	usage = "datalimit <kbps>",
	requiresArguments = true,
	callback = function(value)
		const limit=tonumber(value)
		if not limit then
			DoNotif("Usage: datalimit <number>",2)
			return
		end
		const networkClient=SafeGetService("NetworkClient")
		if not networkClient then
			DoNotif("NetworkClient unavailable",3)
			return
		end
		local ok,err=pcall(function()
			__lt.cm("NetworkClient", "SetOutgoingKBPSLimit", limit)
		end)
		if ok then
			DoNotif("Outgoing limit set to "..tostring(limit).." kbps",2)
		else
			DoNotif("Failed to set limit: "..tostring(err),3)
		end
	end,
})

NAmanage.RemoveAdsCandidate = NAmanage.RemoveAdsCandidate or function(obj)
	if typeof(obj) ~= "Instance" then
		return false
	end
	const parent = obj:IsA("PackageLink") and obj.Parent or obj
	if not (parent and parent.Parent) then
		return false
	end
	local destroyTarget = nil
	if parent:FindFirstChild("ADpart") then
		destroyTarget = parent
	elseif parent:FindFirstChild("AdGuiAdornee") then
		destroyTarget = parent.Parent or parent
	end
	if not (destroyTarget and destroyTarget.Parent) then
		return false
	end
	pcall(function()
		destroyTarget:Destroy()
	end)
	return true
end

NAmanage.RemoveAdsScan = NAmanage.RemoveAdsScan or function()
	local count = 0
	for _, obj in NAmanage.QueryDescendants(Services.Workspace, "PackageLink") do
		if NAmanage.RemoveAdsCandidate(obj) then
			count += 1
		end
	end
	return count
end

cmd.register({
	name = "removeads",
	aliases = { "adblock" },
	description = "Removes billboard advertisements as they appear",
	usage = "removeads (adblock)",
	callback = function()
		if NAStuff._removeAdsLoop and NAStuff._removeAdsLoop.active then
			DoNotif("Remove Ads already enabled",2)
			return
		end
		const state={active=true}
		NAStuff._removeAdsLoop=state
		NAmanage.RemoveAdsScan()
		NAlib.disconnect("removeads_added")
		NAlib.connect("removeads_added", NAmanage.wsAdd(function(obj)
			if not (NAStuff._removeAdsLoop and NAStuff._removeAdsLoop.active) then
				NAlib.disconnect("removeads_added")
				return
			end
			if obj and obj:IsA("PackageLink") then
				NAmanage.RemoveAdsCandidate(obj)
			elseif obj and (obj.Name == "ADpart" or obj.Name == "AdGuiAdornee") then
				NAmanage.RemoveAdsCandidate(obj.Parent)
			end
		end))
		DoNotif("Remove Ads enabled",2)
	end,
})

cmd.register({
	name = "unremoveads",
	aliases = { "noadblock", "disableads" },
	description = "Stop removing billboard advertisements",
	usage = "unremoveads (noadblock,disableads)",
	callback = function()
		const state=NAStuff._removeAdsLoop
		if not state or not state.active then
			DoNotif("Remove Ads is not active",2)
			NAStuff._removeAdsLoop=nil
			return
		end
		state.active=false
		NAStuff._removeAdsLoop=nil
		NAlib.disconnect("removeads_added")
		DoNotif("Remove Ads disabled",2)
	end,
})

NAmanage.EngineSettings = NAmanage.EngineSettings or {}

NAmanage.EngineSettings.key = function(serviceName, propertyName)
	return tostring(serviceName or "").."."..tostring(propertyName or "")
end

NAmanage.EngineSettings.saved = function()
	return {}
end

NAmanage.EngineSettings.saveValue = function(serviceName, propertyName, value)
	return nil
end

NAmanage.EngineSettings.parseBool = function(value, default)
	if type(value) == "boolean" then
		return value
	end
	if value == nil or value == "" then
		return default ~= false
	end
	const text = Lower(tostring(value))
	if text == "true" or text == "1" or text == "on" or text == "yes" or text == "enable" or text == "enabled" then
		return true
	end
	if text == "false" or text == "0" or text == "off" or text == "no" or text == "disable" or text == "disabled" then
		return false
	end
	return default ~= false
end

NAmanage.EngineSettings.getService = function(serviceName)
	NAmanage.EngineSettings._serviceCache = type(NAmanage.EngineSettings._serviceCache) == "table" and NAmanage.EngineSettings._serviceCache or {}
	const key = tostring(serviceName or "")
	if NAmanage.EngineSettings._serviceCache[key] ~= nil then
		return NAmanage.EngineSettings._serviceCache[key] or nil
	end
	local ok, service = pcall(function()
		return __lt.cv(settings():GetService(serviceName))
	end)
	if ok and service then
		NAmanage.EngineSettings._serviceCache[key] = service
		return service
	end
	NAmanage.EngineSettings._serviceCache[key] = false
	return nil
end

NAmanage.EngineSettings.get = function(serviceName, propertyName, fallback)
	const service = NAmanage.EngineSettings.getService(serviceName)
	if not service then
		return fallback
	end
	local ok, value = pcall(function()
		return service[propertyName]
	end)
	if ok then
		return value
	end
	return fallback
end

NAmanage.EngineSettings.set = function(serviceName, propertyName, value, label, silent)
	const service = NAmanage.EngineSettings.getService(serviceName)
	label = label or (serviceName.."."..propertyName)
	if not service then
		if not silent then
			DoNotif(serviceName.." unavailable", 3)
		end
		return false
	end
	local ok, err = pcall(function()
		service[propertyName] = value
	end)
	if ok then
		if not silent then
			DoNotif(label.." set to "..tostring(value), 2)
		end
		return true
	end
	if not silent then
		DoNotif("Failed to set "..label..": "..tostring(err), 3)
	end
	return false
end

NAmanage.EngineSettings.setAndSave = function(serviceName, propertyName, value, label, silent)
	return NAmanage.EngineSettings.set(serviceName, propertyName, value, label, silent)
end

NAmanage.EngineSettings.setBool = function(entry, value, silent)
	return NAmanage.EngineSettings.setAndSave(entry.service, entry.property, value == true, entry.label, silent)
end

NAmanage.EngineSettings.setNumber = function(entry, value, silent)
	local n = tonumber(value)
	if not n then
		if not silent then
			DoNotif("Usage: "..entry.usage, 2)
		end
		return false
	end
	if entry.integer then
		n = math.floor(n + 0.5)
	end
	if entry.min ~= nil then
		n = math.max(entry.min, n)
	end
	if entry.max ~= nil then
		n = math.min(entry.max, n)
	end
	return NAmanage.EngineSettings.setAndSave(entry.service, entry.property, n, entry.label, silent)
end

NAmanage.EngineSettings.boolCommands = {
	{ name = "renderstreamedregions", aliases = {"streamedregions"}, offName = "unrenderstreamedregions", offAliases = {"nostreamedregions"}, service = "NetworkSettings", property = "RenderStreamedRegions", label = "Render Streamed Regions" },
	{ name = "joinbreakdown", aliases = {"printjoinsize"}, offName = "unjoinbreakdown", offAliases = {"noprintjoinsize"}, service = "NetworkSettings", property = "PrintJoinSizeBreakdown", label = "Print Join Size Breakdown" },
	{ name = "streamquota", aliases = {"printstreamquota"}, offName = "unstreamquota", offAliases = {"noprintstreamquota"}, service = "NetworkSettings", property = "PrintStreamInstanceQuota", label = "Print Stream Instance Quota" },
	{ name = "animationassetdata", aliases = {"showanimationasset"}, offName = "unanimationassetdata", offAliases = {"noanimationasset"}, service = "NetworkSettings", property = "ShowActiveAnimationAsset", label = "Show Active Animation Asset" },
	{ name = "randomizejoinorder", aliases = {"randomjoinorder"}, offName = "unrandomizejoinorder", offAliases = {"norandomjoinorder"}, service = "NetworkSettings", property = "RandomizeJoinInstanceOrder", label = "Randomize Join Instance Order" },
