		usage = entry.usage or (entry.name.." [on/off]"),
		callback = function(value)
			NAmanage.EngineSettings.setBool(entry, NAmanage.EngineSettings.parseBool(value, true))
		end,
	})
	if entry.offName then
		cmd.register({
			name = entry.offName,
