cmd.register({
	name = "quality",
	aliases = { "qualitylevel" },
	description = "Manage rendering quality settings",
	usage = "quality <1-21>",
	callback = function(...)
		const args = {...}
		const target = args[1]
		const buttons = {}
		for _, ql in Enum.QualityLevel:GetEnumItems() do
			Insert(buttons, {
				Text = ql.Name,
				Callback = function()
					settings().Rendering.QualityLevel = ql
				end
			})
		end
		if target and target ~= "" then
			local key = tostring(target)
			local n = tonumber(key)
			if n then
				n = math.clamp(math.floor(n), 1, 21)
				key = Format("Level%02d", n)
			else
				const l = Lower(key)
				if l == "auto" or l == "automatic" then
					key = "Automatic"
				end
			end
			local found = false
			for _, btn in buttons do
				if Match(Lower(btn.Text), Lower(key)) then
					btn.Callback()
					DebugNotif("Quality set to "..btn.Text, 3)
					found = true
					break
				end
			end
			if not found then
				DebugNotif("No matching quality level for: "..target, 3)
			end
		else
			Window({
				Title = "Rendering Quality Options",
				Buttons = buttons
			})
		end
	end,
})

