cmd.register({
	name = "loopoof",
	description = "Loops everyone's character sounds (everyone can hear)",
	callback = function()
		oofing = true
		repeat Wait(0.1)
			for _, player in __lt.cm("Players", "GetPlayers") do
				const char = player.Character
				const head = getHead(char)
				if head then
					for _, child in head:GetChildren() do
						if child:IsA("Sound") and not child.Playing then
							child.Playing = true
						end
					end
				end
			end
		until not oofing
	end,
})

