		if not lp then
			pcall(function()
				antiAFKVIM:Destroy()
			end)
			return DebugNotif("Anti AFK failed: LocalPlayer missing")
		end

		NAStuff.antiAFKVIM = antiAFKVIM
		NAlib.connect("antiAFK", lp.Idled:Connect(antiAFKHandler))
