do
	local names, aliases, flips = {}, {}, {}
	for _, key in {
		"mode", "Binary", "CompressionMode", "CompressionLevel", "FilePath", "SafeMode", "KillAllScripts",
		"BoostFPS", "Object", "IsModel", "ShowStatus", "ReadMe", "Decompile", "SaveBytecode", "DecompileTimeout",
		"BytecodeTimeout", "DecompileIgnore", "SourceCache", "DecompileJobless", "scriptcache", "RecoverScriptsFromAssets",
		"IsolatePlayers", "IsolateLocalPlayer", "IsolateLocalPlayerCharacter", "IsolateStarterPlayer", "SavePlayerCharacters",
		"NilInstances", "ExtraInstances", "IgnoreList", "MaxDepth", "IgnoreSpecialProperties", "SpecialProperties", "AlternativeWritefile", "ResumeWrite", "Anonymous",
		"RiskyServicesDisabled", "AvoidFileOverwrite", "AntiIdle", "CopyToClipboard", "Callback", "IgnoreProperties",
		"IgnoreNotArchivable", "SaveNotCreatable", "NotCreatableFixes", "NilInstancesFixes", "IgnoreDefaultProperties",
		"IgnorePropertiesOfNotScriptsOnScriptsMode", "IgnoreDefaultPlayerScripts", "SaveCacheInterval", "SharedBinaryStrings",
		"TreatUnionsAsParts", "ShutdownWhenDone", "__DEBUG_MODE"
	} do names[key:lower()] = key end
	for key, value in {
		Clipboard = "CopyToClipboard"; DecompileScripts = "Decompile"; EmbedBytecode = "SaveBytecode";
		FileName = "FilePath"; IgnoreArchivable = "IgnoreNotArchivable"; IgnoreDefaultProps = "IgnoreDefaultProperties";
		InstancesBlacklist = "IgnoreList"; IsolatePlayerGui = "IsolateLocalPlayer"; Path = "FilePath";
		SaveCharacters = "SavePlayerCharacters"; SaveLocalPlayer = "IsolateLocalPlayer"; SaveNilInstances = "NilInstances";
		SaveNonCreatable = "SaveNotCreatable"; SavePlayerGui = "IsolateLocalPlayer"; SavePlayers = "IsolatePlayers";
		ShowProgress = "ShowStatus"; StatusText = "ShowStatus"; timeout = "DecompileTimeout"; Debug = "__DEBUG_MODE";
	} do aliases[key:lower()] = value end
	for key, value in {
		DisableCompression = "CompressionMode"; noscripts = "Decompile"; NullifyScripts = "Decompile";
		RemovePlayerCharacters = "SavePlayerCharacters"; RemovePlayers = "IsolatePlayers"; XML = "Binary";
	} do flips[key:lower()] = value end
	local function asBool(value, key)
		if type(value) == "boolean" then return value end
		if value == 1 then return true elseif value == 0 then return false end
		if type(value) == "string" then
			local text = value:match("^%s*(.-)%s*$"):lower()
			if text == "true" or text == "on" or text == "1" then return true end
			if text == "false" or text == "off" or text == "0" then return false end
		end
		error(key.." must be true or false", 0)
	end
	local function copy(value, seen)
		if type(value) ~= "table" then return value end
		seen = seen or {}
		if seen[value] then return seen[value] end
		local out = {}
		seen[value] = out
		for key, child in value do out[key] = copy(child, seen) end
		return out
	end
	NAmanage.MergeSaveOptions = function(target, source, loose)
		if source == nil then return target end
		if type(source) ~= "table" then error("Save options must be a table", 0) end
		local keys = {}
		for key in source do
			if type(key) ~= "string" then error("Save option names must be strings", 0) end
			keys[#keys + 1] = key
		end
		table.sort(keys)
		for pass = 1, 3 do
			for _, key in keys do
				local low = key:lower()
				local name = names[low] or aliases[low] or flips[low]
				if not name then
					if not loose then error("Unknown SynSaveInstance option: "..key, 0) end
				else
					local rank = names[low] and (key == name and 3 or 2) or 1
					if rank == pass then
						local value = source[key]
						if flips[low] then value = not asBool(value, key) end
						target[name] = copy(value)
					end
				end
			end
		end
		return target
	end
	NAmanage.FixSaveOptions = function(opts)
		for _, key in {
			"Binary", "SafeMode", "KillAllScripts", "BoostFPS", "IsModel", "ShowStatus", "ReadMe", "Decompile",
			"SaveBytecode", "DecompileJobless", "scriptcache", "RecoverScriptsFromAssets", "IsolatePlayers",
			"IsolateLocalPlayer", "IsolateLocalPlayerCharacter", "IsolateStarterPlayer", "SavePlayerCharacters",
			"NilInstances", "IgnoreSpecialProperties", "AlternativeWritefile", "AvoidFileOverwrite", "AntiIdle",
			"CopyToClipboard", "IgnoreNotArchivable", "SaveNotCreatable", "IgnoreDefaultProperties",
			"IgnorePropertiesOfNotScriptsOnScriptsMode", "IgnoreDefaultPlayerScripts", "SharedBinaryStrings",
			"TreatUnionsAsParts", "ShutdownWhenDone", "ResumeWrite"
		} do if opts[key] ~= nil then opts[key] = asBool(opts[key], key) end end
		for _, key in { "DecompileTimeout", "BytecodeTimeout", "CompressionLevel", "SaveCacheInterval" } do
			if opts[key] ~= nil then
				local num = tonumber(opts[key])
				if not num or num ~= num or math.abs(num) == math.huge then error(key.." must be a finite number", 0) end
				if key == "CompressionLevel" then num = math.clamp(math.floor(num), -7, 22)
				elseif key == "SaveCacheInterval" then num = math.max(0, math.floor(num))
				elseif num ~= -1 and num <= 0 then error(key.." must be greater than 0, or -1 to disable the timeout", 0) end
				opts[key] = num
			end
		end
		local comp = opts.CompressionMode
		if type(comp) == "string" then comp = comp:match("^%s*(.-)%s*$"):lower() end
		if comp == "none" or comp == "off" then comp = false elseif comp == true then comp = "zstd" end
		if comp ~= nil and comp ~= false and comp ~= "zstd" and comp ~= "lz4" then error("CompressionMode must be zstd, lz4, or false", 0) end
		opts.CompressionMode = comp
		if opts.mode ~= nil then
			if type(opts.mode) ~= "string" then error("mode must be a string", 0) end
			opts.mode = opts.mode:match("^%s*(.-)%s*$"):lower()
		end
		for _, key in { "DecompileIgnore", "IgnoreList", "IgnoreProperties", "ExtraInstances", "NotCreatableFixes", "NilInstancesFixes", "RiskyServicesDisabled" } do
			if opts[key] ~= nil and type(opts[key]) ~= "table" then error(key.." must be a list or map", 0) end
		end
		for key, kind in { Anonymous = "table"; __DEBUG_MODE = "function" } do
			if opts[key] ~= nil and type(opts[key]) ~= kind then opts[key] = asBool(opts[key], key) end
		end
		if opts.FilePath ~= nil and opts.FilePath ~= false and type(opts.FilePath) ~= "string" then error("FilePath must be a string or false", 0) end
		if opts.Object ~= nil and opts.Object ~= false and typeof(opts.Object) ~= "Instance" then error("Object must be an Instance or false", 0) end
		if opts.Callback ~= nil and opts.Callback ~= false and type(opts.Callback) ~= "function" then error("Callback must be a function or false", 0) end
		if opts.SourceCache ~= nil and opts.SourceCache ~= false and type(opts.SourceCache) ~= "table" then error("SourceCache must be a table or false", 0) end
		if opts.SpecialProperties ~= nil and opts.SpecialProperties ~= false and type(opts.SpecialProperties) ~= "table" then error("SpecialProperties must be a table or false", 0) end
		if opts.DecompileJobless then opts.scriptcache = true end
		return opts
	end
end

NAmanage.LoadSynSaveInstance = NAmanage.LoadSynSaveInstance or function()
	const cacheHost = _na_env or _G
	const cacheKey = "__na_synsaveinstance_v7"
	const cached = type(cacheHost) == "table" and rawget(cacheHost, cacheKey)
	if type(cached) == "function" then
		return cached
	end

	const loader = loadstring or load
	if type(loader) ~= "function" then
		error("SynSaveInstance loader unavailable")
	end

	const repoUrl = "https://ltseverydayyou.gitlab.io/UniversalSynSaveInstance/"
	const scriptName = "saveinstance"
	const url = repoUrl..scriptName..".luau?rev=service-roots"
	const chunkName = "@UniversalSynSaveInstance/"..scriptName..".luau"
	local loadErr
	const function compile(text)
		if type(text) ~= "string" or text == "" then
			loadErr = "the download returned empty source"
			return
		end
		text = text:gsub("^\239\187\191", "")
		if text:match("^%s*<") then
			error("SynSaveInstance returned HTML instead of Luau", 0)
		end
		text = text:gsub("local GLOBAL_ENV =", "local __ssiSR = ...\nlocal GLOBAL_ENV =", 1)
		text = text:gsub("local USSI = GLOBAL_ENV%.USSI", 'local USSI = type(GLOBAL_ENV.USSI) == "table" and GLOBAL_ENV.USSI or nil', 1)
		text = text:gsub('game:GetService%("CoreGui"%)', '__ssiSR.cs("CoreGui", __ssiSR.cr)')
		text = text:gsub('[Ss]cript[Cc]ache%s*=%s*"DecompileJobless"%s*,?', "", 1)
		text = text:gsub("local DecompileJobless = OPTIONS%.DecompileJobless%s*\n", "local DecompileJobless = OPTIONS.DecompileJobless == true\n", 1)
		local clean = [[
			if not DecompileJobless and type(ldeccache) == "table" then
				for key, code in ldeccache do
					if type(code) == "string" and code:match("^%s*%-%-%s*Not found in already decompiled ScriptCache%s*$") then
						ldeccache[key] = nil
					end
				end
			end
		]]
		text = text:gsub("(local ldeccache = ScriptCache and USSI%.ScriptCache)", function(line) return line.."\n"..clean end, 1)
		text = text:gsub("(local ldeccache = GLOBAL_ENV%.USSI_scriptcache)", function(line) return line.."\n"..clean end, 1)
		text = text:gsub("StatusGui%.Parent%s*=%s*global_container%.gethui%(%s*%)", [[
			local ok, hui = pcall(global_container.gethui)
			if ok and typeof(hui) == "Instance" then
				StatusGui.Parent = hui
			else
				local CoreGui = __ssiSR.cs("CoreGui", __ssiSR.cr)
				StatusGui.Parent = CoreGui:FindFirstChild("RobloxGui") or CoreGui
			end
		]], 1)
		local patched
		text, patched = text:gsub("\nend%s*\nreturn synsaveinstance%s*$", "\n\tif not ok then error(err, 0) end\n\treturn true\nend\n\nreturn synsaveinstance\n", 1)
		if patched ~= 1 then
			error("SynSaveInstance changed its entry point. Please report this error.", 0)
		end
		for attempt = 1, 2 do
			local ok, fn, err
			if attempt == 1 then
				ok, fn, err = pcall(loader, text, chunkName)
			else
				Wait(0.25)
				ok, fn, err = pcall(loader, text)
			end
			if ok and type(fn) == "function" then
				return fn
			end
			const detail = if ok then err else fn
			loadErr = detail ~= nil and tostring(detail) or loadErr or "the executor compiler returned no function"
		end
	end
	const source = NAmanage.HttpGetOrError(url, { noCache = true, timeout = 20 })
	local chunk = compile(source)
	if type(chunk) ~= "function" then
		const ok, fresh = NAmanage.IOCall(function()
			return game:HttpGet(url, true)
		end)
		if ok then
			chunk = compile(fresh)
		end
	end
	if type(chunk) ~= "function" then
		error("failed to compile SynSaveInstance: "..tostring(loadErr), 0)
	end

	const synSaveInstance = chunk(__lt)
	if type(synSaveInstance) ~= "function" then
		error("failed to load SynSaveInstance")
	end

	const function mergeOptions(target, sourceOptions)
		return NAmanage.MergeSaveOptions(target, sourceOptions)
	end

	const function getLocalHumanoid()
		const player = Services.Players and Services.Players.LocalPlayer
		const character = player and player.Character
		if character then
			return character:FindFirstChildOfClass("Humanoid")
		end
	end

	const function captureClientState()
		const state = {}

		pcall(function()
			const camera = Services.Workspace and Services.Workspace.CurrentCamera
			state.Camera = camera
			if camera then
				state.CameraType = camera.CameraType
				state.CameraSubject = camera.CameraSubject
			end
		end)

		pcall(function()
			const userInput = Services.UserInputService or SafeGetService("UserInputService")
			state.UserInput = userInput
			if userInput then
				state.MouseBehavior = userInput.MouseBehavior
				state.MouseIconEnabled = userInput.MouseIconEnabled
			end
		end)

		return state
	end

	const function restoreClientState(state)
		if type(state) ~= "table" then
			return
		end

		pcall(function()
			const userInput = state.UserInput or Services.UserInputService or SafeGetService("UserInputService")
			if not userInput then
				return
			end
			if state.MouseBehavior then
				userInput.MouseBehavior = state.MouseBehavior
			end
			if state.MouseIconEnabled ~= nil then
				userInput.MouseIconEnabled = state.MouseIconEnabled
			end
		end)

		pcall(function()
			const runService = Services.RunService or SafeGetService("RunService")
			if runService and runService.Set3dRenderingEnabled then
				runService:Set3dRenderingEnabled(true)
			end
		end)

		pcall(function()
			local camera = state.Camera
			if not camera or camera.Parent == nil then
				camera = Services.Workspace and Services.Workspace.CurrentCamera
			end
			if not camera then
				return
			end

			local subject = state.CameraSubject
			if not subject or subject.Parent == nil then
				subject = getLocalHumanoid()
			end

			if subject then
				camera.CameraSubject = subject
			end

			if state.CameraType then
				camera.CameraType = state.CameraType
			elseif subject then
				camera.CameraType = Enum.CameraType.Custom
			end
		end)
	end

	const function isInstanceArray(value)
		if type(value) ~= "table" then
			return false
		end
		for _, item in value do
			if typeof(item) ~= "Instance" then
				return false
			end
		end
		return true
	end


	local saving = false
	const function wrappedSaveInstance(param1, param2, param3)
		if saving then error("SynSaveInstance is already saving", 0) end
		const opts = {}
		local objs
		if typeof(param1) == "Instance" then
			objs = param1
		elseif type(param1) == "table" then
			if typeof(param1[1]) == "Instance" then
				if not isInstanceArray(param1) then error("The selection contains a non-instance value", 0) end
				objs = param1
			else
				mergeOptions(opts, param1)
			end
		elseif type(param1) == "string" and param1 ~= "" then
			opts.FilePath = param1
		end
		if type(param2) == "string" and param2 ~= "" then opts.FilePath = param2 end
		mergeOptions(opts, param2)
		mergeOptions(opts, param3)
		if typeof(objs) == "Instance" then
			opts.Object = objs
		elseif type(objs) == "table" then
			opts.Object = nil
			opts.ExtraInstances = objs
			opts.IsModel = true
			opts.mode = "custom"
		end
		if opts.Object ~= nil then
			if opts.Object == game then
				opts.Object = nil
				opts.IsModel = false
				opts.mode = "full"
			elseif opts.mode == nil or opts.mode == "optimized" then
				opts.mode = "full"
			end
		end
		NAmanage.FixSaveOptions(opts)
		if opts.SafeMode == nil then opts.SafeMode = false end
		if opts.KillAllScripts == nil then opts.KillAllScripts = false end
		saving = true
		const state = captureClientState()
		const ok, result = pcall(synSaveInstance, opts)
		saving = false
		restoreClientState(state)
		if not ok then error(result, 0) end
		if result ~= true and (type(result) ~= "string" or result == "") then error("Saving stopped before completion. Check F9 for the save error.", 0) end
		return true
	end

	if type(cacheHost) == "table" then
		rawset(cacheHost, cacheKey, wrappedSaveInstance)
		rawset(cacheHost, "__na_synsaveinstance", wrappedSaveInstance)
	end
	return wrappedSaveInstance
end

NAmanage.SynSaveInstanceLoader = type(NAmanage.SynSaveInstanceLoader) == "table" and NAmanage.SynSaveInstanceLoader or {
	loading = false;
	ready = false;
	value = nil;
	error = nil;
}

NAmanage.StartSynSaveInstance = NAmanage.StartSynSaveInstance or function()
	const state = NAmanage.SynSaveInstanceLoader
	if state.loading or (state.ready and type(state.value) == "function") then
		return
	end

	const cacheHost = _na_env or _G
	const cached = type(cacheHost) == "table" and rawget(cacheHost, "__na_synsaveinstance_v7")
	if type(cached) == "function" then
		state.value = cached
		state.error = nil
		state.ready = true
		return
	end

	state.loading = true
	state.error = nil
	Spawn(function()
		local ok, result = pcall(NAmanage.LoadSynSaveInstance)
		state.loading = false
		if ok and type(result) == "function" then
			state.value = result
			state.error = nil
			state.ready = true
		else
			state.value = nil
			state.ready = false
			state.error = result or "failed to load SynSaveInstance"
		end
	end)
end

NAmanage.GetSynSaveInstance = function()
	const state = NAmanage.SynSaveInstanceLoader
	if state.ready and type(state.value) == "function" then
		return state.value
	end

	NAmanage.StartSynSaveInstance()
	while state.loading do
		Wait()
	end
	if state.ready and type(state.value) == "function" then
		return state.value
	end

	const previousError = state.error
	NAmanage.StartSynSaveInstance()
	while state.loading do
		Wait()
	end
	if not state.ready or type(state.value) ~= "function" then
		error(state.error or previousError or "failed to load SynSaveInstance", 0)
	end
	return state.value
end

NAmanage.GetSaveInstancePlaceName = NAmanage.GetSaveInstancePlaceName or function()
	if type(NAStuff._SaveInstancePlaceName) == "string" and NAStuff._SaveInstancePlaceName ~= "" then
		return NAStuff._SaveInstancePlaceName
	end

	local placeName = "UnknownPlace"
	local okInfo, info = pcall(function()
		return __lt.cm("MarketplaceService", "GetProductInfo", game.PlaceId)
	end)
	if okInfo and type(info) == "table" and type(info.Name) == "string" and info.Name ~= "" then
		placeName = info.Name
	end
	placeName = tostring(placeName):gsub("[%c\\/:*?\"<>|]", "_")
	placeName = placeName:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
	if placeName == "" then
		placeName = "UnknownPlace"
	end

	NAStuff._SaveInstancePlaceName = placeName
	return placeName
end

NAmanage.FormatSaveInstanceFileName = NAmanage.FormatSaveInstanceFileName or function(template, extra)
	local formatText = tostring(template or "")
	if formatText == "" then
		formatText = "{placeName}_{timestamp}"
	end

	const tokens = {
		placeName = NAmanage.GetSaveInstancePlaceName();
		placeId = tostring(game.PlaceId);
		timestamp = os.date("%d-%m-%Y_%H-%M-%S");
		date = os.date("%d-%m-%Y");
		time = os.date("%H-%M-%S");
		unix = tostring(os.time());
	}
	if type(extra) == "table" then
		for key, value in extra do
			tokens[key] = value
		end
	end
	tokens.TIMESTAMP = tokens.TIMESTAMP or tokens.timestamp
	tokens.DATE = tokens.DATE or tokens.date
	tokens.TIME = tokens.TIME or tokens.time
	tokens.UNIX = tokens.UNIX or tokens.unix
	tokens.PLACENAME = tokens.PLACENAME or tokens.placeName
	tokens.PLACEID = tokens.PLACEID or tokens.placeId

	const resolved = formatText:gsub("{([%w_]+)}", function(token)
		local value = tokens[token]
		if value == nil then
			return "{"..token.."}"
		end
		value = tostring(value)
		value = value:gsub("[%c\\/:*?\"<>|]", "_")
		value = value:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
		if value == "" then
			return "Unnamed"
		end
		return value
	end)

	return resolved
end

NAmanage.TrimSaveInstanceText = NAmanage.TrimSaveInstanceText or function(value, fallback)
	const text = tostring(value or ""):match("^%s*(.-)%s*$") or ""
	if text == "" and fallback ~= nil then
		return fallback
	end
	return text
end

NAmanage.ParseSaveInstanceList = NAmanage.ParseSaveInstanceList or function(value)
	if type(value) == "table" then return value end
	const raw = NAmanage.TrimSaveInstanceText(value, "")
	if raw:match("^[%[{]") then
		const ok, data = pcall(Services.HttpService.JSONDecode, Services.HttpService, raw)
		if not ok or type(data) ~= "table" then error("Save instance list/map JSON is invalid", 0) end
		return data
	end
	const out = {}
	const seen = {}
	for _, entry in string.split(raw, ",") do
		const clean = tostring(entry):match("^%s*(.-)%s*$") or ""
		if clean ~= "" and not seen[clean] then
			seen[clean] = true
			out[#out + 1] = clean
		end
	end
	return out
end

NAmanage.DecodeSaveInstanceExtraOptions = NAmanage.DecodeSaveInstanceExtraOptions or function(text)
	const trimmed = NAmanage.TrimSaveInstanceText(text, "")
	if trimmed == "" then
		return {}
	end
	local okDecode, decoded = pcall(function()
		return Services.HttpService:JSONDecode(trimmed)
	end)
	if not okDecode or type(decoded) ~= "table" then
		error("Extra Options JSON is invalid")
	end
	return decoded
end



NAmanage.BuildSaveInstanceOptions = NAmanage.BuildSaveInstanceOptions or function(extra)
	const cfg = NAStuff.SaveInstanceConfig or {}
	const options = {
		SafeMode = cfg.safeMode == true;
		KillAllScripts = cfg.killAllScripts == true;
		BoostFPS = cfg.boostFPS == true;
		ShutdownWhenDone = cfg.shutdownWhenDone == true;
		AntiIdle = cfg.antiIdle ~= false;
		ShowStatus = cfg.showStatus ~= false;
		ReadMe = cfg.readMe ~= false;
		__DEBUG_MODE = cfg.debugMode == true;
		Anonymous = cfg.anonymous == true;
		mode = (cfg.mode == "full" or cfg.mode == "scripts") and cfg.mode or "optimized";
		Decompile = cfg.decompile ~= false;
		scriptcache = cfg.scriptCache ~= false;
		DecompileTimeout = tonumber(cfg.decompileTimeout) or 10;
		BytecodeTimeout = tonumber(cfg.bytecodeTimeout) or 3;
		DecompileJobless = cfg.decompileJobless == true;
		SaveBytecode = cfg.saveBytecode == true;
		RecoverScriptsFromAssets = cfg.recoverScriptsFromAssets ~= false;
		DecompileIgnore = NAmanage.ParseSaveInstanceList(cfg.decompileIgnore);
		IgnoreList = NAmanage.ParseSaveInstanceList(cfg.ignoreList);
		IgnoreProperties = NAmanage.ParseSaveInstanceList(cfg.ignoreProperties);
		SaveCacheInterval = math.max(0, math.floor((tonumber(cfg.saveCacheInterval) or 56320) + 0.5));
		NilInstances = cfg.nilInstances == true;
		IgnoreDefaultProperties = cfg.ignoreDefaultProperties ~= false;
		IgnoreNotArchivable = cfg.ignoreNotArchivable ~= false;
		IgnorePropertiesOfNotScriptsOnScriptsMode = cfg.ignorePropertiesOfNotScriptsOnScriptsMode == true;
		IgnoreSpecialProperties = cfg.ignoreSpecialProperties == true;
		IsolateStarterPlayer = cfg.isolateStarterPlayer == true;
		IsolatePlayers = cfg.isolatePlayers == true;
		IsolateLocalPlayer = cfg.isolateLocalPlayer == true;
		IsolateLocalPlayerCharacter = cfg.isolateLocalPlayerCharacter == true;
		SavePlayerCharacters = cfg.savePlayerCharacters == true;
		SaveNotCreatable = cfg.saveNotCreatable == true;
		AlternativeWritefile = cfg.alternativeWritefile ~= false;
		IgnoreDefaultPlayerScripts = cfg.ignoreDefaultPlayerScripts == true;
		TreatUnionsAsParts = cfg.treatUnionsAsParts == true;
		Binary = cfg.binary == true;
		CompressionMode = cfg.compressionMode;
		CompressionLevel = math.clamp(math.floor((tonumber(cfg.compressionLevel) or 9) + 0.5), -7, 22);
		SharedBinaryStrings = cfg.sharedBinaryStrings == true;
		CopyToClipboard = cfg.copyToClipboard == true;
		AvoidFileOverwrite = cfg.avoidFileOverwrite ~= false;
		FilePath = NAmanage.FormatSaveInstanceFileName(cfg.fileNameFormat);
	}
	const fixes = NAmanage.ParseSaveInstanceList(cfg.notCreatableFixes)
	if next(fixes) and cfg.notCreatableFixes ~= "Player,PlayerScripts,PlayerGui,TouchTransmitter" then options.NotCreatableFixes = fixes end
	local executorName = ""
	pcall(function()
		if type(identifyexecutor) == "function" then
			executorName = tostring(identifyexecutor())
		end
	end)
	if executorName == "Fluxus" and extra == nil then
		options.IgnoreSpecialProperties = true
	end
	NAmanage.MergeSaveOptions(options, NAmanage.DecodeSaveInstanceExtraOptions(cfg.extraOptionsJson))
	NAmanage.MergeSaveOptions(options, extra)
	NAmanage.FixSaveOptions(options)
	return options
end

NAmanage.RunSaveInstance = NAmanage.RunSaveInstance or function(extra)
	const synSaveInstance = NAmanage.GetSynSaveInstance()
	const options = NAmanage.BuildSaveInstanceOptions(extra)
	local ok, result = pcall(synSaveInstance, options)
	if not ok then
		error(result)
	end
	return result
end


NAStuff.FullMapStreamingState = type(NAStuff.FullMapStreamingState) == "table" and NAStuff.FullMapStreamingState or {
	enabled = false;
	token = 0;
	connection = nil;
	previousStreamOutBehavior = nil;
	originalModelModes = nil;
	sweepRunning = false;
	completed = 0;
	failed = 0;
	total = 0;
}

NAmanage.StopFullMapStreaming = NAmanage.StopFullMapStreaming or function(opts)
	opts = type(opts) == "table" and opts or {}
	local state = NAStuff.FullMapStreamingState
	state.enabled = false
	state.token = (tonumber(state.token) or 0) + 1
	state.sweepRunning = false

	if state.connection then
		pcall(function()
			state.connection:Disconnect()
		end)
		state.connection = nil
	end

	if type(state.originalModelModes) == "table" then
		for model, mode in state.originalModelModes do
			if typeof(model) == "Instance" and model.Parent ~= nil and mode ~= nil then
				pcall(function()
					model.ModelStreamingMode = mode
				end)
			end
		end
	end
	state.originalModelModes = nil

	if state.previousStreamOutBehavior ~= nil then
		pcall(function()
			if type(sethiddenproperty) == "function" then
				sethiddenproperty(workspace, "StreamOutBehavior", state.previousStreamOutBehavior)
			else
				workspace.StreamOutBehavior = state.previousStreamOutBehavior
			end
		end)
	end
	state.previousStreamOutBehavior = nil

	if opts.save ~= false then
		pcall(NAmanage.NASettingsSet, "fullMapStreamingEnabled", false)
	end
	if opts.notify == true then
		DoNotif("Full map streaming disabled. Loaded chunks can stream out normally again.", 3, "Full Map Streaming")
	end
	return true
end

NAmanage.SetFullMapStreaming = NAmanage.SetFullMapStreaming or function(enabled, opts)
	opts = type(opts) == "table" and opts or {}
	enabled = enabled == true

	if not enabled then
		return NAmanage.StopFullMapStreaming(opts)
	end

	local state = NAStuff.FullMapStreamingState
	if state.enabled == true then
		if opts.save ~= false then
			pcall(NAmanage.NASettingsSet, "fullMapStreamingEnabled", true)
		end
		return true
	end

	local player = Services.Players.LocalPlayer
	if not player or type(player.RequestStreamAroundAsync) ~= "function" then
		if opts.notify ~= false then
			DoNotif("RequestStreamAroundAsync is unavailable.", 3, "Full Map Streaming")
		end
		return false
	end

	if workspace.StreamingEnabled ~= true then
		if opts.notify ~= false then
			DoNotif("Workspace streaming is disabled in this game, so there is nothing for this mode to force-load.", 4, "Full Map Streaming")
		end
		if opts.save ~= false then
			pcall(NAmanage.NASettingsSet, "fullMapStreamingEnabled", false)
		end
		return false
	end

	state.enabled = true
	state.token = (tonumber(state.token) or 0) + 1
	local token = state.token
	state.completed = 0
	state.failed = 0
	state.total = 0
	state.originalModelModes = setmetatable({}, { __mode = "k" })

	pcall(function()
		if type(gethiddenproperty) == "function" then
			state.previousStreamOutBehavior = gethiddenproperty(workspace, "StreamOutBehavior")
		else
			state.previousStreamOutBehavior = workspace.StreamOutBehavior
		end
	end)
	pcall(function()
		if type(sethiddenproperty) == "function" then
			sethiddenproperty(workspace, "StreamOutBehavior", Enum.StreamOutBehavior.LowMemory)
		else
			workspace.StreamOutBehavior = Enum.StreamOutBehavior.LowMemory
		end
	end)

	local function persistModel(model)
		if state.enabled ~= true or token ~= state.token or not model:IsA("Model") then
			return
		end
		if state.originalModelModes[model] == nil then
			pcall(function()
				state.originalModelModes[model] = model.ModelStreamingMode
			end)
		end
		pcall(function()
			model.ModelStreamingMode = Enum.ModelStreamingMode.Persistent
		end)
	end

	local okModels, models = pcall(function()
		return workspace:QueryDescendants("Model")
	end)
	if okModels and type(models) == "table" then
		for _, model in models do
			persistModel(model)
		end
	else
		for _, descendant in workspace:GetDescendants() do
			if descendant:IsA("Model") then
				persistModel(descendant)
			end
		end
	end

	state.connection = workspace.DescendantAdded:Connect(function(descendant)
		if descendant:IsA("Model") then
			persistModel(descendant)
		end
	end)

	local cfg = NAStuff.SaveInstanceConfig or {}
	local areaSize = math.max(256, tonumber(cfg.streamingAreaSize) or 10000)
	local configuredRadius = math.max(64, tonumber(cfg.streamingRadius) or 1024)
	local timeout = math.max(1, tonumber(cfg.streamingTimeout) or 20)
	local slices = math.clamp(math.floor((tonumber(cfg.streamingSlices) or 2) + 0.5), 1, 16)
	local concurrency = math.max(0, math.floor((tonumber(cfg.streamingConcurrency) or 0) + 0.5))
	if concurrency <= 0 then
		concurrency = math.clamp(math.floor(areaSize / 750), 4, 24)
	end

	local targetRadius = configuredRadius
	pcall(function()
		if type(gethiddenproperty) == "function" then
			local value = tonumber(gethiddenproperty(workspace, "StreamingTargetRadius"))
			if value and value > 0 then
				targetRadius = math.max(64, math.min(configuredRadius, value))
			end
		end
	end)
	local step = math.max(64, targetRadius)
	local character = player.Character
	local center = Vector3.zero
	if character then
		pcall(function()
			center = character:GetPivot().Position
		end)
	elseif workspace.CurrentCamera then
		center = workspace.CurrentCamera.CFrame.Position
	end

	local half = areaSize * 0.5
	local verticalSpan = math.max(step, configuredRadius)
	local points = {}
	local yValues = {}
	if slices <= 1 then
		yValues[1] = center.Y
	else
		for index = 1, slices do
			local alpha = (index - 1) / (slices - 1)
			yValues[#yValues + 1] = center.Y + ((alpha * 2) - 1) * verticalSpan
		end
	end
	for _, y in yValues do
		local x = center.X - half
		while x <= center.X + half + 0.001 do
			local z = center.Z - half
			while z <= center.Z + half + 0.001 do
				points[#points + 1] = Vector3.new(x, y, z)
				z += step
			end
			x += step
		end
	end

	state.total = #points
	state.sweepRunning = true
	if opts.save ~= false then
		pcall(NAmanage.NASettingsSet, "fullMapStreamingEnabled", true)
	end
	if opts.notify ~= false then
		DoNotif(("Streaming %d map cells in the background without moving your character."):format(#points), 4, "Full Map Streaming")
	end

	task.spawn(function()
		local nextIndex = 1
		local workersLeft = concurrency
		for _ = 1, concurrency do
			task.spawn(function()
				while state.enabled == true and token == state.token do
					local index = nextIndex
					nextIndex += 1
					if index > #points then
						break
					end
					local ok = pcall(function()
						player:RequestStreamAroundAsync(points[index], timeout)
					end)
					if ok then
						state.completed += 1
					else
						state.failed += 1
					end
					task.wait()
				end
				workersLeft -= 1
			end)
		end

		while state.enabled == true and token == state.token and workersLeft > 0 do
			task.wait(0.1)
		end
		if token ~= state.token then
			return
		end
		state.sweepRunning = false
		if state.enabled == true and opts.notify ~= false then
			DoNotif(("Full map streaming pass finished: %d/%d requests succeeded%s."):format(
				state.completed,
				state.total,
				state.failed > 0 and (", "..tostring(state.failed).." failed") or ""
			), 4, "Full Map Streaming")
		end
	end)

	return true
end

if type(NAmanage.RegisterUnloadCleanup) == "function" then
