	end
end)

NAmanage.BuildSaveInstanceTab = NAmanage.BuildSaveInstanceTab or function()
	const cfg = NAStuff.SaveInstanceConfig
	const function setValue(key, setting, value)
		cfg[key] = value
		pcall(NAmanage.NASettingsSet, setting, value)
	end
	const function choose(value, fallback)
		if type(value) == "table" then value = value[1] end
		return tostring(value or fallback)
	end
	const function flag(title, key, setting, def)
		NAgui.addToggle(title, cfg[key] == true or (def == true and cfg[key] ~= false), function(value)
			setValue(key, setting, value == true)
		end)
	end
	const function textField(title, hint, key, setting, fallback)
		NAgui.addInput(title, hint, tostring(cfg[key] or fallback), function(value)
			setValue(key, setting, NAmanage.TrimSaveInstanceText(value, fallback))
		end)
	end
	const function numberField(title, key, setting, fallback, minVal, maxVal)
		NAgui.addInput(title, tostring(fallback), tostring(cfg[key] or fallback), function(value)
			local result = tonumber(value) or fallback
			if minVal == -1 then
				if result ~= -1 and (result <= 0 or result ~= result or result == math.huge) then result = fallback end
			else
				result = maxVal and math.clamp(result, minVal, maxVal) or math.max(minVal, result)
			end
			setValue(key, setting, result)
		end)
	end

	NAgui.addSection("Safety")
	flag("Safe Mode (leave game before saving)", "safeMode", "saveInstanceSafeMode", false)
	flag("Kill Scripts", "killAllScripts", "saveInstanceKillAllScripts", false)
	flag("Boost FPS While Saving", "boostFPS", "saveInstanceBoostFPS", false)
	flag("Shutdown When Done", "shutdownWhenDone", "saveInstanceShutdownWhenDone", false)
	flag("Anti Idle", "antiIdle", "saveInstanceAntiIdle", true)
	flag("Show Status", "showStatus", "saveInstanceShowStatus", true)
	flag("Write ReadMe", "readMe", "saveInstanceReadMe", true)
	flag("Debug Mode", "debugMode", "saveInstanceDebugMode", false)
	flag("Anonymous", "anonymous", "saveInstanceAnonymous", false)

	NAgui.addSection("Scripts")
	NAgui.addDropdown("Save Mode", {"optimized", "full", "scripts"}, tostring(cfg.mode or "optimized"), function(selected)
		local mode = choose(selected, "optimized"):lower()
		if mode ~= "full" and mode ~= "scripts" then mode = "optimized" end
		setValue("mode", "saveInstanceMode", mode)
	end)
	flag("Decompile Scripts", "decompile", "saveInstanceDecompile", true)
	flag("Use Script Cache", "scriptCache", "saveInstanceScriptCache", true)
	flag("Recover Scripts From Assets", "recoverScriptsFromAssets", "saveInstanceRecoverScriptsFromAssets", true)
	flag("Cached Scripts Only", "decompileJobless", "saveInstanceDecompileJobless", false)
	flag("Save Bytecode", "saveBytecode", "saveInstanceSaveBytecode", false)
	numberField("Decompile Timeout (s, -1 = off)", "decompileTimeout", "saveInstanceDecompileTimeout", 10, -1)
	numberField("Bytecode Timeout (s, -1 = off)", "bytecodeTimeout", "saveInstanceBytecodeTimeout", 3, -1)
	textField("Decompile Ignore (list or JSON)", "TextChatService", "decompileIgnore", "saveInstanceDecompileIgnore", "")

	NAgui.addSection("Instances")
	textField("Ignore List (list or JSON)", "CoreGui,CorePackages", "ignoreList", "saveInstanceIgnoreList", "")
	textField("Ignore Properties", "PropertyA,PropertyB", "ignoreProperties", "saveInstanceIgnoreProperties", "")
	textField("Class Fixes (blank = defaults)", "List or JSON map", "notCreatableFixes", "saveInstanceNotCreatableFixes", "")
	numberField("XML Buffer Size (bytes)", "saveCacheInterval", "saveInstanceSaveCacheInterval", 56320, 0)
	flag("Save Nil Instances", "nilInstances", "saveInstanceNilInstances", false)
	flag("Ignore Default Properties (XML)", "ignoreDefaultProperties", "saveInstanceIgnoreDefaultProperties", true)
	flag("Save Non-Archivable Objects", "ignoreNotArchivable", "saveInstanceIgnoreNotArchivable", true)
	flag("Ignore Non-Script Props In Scripts Mode", "ignorePropertiesOfNotScriptsOnScriptsMode", "saveInstanceIgnorePropertiesOfNotScriptsOnScriptsMode", false)
	flag("Ignore Special Properties", "ignoreSpecialProperties", "saveInstanceIgnoreSpecialProperties", false)
	flag("Isolate StarterPlayer", "isolateStarterPlayer", "saveInstanceIsolateStarterPlayer", false)
	flag("Isolate Players", "isolatePlayers", "saveInstanceIsolatePlayers", false)
	flag("Isolate Local Player", "isolateLocalPlayer", "saveInstanceIsolateLocalPlayer", false)
	flag("Isolate Local Player Character", "isolateLocalPlayerCharacter", "saveInstanceIsolateLocalPlayerCharacter", false)
	flag("Save Player Characters", "savePlayerCharacters", "saveInstanceSavePlayerCharacters", false)
	flag("Save Not Creatable", "saveNotCreatable", "saveInstanceSaveNotCreatable", false)
	flag("Alternative Writefile", "alternativeWritefile", "saveInstanceAlternativeWritefile", true)
	flag("Ignore Default PlayerScripts", "ignoreDefaultPlayerScripts", "saveInstanceIgnoreDefaultPlayerScripts", false)
	flag("Treat Unions As Parts", "treatUnionsAsParts", "saveInstanceTreatUnionsAsParts", false)

	NAgui.addSection("Output")
	flag("Binary Output", "binary", "saveInstanceBinary", false)
	NAgui.addDropdown("Compression", {"zstd", "lz4", "none"}, tostring(cfg.compressionMode or "zstd"), function(selected)
		local value = choose(selected, "zstd"):lower()
		if value ~= "lz4" and value ~= "none" then value = "zstd" end
		setValue("compressionMode", "saveInstanceCompressionMode", value)
	end)
	numberField("Compression Level", "compressionLevel", "saveInstanceCompressionLevel", 9, -7, 22)
	flag("Shared Binary Strings", "sharedBinaryStrings", "saveInstanceSharedBinaryStrings", false)
	flag("Copy To Clipboard", "copyToClipboard", "saveInstanceCopyToClipboard", false)
	flag("Avoid File Overwrite", "avoidFileOverwrite", "saveInstanceAvoidFileOverwrite", true)

	NAgui.addSection("Full Map Streaming (NA)")
	numberField("Area Size", "streamingAreaSize", "saveInstanceStreamingAreaSize", 10000, 1)
	numberField("Radius", "streamingRadius", "saveInstanceStreamingRadius", 1024, 1)
	numberField("Request Timeout", "streamingTimeout", "saveInstanceStreamingTimeout", 20, 1)
	numberField("Concurrency (0 = auto)", "streamingConcurrency", "saveInstanceStreamingConcurrency", 0, 0)
	numberField("Vertical Slices", "streamingSlices", "saveInstanceStreamingSlices", 2, 1, 16)
	numberField("Max Time (0 = auto)", "streamingMaxTime", "saveInstanceStreamingMaxTime", 0, 0)
	numberField("Chunk Wait", "streamingChunkWait", "saveInstanceStreamingChunkWait", 12, 1)
	numberField("Settle Time", "streamingSettleTime", "saveInstanceStreamingSettleTime", 5, 0)

	NAgui.addSection("File")
	textField("File Name Format", "{placeName}_{timestamp}", "fileNameFormat", "saveInstanceFileNameFormat", "{placeName}_{timestamp}")
	textField("Extra Options JSON", "{\"Option\":true}", "extraOptionsJson", "saveInstanceExtraOptionsJson", "")
	NAgui.addButton("Save Current Game", function()
		local ok, err = pcall(NAmanage.RunSaveInstance)
		if ok then
			DoNotif("SynSaveInstance finished saving.", 3)
		else
			DoNotif("SynSaveInstance failed: "..tostring(err), 4)
		end
	end)
end

NAmanage.OpenSaveInstanceSettings = NAmanage.OpenSaveInstanceSettings or function()
	if NAgui and type(NAgui.settingss) == "function" then
		pcall(NAgui.settingss)
	end

	const settingsFrame = NAUIMANAGER and NAUIMANAGER.SettingsFrame
	if settingsFrame then
		pcall(function()
			if settingsFrame.Visible ~= true then
				settingsFrame.Visible = true
			end
			if NAmanage.OnUIWindowShown then pcall(NAmanage.OnUIWindowShown, settingsFrame) end

			if settingsFrame.GetAttribute and settingsFrame.Size then
				const minimized = NAmanage.GetAttr(settingsFrame, "NAMenuMinimized") == true
				if minimized then
					const restoreX = tonumber(NAmanage.GetAttr(settingsFrame, "NAMenuStoredSizeX")) or settingsFrame.Size.X.Offset
					const restoreY = tonumber(NAmanage.GetAttr(settingsFrame, "NAMenuStoredSizeY")) or settingsFrame.Size.Y.Offset
					NAmanage.SetAttr(settingsFrame, "NAMenuMinimized", false)
					settingsFrame.Size = UDim2.new(0, restoreX, 0, restoreY)
				end
			end

			if NAmanage and type(NAmanage.centerFrame) == "function" then
				NAmanage.centerFrame(settingsFrame)
			end
		end)
	end

	if NAgui and type(NAgui.setTab) == "function" then
		pcall(function()
			NAgui.setTab(NA_TABS.TAB_SAVE_INSTANCE)
		end)
	end
end

NAmanage.RunSaveInstanceCommand = NAmanage.RunSaveInstanceCommand or function()
	local ok, err = pcall(NAmanage.RunSaveInstance)
	if ok then
		DoNotif("SynSaveInstance finished with your saved NA settings.", 3)
	else
		DoNotif("SynSaveInstance failed: "..tostring(err), 4)
	end
end

cmd.register({
	name = "saveinstance",
	aliases = { "savegame" },
	description = "Saves the game with SynSaveInstance using your saved options",
	usage = "saveinstance (savegame)",
	callback = function()
		if NAmanage.NASettingsGet("saveInstanceCommandHintShown") ~= true then
			pcall(NAmanage.NASettingsSet, "saveInstanceCommandHintShown", true)
			if type(Popup) == "function" then
				Popup({
					Title = "SaveInstance 420 Setup",
					Description = "Do you want to configure SynSaveInstance first? Confirm opens the Save Instance settings tab. Ignore uses the current saved defaults.",
					Duration = 0,
					Buttons = {
						{
							Text = "Confirm",
							Callback = function()
								NAmanage.OpenSaveInstanceSettings()
							end,
						},
						{
							Text = "Ignore",
							Callback = function()
								NAmanage.RunSaveInstanceCommand()
							end,
						},
					},
				})
				return
			else
				DoNotif("Tip: open the Save Instance tab in settings if you want to configure the save options first.", 7)
			end
		end
		NAmanage.RunSaveInstanceCommand()
	end,
})

cmd.register({
	name = "admin",
	aliases = { "whitelist" },
	description = "Whitelist the user to have access to *your* client-side commands, anything they type runs on *you*, not on themselves",
	usage = "admin <player>",
	requiresArguments = true,
	callback = function(...)
		const Player=getPlr(NAmanage.PlayerQueryFromArgs(...))
		const pending={}
		for _, plr in next, Player do
			if plr~=nil and not Admin[plr.UserId] then
				pending[#pending+1]=plr
			end
		end
		if #pending==0 then
			DoNotif("No eligible player found")
			return
		end
		const names={}
		for _, plr in pending do names[#names+1]=nameChecker(plr) end
		const function grantAdmin(tellUser)
			for _, plr in pending do
				if plr and plr.Parent and not Admin[plr.UserId] then
					Admin[plr.UserId]={plr=plr}
					if tellUser then
						NAlib.LocalPlayerChat(("[%s] You've got admin. Use prefix %q. Your commands will control my client."):format(adminName, opt.prefix),plr.Name)
						Wait(0.2)
					end
					DoNotif(nameChecker(plr).." has now been whitelisted to use commands"..(tellUser and " and was notified" or " silently"),15)
				end
			end
		end
		const show=Window or DoWindow
		if type(show)=="function" then
			show({
				Title="Admin Access",
				Description=("Whitelist %s?\n\nTheir commands will use your current prefix %q. Choose whether to tell them privately."):format(Concat(names, ", "), opt.prefix),
				Buttons={
					{Text="Tell User",Callback=function() grantAdmin(true) end},
					{Text="Silent",Callback=function() grantAdmin(false) end},
				}
			})
		else
			grantAdmin(false)
		end
	end,
})

cmd.register({
	name = "unadmin",
	description = "removes someone from being admin",
	usage = "unadmin <player>",
	requiresArguments = true,
	callback = function(...)
		function ChatMessage(Message,Whisper)
			NAlib.LocalPlayerChat(Message,Whisper or "All")
		end
		const Player=getPlr(NAmanage.PlayerQueryFromArgs(...))
		for _, plr in next, Player do
			if plr~=nil and Admin[plr.UserId] then
				Admin[plr.UserId]=nil
				ChatMessage("You can no longer use commands",plr.Name)
				DoNotif(nameChecker(plr).." is no longer an admin",15)
			else
				DoNotif("Player not found")
			end
		end
	end,
})

