	return detail and detail.city or nil
end


NAStuff.srv.parseIsoTimestamp = function(self, value)
	if type(value) ~= "string" or value == "" then return nil end
	local y, mo, d, h, mi, s = value:match("^(%d%d%d%d)%-(%d%d)%-(%d%d)T(%d%d):(%d%d):(%d%d)")
	y, mo, d, h, mi, s = tonumber(y), tonumber(mo), tonumber(d), tonumber(h), tonumber(mi), tonumber(s)
	if not (y and mo and d and h and mi and s) then return nil end
	local ok, dt = pcall(DateTime.fromUniversalTime, y, mo, d, h, mi, s)
	if ok and dt then return dt.UnixTimestamp end
	return nil
end

NAStuff.srv.formatUptime = function(self, seconds, estimated)
	local value = tonumber(seconds)
	if not value or value < 0 then return "Unknown" end
	value = math.floor(value)
	const days = math.floor(value / 86400)
	const hours = math.floor((value % 86400) / 3600)
	const minutes = math.floor((value % 3600) / 60)
	const secs = math.floor(value % 60)
	const parts = {}
	if days > 0 then parts[#parts + 1] = tostring(days).."d" end
	if hours > 0 then parts[#parts + 1] = tostring(hours).."h" end
	if minutes > 0 then parts[#parts + 1] = tostring(minutes).."m" end
	if #parts == 0 then parts[#parts + 1] = tostring(secs).."s" end
	return Concat(parts, " ")..(estimated == true and "~" or "")
end

NAStuff.srv.normalizeDetail = function(self, raw)
	if type(raw) ~= "table" then return nil end
	const id = tostring(raw.server_id or raw.id or "")
	if id == "" then return nil end
	local firstSeenUnix = self:parseIsoTimestamp(raw.first_seen)
	local uptime = nil
	if firstSeenUnix then
		local nowUnix = nil
		local okNow, nowDt = pcall(DateTime.now)
		if okNow and nowDt then nowUnix = nowDt.UnixTimestamp end
		if nowUnix then uptime = math.max(0, nowUnix - firstSeenUnix) end
	end
	const locationParts = {}
	if raw.city and tostring(raw.city) ~= "" and tostring(raw.city) ~= "Unknown" then locationParts[#locationParts + 1] = tostring(raw.city) end
	if raw.region and tostring(raw.region) ~= "" and tostring(raw.region) ~= "Unknown" and tostring(raw.region) ~= tostring(raw.city) then locationParts[#locationParts + 1] = tostring(raw.region) end
	if raw.country and tostring(raw.country) ~= "" and tostring(raw.country) ~= "Unknown" then locationParts[#locationParts + 1] = tostring(raw.country) end
	return {
		id = id;
		serverId = id;
		firstSeen = raw.first_seen;
		firstSeenUnix = firstSeenUnix;
		uptime = uptime;
		uptimeEstimated = firstSeenUnix ~= nil;
		placeVersion = tonumber(raw.place_version) or raw.place_version;
		city = raw.city and tostring(raw.city) or nil;
		regionName = raw.region and tostring(raw.region) or nil;
		country = raw.country and tostring(raw.country) or nil;
		countryCode = raw.region_code and tostring(raw.region_code) or nil;
		ipAddress = raw.ip_address and tostring(raw.ip_address) or nil;
		datacenterId = raw.datacenter_id;
		regionLabel = #locationParts > 0 and Concat(locationParts, ", ") or nil;
	}
end

NAStuff.srv.fetchRoDetails = function(self, placeId, serverIds, force)
	const pid = tonumber(placeId) or tonumber(PlaceId)
	if type(serverIds) ~= "table" or #serverIds == 0 then return {} end
	const results = {}
	const missing = {}
	const now = tick()
	for _, rawId in serverIds do
		const id = tostring(rawId or "")
		if id ~= "" then
			const key = "rovalra|"..tostring(pid).."|"..id
			const cached = self.detailsCache[key]
			if not force and type(cached) == "table" and now - (tonumber(cached.at) or 0) < self.detailsTtl and type(cached.data) == "table" then
				results[id] = cached.data
			else
				missing[#missing + 1] = id
			end
		end
	end
	local index = 1
	while index <= #missing do
		const batch = {}
		for i = index, math.min(index + 39, #missing) do batch[#batch + 1] = missing[i] end
		index += #batch
		const url = self.latency.cfg.rovalraBase.."/v1/servers/details?place_id="..tostring(pid).."&server_ids="..Services.HttpService:UrlEncode(Concat(batch, ","))
		const decoded = self:j(self:get(url))
		if type(decoded) == "table" and type(decoded.servers) == "table" then
			for _, raw in decoded.servers do
				const detail = self:normalizeDetail(raw)
				if detail then
					detail.provider = "RoValra"
					results[detail.id] = detail
					self.detailsCache["rovalra|"..tostring(pid).."|"..detail.id] = { at = tick(); data = detail }
				end
			end
		end
		if index <= #missing then Wait(self.latency.cfg.requestDelay) end
	end
	return results
end

NAStuff.srv.better = type(NAStuff.srv.better) == "table" and NAStuff.srv.better or {
	dcs = {}; at = 0; indexes = {};
}

NAStuff.srv.getRoDcs = function(self, force)
	const cached = self.roDcs
	if not force and cached and tick() - cached.at < self.latency.cfg.modelTtl then return cached.rows end
	const rows = self:j(self:get(self.latency.cfg.datacentersUrl))
	if type(rows) == "table" and #rows > 0 then
		self.roDcs = {at = tick(); rows = rows}
	end
	return self.roDcs and self.roDcs.rows or {}
end

do
	const aliases = { ffm = "frankfurt"; hessen = "hesse"; deutschland = "de"; usa = "us"; uk = "gb"; turkey = "tr" }
	const countries = {
		ar = "argentina"; au = "australia"; br = "brazil"; ch = "switzerland"; cl = "chile";
		de = "germany"; fr = "france"; gb = "united kingdom"; gr = "greece"; id = "indonesia";
		ie = "ireland"; il = "israel"; ["in"] = "india"; it = "italy"; jp = "japan"; mx = "mexico";
		my = "malaysia"; nl = "netherlands"; pe = "peru"; pl = "poland"; qa = "qatar";
		sg = "singapore"; tr = "turkiye"; us = "united states"; za = "south africa";
	}
	const accents = {
		["ã"] = "a"; ["Ã"] = "a"; ["é"] = "e"; ["É"] = "e"; ["î"] = "i"; ["Î"] = "i";
		["ō"] = "o"; ["Ō"] = "o"; ["ü"] = "u"; ["Ü"] = "u";
	}
	const function locText(value)
		const text = tostring(value or ""):gsub("[\194-\244][\128-\191]+", accents)
		return Lower(text):gsub("[%p%s]+", " "):match("^%s*(.-)%s*$")
	end

	NAStuff.srv.resolveRegionQuery = function(self, query)
		const raw = tostring(query or ""):match("^%s*(.-)%s*$")
		const text = locText(raw):gsub("%S+", aliases)
		if text == "" then return nil end
		const rows = self:getRoDcs(false)
		const names = table.clone(countries)
		for _, dc in rows do
			const loc = type(dc) == "table" and dc.location
			if type(loc) == "table" then
				const code, name = locText(loc.country), locText(loc.country_name)
				if #code == 2 and name ~= "" then names[code] = name end
			end
		end
		local code = text:match("^%a%a$")
		if not code then
			for id, name in names do
				if name == text then code = id break end
			end
		end
		return { raw = raw; text = text; code = code; names = names; dcs = rows }
	end

	NAStuff.srv.matchLocation = function(self, loc, query)
		if type(loc) ~= "table" then return false end
		const code = locText(loc.countryCode or loc.region_code or loc.country)
		const name = locText(loc.country_name or query.names[code] or loc.country)
		if query.code then
			return code == query.code or (#code ~= 2 and name == query.names[query.code])
		end
		const city = locText(loc.city)
		const region = locText(loc.regionName or loc.region)
		const text = " "..city.." "..region.." "..name.." "..code.." "
		for word in query.text:gmatch("%S+") do
			if not text:find(" "..word.." ", 1, true) then return false end
		end
		return true
	end
end

NAStuff.srv.getBetterDcs = function(self, force)
	const state = self.better
	if not force and tick() - state.at < 900 and next(state.dcs) then return state.dcs end
	if not force and state.failedAt and tick() - state.failedAt < 20 then return state.dcs end
	const raw = self:j(self:get(self.latency.cfg.betterBase.."/servers/datacenters"))
	if type(raw) ~= "table" then state.failedAt = tick() return state.dcs end
	const dcs = {}
	for key, dc in raw do
		const id = type(dc) == "table" and (tonumber(dc.id) or tonumber(key))
		const loc = type(dc) == "table" and dc.location
		if id and id > 0 and type(loc) == "table" and loc.city then dcs[id] = loc end
	end
	if next(dcs) then
		state.dcs = dcs
		state.at = tick()
		state.failedAt = nil
	else
		state.failedAt = tick()
	end
	return state.dcs
end

NAStuff.srv.normalizeBetter = function(self, raw, dcs)
	if type(raw) ~= "table" then return nil end
	const loc = dcs[tonumber(raw.datacenter or raw.datacenterId)]
	if type(loc) ~= "table" then return nil end
	const detail = self:normalizeDetail({
		id = raw.id or raw.serverId;
		first_seen = raw.firstSeen;
		datacenter_id = raw.datacenter or raw.datacenterId;
		city = loc.city; region = loc.region;
		country = loc.country; region_code = loc.country;
	})
	if detail then
		detail.provider = "BetterBLOX"
		detail.latitude, detail.longitude = self:extractLatLon(loc)
	end
	return detail
end

NAStuff.srv.getBetterIndex = function(self, placeId, dcIds, force)
	const pid = tonumber(placeId) or tonumber(PlaceId)
	const filter = type(dcIds) == "table" and Concat(dcIds, ",") or ""
	const key = tostring(pid).."|"..filter
	const cached = self.better.indexes[key]
	if not force and cached and tick() - cached.at < (cached.failed and 15 or 60) then return cached.data end
	const out, seen = {}, {}
	local cursor
	local failed = false
	for page = 1, self.latency.cfg.betterPages do
		local url = self.latency.cfg.betterBase.."/servers/place/"..tostring(pid).."?limit=500"
		if filter ~= "" then url ..= "&region="..Services.HttpService:UrlEncode(filter) end
		if cursor then url ..= "&cursor="..Services.HttpService:UrlEncode(cursor) end
		const data = self:j(self:get(url))
		const rows = type(data) == "table" and (data.servers or data.data)
		if type(rows) ~= "table" then failed = true break end
		for _, raw in rows do
			const id = type(raw) == "table" and tostring(raw.id or "")
			if id and id ~= "" and not out[id] then out[id] = raw end
		end
		cursor = data.nextPageCursor
		if not cursor or cursor == "" or seen[cursor] then break end
		seen[cursor] = true
		Wait(self.latency.cfg.requestDelay)
	end
	local count = 0
	for name, cache in self.better.indexes do
		count += 1
		if tick() - cache.at > 180 then self.better.indexes[name] = nil end
	end
	if count >= 12 then self.better.indexes = {} end
	self.better.indexes[key] = { at = tick(); data = out; failed = failed }
	return out
end

NAStuff.srv.fetchBetterDetails = function(self, placeId, serverIds, force)
	const pid = tonumber(placeId) or tonumber(PlaceId)
	const results = {}
	if type(serverIds) ~= "table" or #serverIds == 0 then return results end
	const dcs = self:getBetterDcs(force)
	if not next(dcs) then return results end
	if #serverIds <= 3 then
		for _, rawId in serverIds do
			const id = tostring(rawId)
			const key = "betterblox|"..tostring(pid).."|"..id
			const cached = self.detailsCache[key]
			if not force and cached and tick() - cached.at < (cached.data and 60 or 15) then
				if cached.data then results[id] = cached.data end
			else
				const url = self.latency.cfg.betterBase.."/servers/place/"..tostring(pid).."/server/"..Services.HttpService:UrlEncode(id)
				const data = self:j(self:get(url))
				const detail = type(data) == "table" and self:normalizeBetter(data.server, dcs) or nil
				if detail then results[id] = detail end
				self.detailsCache[key] = {at = tick(); data = detail or false}
			end
		end
	else
		const index = self:getBetterIndex(pid, nil, force)
		for _, rawId in serverIds do
			const id = tostring(rawId)
			const detail = self:normalizeBetter(index[id], dcs)
			if detail then results[id] = detail end
		end
	end
	return results
end

NAStuff.srv.fetchDetails = function(self, placeId, serverIds, force, provider)
	if type(serverIds) ~= "table" or #serverIds == 0 then return {} end
	const api = Lower(tostring(provider or "auto"))
	if api == "betterblox" or api == "better" or api == "bb" then
		return self:fetchBetterDetails(placeId, serverIds, force)
	end
	const out = self:fetchRoDetails(placeId, serverIds, force)
	if api == "rovalra" then return out end
	const missing = {}
	for _, rawId in serverIds do
		const id = tostring(rawId)
		const detail = out[id]
		if not detail or not detail.city or detail.city == "Unknown" then missing[#missing + 1] = id end
	end
	const more = self:fetchBetterDetails(placeId, missing, force)
	for id, detail in more do
		const prior = out[id]
		if prior then
			for key, value in detail do prior[key] = value end
		else
			out[id] = detail
		end
	end
	return out
end

NAStuff.srv.pickBetterRegion = function(self, placeId, query)
	const dcIds, locs = {}, {}
	for id, loc in self:getBetterDcs(false) do
		if self:matchLocation(loc, query) then
			dcIds[#dcIds + 1] = tostring(id)
			locs[id] = loc
		end
	end
	if #dcIds == 0 then return nil, "BetterBLOX has no matching datacenter" end
	table.sort(dcIds)
	const raw = self:getBetterIndex(placeId, dcIds, false)
	const ids = {}
	for id, row in raw do
		if locs[tonumber(row.datacenter or row.datacenterId)] then ids[id] = true end
	end
	if not next(ids) then return nil, "BetterBLOX has no indexed servers for this location" end
	const servers = self:collect(placeId, "low", self.latency.cfg.publicPageLimit, ids)
	const server = self:sortCandidates(servers, "low")[1]
	if not server then return nil, "BetterBLOX found no joinable public server for this location" end
	const detail = self:normalizeBetter(raw[server.id], locs)
	for key, value in detail do server[key] = value end
	server.region = detail.city or detail.regionName or detail.country
	return server
end

NAStuff.srv.getServerDetail = function(self, placeId, serverId, force, provider)
	const id = tostring(serverId or "")
	if id == "" then return nil end
	const map = self:fetchDetails(placeId, { id }, force, provider)
	return map[id]
end

NAStuff.srv.getCounts = function(self, placeId, force)
	const pid = tonumber(placeId) or tonumber(PlaceId)
	const key = tostring(pid)
	const cached = self.countsCache[key]
	if not force and type(cached) == "table" and tick() - (tonumber(cached.at) or 0) < self.countsTtl and type(cached.data) == "table" then
		return cached.data
	end
	const url = self.latency.cfg.rovalraBase.."/v1/servers/counts?place_id="..tostring(pid)
	const decoded = self:j(self:get(url))
	if type(decoded) == "table" and type(decoded.counts) == "table" then
		self.countsCache[key] = { at = tick(); data = decoded.counts }
		return decoded.counts
	end
	return nil
end

NAStuff.srv.queryRoValraServers = function(self, path, pageLimit)
	local cursor = nil
	local page = 0
	const out = {}
	const seen = {}
	while page < math.max(1, math.floor(tonumber(pageLimit) or 3)) do
		page += 1
		local url = self.latency.cfg.rovalraBase..path
		if cursor and cursor ~= "" and cursor ~= "0" then
			url ..= (url:find("?", 1, true) and "&" or "?").."cursor="..Services.HttpService:UrlEncode(tostring(cursor))
		end
		const decoded = self:j(self:get(url))
		if type(decoded) ~= "table" or type(decoded.servers) ~= "table" then break end
		for _, raw in decoded.servers do
			if type(raw) == "table" then
				const id = tostring(raw.server_id or raw.id or "")
				if id ~= "" and not seen[id] then
					seen[id] = true
					out[#out + 1] = raw
				end
			end
		end
		cursor = decoded.next_cursor or decoded.nextPageCursor
		if not cursor or cursor == "" or cursor == "0" then break end
		Wait(self.latency.cfg.requestDelay)
	end
	return out
end

NAStuff.srv.matchPublicByIds = function(self, placeId, orderedIds, mode, provider, known)
	const pid = tonumber(placeId) or tonumber(PlaceId)
	if type(orderedIds) ~= "table" or #orderedIds == 0 then return nil, "no servers returned" end
	const _, byId = self:collect(pid, mode == "fullest" and "high" or "low", self.latency.cfg.publicPageLimit, known)
	for _, id in orderedIds do
		const key = tostring(id)
		const server = byId[key]
		if server then
			const detail = if known then self:normalizeDetail(known[key]) else self:fetchDetails(pid, { key }, false, provider)[key]
			if detail then
				for k, v in detail do server[k] = v end
				if detail.city then server.region = detail.city end
				if detail.regionLabel then server.regionLabel = detail.regionLabel end
			end
			const ready, model = self:refreshLatencyModel(false, provider)
			if ready and server.city then
				server.regionRank = model.cityRank[server.city]
				server.latency = model.cityPing[server.city]
				server.latencyEstimated = tonumber(server.latency) ~= nil
			end
			if not tonumber(server.latency) and (tonumber(server.ping) or 0) > 0 then
				server.latency = tonumber(server.ping)
				server.latencyEstimated = false
			end
			return server
		end
	end
	return nil, "matching public server was not found"
end

NAStuff.srv.pickUptime = function(self, placeId, kind)
	const pid = tonumber(placeId) or tonumber(PlaceId)
	kind = kind == "newest" and "newest" or "oldest"
	const raw = self:queryRoValraServers("/v1/servers/"..kind.."?place_id="..tostring(pid).."&limit=100", 4)
	const ids = {}
	for _, entry in raw do
		const id = tostring(entry.server_id or entry.id or "")
		if id ~= "" and not (pid == tonumber(game.PlaceId) and id == tostring(game.JobId)) then ids[#ids + 1] = id end
	end
	return self:matchPublicByIds(pid, ids, "low")
end

NAStuff.srv.pickVersion = function(self, placeId, version)
	const pid = tonumber(placeId) or tonumber(PlaceId)
	const ver = tonumber(version)
	if not ver then return nil, "invalid place version" end
	const path = "/v1/servers/versions?place_id="..tostring(pid).."&place_version="..tostring(math.floor(ver)).."&limit=100"
	const raw = self:queryRoValraServers(path, 4)
	const ids = {}
	for _, entry in raw do
		const id = tostring(entry.server_id or entry.id or "")
		if id ~= "" and not (pid == tonumber(game.PlaceId) and id == tostring(game.JobId)) then ids[#ids + 1] = id end
	end
	return self:matchPublicByIds(pid, ids, "low")
end

NAStuff.srv.pickOldestVersion = function(self, placeId)
	const pid = tonumber(placeId) or tonumber(PlaceId)
	const counts = self:getCounts(pid, false)
	local version = counts and tonumber(counts.oldest_place_version) or nil
	if not version and counts and type(counts.place_versions) == "table" then
		for _, rawVersion in counts.place_versions do
			const n = tonumber(type(rawVersion) == "table" and (rawVersion.place_version or rawVersion.version) or rawVersion)
			if n and (not version or n < version) then version = n end
		end
	end
	if not version then return nil, "oldest active place version is unavailable" end
	local server, err = self:pickVersion(pid, version)
	if server then server.requestedVersion = version end
	return server, err, version
end

NAStuff.srv.pickRoRegion = function(self, placeId, query)
	const pid = tonumber(placeId) or tonumber(PlaceId)
	const base = "/v1/servers/region?place_id="..tostring(pid).."&limit=100"
	const rows, ids, seen = {}, {}, {}
	const function add(filter)
		if seen[filter] then return end
		seen[filter] = true
		for _, row in self:queryRoValraServers(base..filter, 3) do
			const id = tostring(row.server_id or row.id or "")
			if id ~= "" and not rows[id] and self:matchLocation(row, query) then
				rows[id] = row
				ids[#ids + 1] = id
			end
		end
	end

	const http = Services.HttpService
	if query.code then
		add("&region="..http:UrlEncode(query.code))
	else
		for _, dc in query.dcs do
			const loc = type(dc) == "table" and dc.location
			if type(loc) == "table" and loc.city and self:matchLocation(loc, query) then
				add("&city="..http:UrlEncode(loc.city).."&region="..http:UrlEncode(loc.country or ""))
			end
		end
		if not next(seen) then
			const name = http:UrlEncode(query.raw)
			add("&city="..name)
			if #ids == 0 then add("&region="..name) end
		end
	end
	if #ids == 0 then return nil, "RoValra has no indexed servers for this location" end
	const server, err = self:matchPublicByIds(pid, ids, "low", "rovalra", rows)
	if server then server.provider = "RoValra" end
	return server, err
end

NAStuff.srv.pickRegion = function(self, placeId, value, provider)
	const query = self:resolveRegionQuery(value)
	if not query then return nil, "enter a city, region, country, or country code" end
	const api = Lower(tostring(provider or "auto"))
	local server, err
	if api ~= "betterblox" then server, err = self:pickRoRegion(placeId, query) end
	if not server and api ~= "rovalra" then server, err = self:pickBetterRegion(placeId, query) end
	return server, err, server and {city = server.city; country = server.country}
end

NAStuff.srv.refreshLatencyModel = function(self, force, provider)
	const latency = self.latency
	const cfg = latency.cfg
	const api = Lower(tostring(provider or "auto"))
	latency.models = latency.models or {}
	if not latency.models[api] then
		latency.models[api] = { ready = false; loading = false; updatedAt = 0 }
	end
	const model = latency.models[api]
	if api == "auto" then latency.model = model end
	const now = tick()
	if not force and model.ready == true and now - (tonumber(model.updatedAt) or 0) < cfg.modelTtl then
		return true, model
	end
	if model.loading == true then
		const started = tick()
		while model.loading == true and tick() - started < 10 do
			Wait(0.05)
		end
		return model.ready == true, model
	end

	model.loading = true
	local okRefresh = pcall(function()
		model.ready = false
		model.datacenters = {}
		model.origin = nil
		model.originIsReal = false
		model.coefficient = cfg.defaultCoefficient
		model.baseOverheadMs = cfg.baseOverheadMs
		model.currentServerRealPing = nil
		model.currentServerCity = nil
		model.cityOrder = {}
		model.cityRank = {}
		model.cityPing = {}

		const dcDecoded = api ~= "betterblox" and self:getRoDcs(force) or nil
		if type(dcDecoded) == "table" then
			const seenCities = {}
			for _, dc in dcDecoded do
				const location = type(dc) == "table" and dc.location or nil
				const city = type(location) == "table" and location.city or nil
				local lat, lon = self:extractLatLon(location)
				if city and lat and lon and not seenCities[tostring(city)] then
					seenCities[tostring(city)] = true
					model.datacenters[#model.datacenters + 1] = {
						city = tostring(city);
						country = tostring(location.country or "");
						region = tostring(location.region or "");
						lat = lat;
						lon = lon;
					}
				end
			end
		end

		if api ~= "rovalra" then
			for _, loc in self:getBetterDcs(false) do
				local lat, lon = self:extractLatLon(loc)
				local found = false
				for _, dc in model.datacenters do
					if Lower(dc.city) == Lower(tostring(loc.city)) then found = true break end
				end
				if lat and lon and not found then
					model.datacenters[#model.datacenters + 1] = {
						city = tostring(loc.city); region = tostring(loc.region or "");
						country = tostring(loc.country or ""); lat = lat; lon = lon;
					}
				end
			end

		end
		local geoDecoded = self:j(self:get(cfg.geolocationUrl))
		local geoLat, geoLon = self:extractLatLon(geoDecoded)
		if not geoLat or not geoLon then
			geoDecoded = self:j(self:get(cfg.geolocationFallback))
		end
		if type(geoDecoded) == "table" then
			local lat, lon = self:extractLatLon(geoDecoded)
			if lat and lon then
				model.origin = { lat = lat; lon = lon }
				model.originIsReal = true
			end
		end

		model.currentServerCity = self:getCurrentServerCity(api)
		if not model.origin and model.currentServerCity then
			for _, dc in model.datacenters do
				if dc.city == model.currentServerCity then
					model.origin = { lat = dc.lat; lon = dc.lon }
					break
				end
			end
		end

		if model.origin and #model.datacenters > 0 then
			const ranked = {}
			for _, dc in model.datacenters do
				ranked[#ranked + 1] = {
					city = dc.city;
					distance = self:haversine(model.origin.lat, model.origin.lon, dc.lat, dc.lon);
				}
			end
			table.sort(ranked, function(a, b)
				return a.distance < b.distance
			end)

			const realPing = self:getCurrentRealPing()
			if realPing and model.currentServerCity then
				model.currentServerRealPing = math.floor(realPing)
				for _, entry in ranked do
					if entry.city == model.currentServerCity and entry.distance > cfg.calibrationMinDistanceKm then
						const coefficient = (realPing - cfg.baseOverheadMs) / math.sqrt(entry.distance)
						if coefficient == coefficient and coefficient > 0 then
							model.coefficient = math.clamp(coefficient, cfg.minCoefficient, cfg.maxCoefficient)
						end
						break
					end
				end
			end

			for index, entry in ranked do
				const estimated = math.max(1, math.floor(model.coefficient * math.sqrt(math.max(0, entry.distance)) + model.baseOverheadMs))
				model.cityOrder[index] = {
					city = entry.city;
					distance = entry.distance;
					latency = estimated;
					rank = index;
				}
				model.cityRank[entry.city] = index
				model.cityPing[entry.city] = estimated
			end
			model.ready = #model.cityOrder > 0
		end
		model.updatedAt = tick()
	end)
	model.loading = false
	if not okRefresh then
		model.ready = false
	end
	return model.ready == true, model
end

NAStuff.srv.pg = function(self, cid, mode, placeId)
	const pid = tonumber(placeId) or tonumber(PlaceId)
	const sortOrder = mode == "high" and "Desc" or "Asc"
	local q = "?sortOrder="..sortOrder.."&excludeFullGames=true&limit=100"
	if cid and cid ~= "" then
		q ..= "&cursor="..Services.HttpService:UrlEncode(cid)
	end

	const primaryBase = self.b[1] or "https://games.rotunnel.com"
	local body = self:get(primaryBase.."/v1/games/"..tostring(pid).."/servers/Public"..q)
	if type(body) == "string" and #body > 0 then
		const js = self:j(body)
		if type(js) == "table" and type(js.data) == "table" then
			return js.data, js.nextPageCursor
		end
	end

	local wq = "placeId="..tostring(pid)
	wq ..= "&sortOrder="..Services.HttpService:UrlEncode(sortOrder).."&excludeFullGames=true"
	if cid and cid ~= "" then
		wq ..= "&cursor="..Services.HttpService:UrlEncode(cid)
	end
	const wbody = self:get(NAStuff.srvWorker.."/servers?"..wq)
	if type(wbody) == "string" and #wbody > 0 then
		const js = self:j(wbody)
		if type(js) == "table" and type(js.data) == "table" then
			return js.data, js.nextPageCursor
		end
	end

	for index = 2, #self.b do
		const base = self.b[index]
		body = self:get(base.."/v1/games/"..tostring(pid).."/servers/Public"..q)
		if type(body) == "string" and #body > 0 then
			const js = self:j(body)
			if type(js) == "table" and type(js.data) == "table" then
				return js.data, js.nextPageCursor
			end
		end
	end

	return nil, nil
end

NAStuff.srv.collect = function(self, placeId, mode, pageLimit, wanted)
	const pid = tonumber(placeId) or tonumber(PlaceId)
	const maxPages = math.clamp(math.floor(tonumber(pageLimit) or self.latency.cfg.publicPageLimit), 1, self.latency.cfg.publicPageLimit)
	const servers = {}
	const byId = {}
	local cursor = nil
	local page = 0
	while page < maxPages do
		page += 1
		local data, nextCursor = self:pg(cursor, mode, pid)
		if type(data) ~= "table" then
			break
		end
		for _, raw in data do
			if type(raw) == "table" then
				const id = tostring(raw.id or "")
				const playing = tonumber(raw.playing) or 0
				const maximum = tonumber(raw.maxPlayers or raw.max) or 0
				if id ~= "" and (not wanted or wanted[id]) and maximum > playing and not (pid == tonumber(game.PlaceId) and id == tostring(game.JobId)) and not byId[id] then
					const server = {
						id = id;
						playing = playing;
						max = maximum;
						ping = tonumber(raw.ping) or 0;
						fps = tonumber(raw.fps) or 0;
					}
					servers[#servers + 1] = server
					byId[id] = server
				end
			end
		end
		if not nextCursor or nextCursor == "" or (wanted and #servers > 0) then
			break
		end
		cursor = nextCursor
		Wait()
	end
	return servers, byId
end

NAStuff.srv.regionIds = function(self, placeId, city)
	const pid = tonumber(placeId) or tonumber(PlaceId)
	const cfg = self.latency.cfg
	const key = tostring(pid).."|"..tostring(city)
	const cached = self.latency.regionCache[key]
	if type(cached) == "table" and tick() - (tonumber(cached.at) or 0) < cfg.regionTtl and type(cached.ids) == "table" then
		return cached.ids
	end

	const ids = {}
	local cursor = "0"
	local pages = 0
	while cursor and pages < cfg.regionPageLimit do
		pages += 1
		const url = cfg.rovalraBase.."/v1/servers/region?place_id="..tostring(pid).."&city="..Services.HttpService:UrlEncode(tostring(city)).."&limit=100&cursor="..Services.HttpService:UrlEncode(tostring(cursor))
		const decoded = self:j(self:get(url))
		if type(decoded) ~= "table" or type(decoded.servers) ~= "table" then
			break
		end
		for _, entry in decoded.servers do
			if type(entry) == "table" and entry.server_id then
				ids[tostring(entry.server_id)] = true
			end
		end
		cursor = decoded.next_cursor
		if not cursor or cursor == "" or cursor == "0" then
			break
		end
		Wait(cfg.requestDelay)
	end
	self.latency.regionCache[key] = { at = tick(); ids = ids }
	return ids
end

NAStuff.srv.sortCandidates = function(self, servers, mode)
	table.sort(servers, function(a, b)
		if mode == "low" then
			if a.playing ~= b.playing then return a.playing < b.playing end
		elseif mode == "high" then
			if a.playing ~= b.playing then return a.playing > b.playing end
		else
			const ap = tonumber(a.ping) or 0
			const bp = tonumber(b.ping) or 0
			if ap ~= bp then
				if ap <= 0 then return false end
				if bp <= 0 then return true end
				return ap < bp
			end
			if a.playing ~= b.playing then return a.playing > b.playing end
		end
		const ap = tonumber(a.ping) or 0
		const bp = tonumber(b.ping) or 0
		if ap ~= bp then
			if ap <= 0 then return false end
			if bp <= 0 then return true end
			return ap < bp
		end
		return tostring(a.id) < tostring(b.id)
	end)
	return servers
end

NAStuff.srv.pickLatency = function(self, placeId, mode)
	const pid = tonumber(placeId) or tonumber(PlaceId)
	mode = mode == "low" and "low" or mode == "high" and "high" or "ping"
	const servers, byId = self:collect(pid, mode, self.latency.cfg.hopPageLimit)
	if #servers == 0 then
		return nil, "no joinable public servers"
	end

	const ready, model = self:refreshLatencyModel(false, "rovalra")
	if ready then
		for index, cityInfo in model.cityOrder do
			if index > self.latency.cfg.regionCityLimit then break end
			const ids = self:regionIds(pid, cityInfo.city)
			const matches = {}
			for id in ids do
				const server = byId[id]
				if server then
					server.region = cityInfo.city
					server.regionRank = cityInfo.rank
					server.latency = cityInfo.latency
					server.latencyEstimated = true
					matches[#matches + 1] = server
				end
			end
			if #matches > 0 then
				self:sortCandidates(matches, mode)
				return matches[1]
			end
			Wait(self.latency.cfg.requestDelay)
		end
	end

	self:sortCandidates(servers, mode)
	const fallback = servers[1]
	if fallback then
		fallback.latency = tonumber(fallback.ping) or 0
		fallback.latencyEstimated = false
		if mode == "ping" and fallback.latency <= 0 then
			return nil, "no latency data is available for these servers"
		end
	end
	return fallback, fallback and nil or "no joinable public servers"
end

NAStuff.srv.pickHybrid = function(self, placeId, mode, provider)
	const pid = tonumber(placeId) or tonumber(PlaceId)
	const servers = self:collect(pid, mode, self.latency.cfg.hopPageLimit)
	if #servers == 0 then return nil, "no joinable public servers" end
	const _, _, model = self:enrichLatencyList(pid, servers, provider)
	local country
	if mode == "ping" and not model.originIsReal then
		pcall(function()
			const svc = SafeGetService("LocalizationService")
			const code = svc:GetCountryRegionForPlayerAsync(Services.Players.LocalPlayer)
			country = Lower(tostring(code or "")):match("^%a%a$")
		end)
	end
	const function rank(srv)
		if model.originIsReal then return srv.regionRank or math.huge end
		if country and Lower(tostring(srv.countryCode or "")) == country then return 1 end
		return math.huge
	end
	const function ping(srv)
		const n = if mode == "ping" then tonumber(srv.ping) else tonumber(srv.latency) or tonumber(srv.ping)
		return n and n > 0 and n or math.huge
	end
	table.sort(servers, function(a, b)
		if mode == "low" and a.playing ~= b.playing then return a.playing < b.playing end
		if mode == "ping" then
			const ar, br = rank(a), rank(b)
			if ar ~= br then return ar < br end
		end
		const ap, bp = ping(a), ping(b)
		if ap ~= bp then return ap < bp end
		if a.playing ~= b.playing then return a.playing > b.playing end
		return tostring(a.id) < tostring(b.id)
	end)
	const server = servers[1]
	if mode == "ping" then
		const ranked = rank(server) < math.huge
		if not ranked and ping(server) == math.huge then return nil, "no latency data is available for these servers" end
		if not ranked or not model.originIsReal then
			server.latency = tonumber(server.ping) or 0
			server.latencyEstimated = false
		end
	end
	return server
end

NAStuff.srv.latencyText = function(self, server, fallbackLatency)
	server = type(server) == "table" and server or {}
	const value = tonumber(server.latency) or tonumber(fallbackLatency) or tonumber(server.ping) or 0
	local text = value > 0 and ((server.latencyEstimated == true and "~" or "")..tostring(math.floor(value)).." ms") or "unknown latency"
	const regionText = server.regionLabel or server.region
	if regionText and tostring(regionText) ~= "" then
		text ..= " | "..tostring(regionText)
	end
	return text
end

NAStuff.srv.enrichLatencyList = function(self, placeId, servers, provider)
	const pid = tonumber(placeId) or tonumber(PlaceId)
	if type(servers) ~= "table" or #servers == 0 then return servers, false end
	const ids = {}
	const byId = {}
	for _, server in servers do
		if type(server) == "table" and server.id then
			const id = tostring(server.id)
			if #ids < self.latency.cfg.detailLimit then ids[#ids + 1] = id end
			byId[id] = server
			server.region = nil
			server.regionLabel = nil
			server.regionRank = nil
			server.latency = nil
			server.latencyEstimated = false
		end
	end
	const detailMap = self:fetchDetails(pid, ids, false, provider)
	const modelReady, model = self:refreshLatencyModel(false, provider)
	local mapped = 0
	for id, detail in detailMap do
		const server = byId[id]
		if server and detail then
			for k, v in detail do server[k] = v end
			server.region = detail.city or detail.regionName or detail.country
			server.regionLabel = detail.regionLabel or server.region
			if modelReady and detail.city then
				server.regionRank = model.cityRank[detail.city]
				server.latency = model.cityPing[detail.city]
				server.latencyEstimated = tonumber(server.latency) ~= nil
			end
			mapped += 1
		end
	end

	for _, server in servers do
		if type(server) == "table" and not tonumber(server.latency) then
			const rawPing = tonumber(server.ping) or 0
			if rawPing > 0 then
				server.latency = rawPing
				server.latencyEstimated = false
			end
		end
	end
	return servers, modelReady, model
end

NAStuff.srv.scan = function(self, mode, placeId)
	const server, err = self:pickLatency(placeId or PlaceId, mode)
	if not server then
		return nil, nil, nil, nil, err
	end
	return server.id, server.playing, tonumber(server.latency) or tonumber(server.ping), server, nil
end

NAmanage.ServerhopDefault = function()
	DebugNotif("Teleporting with the legacy serverhop method")
	local ok, err = NAmanage.TeleportServiceCall("Teleport", { PlaceId, Services.Players.LocalPlayer }, {
		placeId = PlaceId;
		placeName = game.Name;
		action = "SERVER HOP";
		detail = "Legacy Roblox serverhop";
	})
	if not ok then
		DebugNotif("Teleport failed: "..tostring(err or "?"))
		return false, err
	end
	return true
end

NAmanage.ServerhopLegacyPick = function(mode)
	if type(NAStuff.srv) ~= "table" or type(NAStuff.srv.collect) ~= "function" then
		return nil, "legacy server list is unavailable"
	end
	mode = mode == "low" and "low" or mode == "high" and "high" or "ping"
	local pageLimit = 4
	if type(NAStuff.srv.latency) == "table" and type(NAStuff.srv.latency.cfg) == "table" then
		pageLimit = tonumber(NAStuff.srv.latency.cfg.hopPageLimit) or pageLimit
	end
	local servers = NAStuff.srv:collect(PlaceId, mode, pageLimit)
	if type(servers) ~= "table" or #servers == 0 then
		return nil, "no joinable public servers"
	end
	if type(NAStuff.srv.sortCandidates) == "function" then
		NAStuff.srv:sortCandidates(servers, mode)
	else
		table.sort(servers, function(a, b)
			if mode == "low" and a.playing ~= b.playing then return a.playing < b.playing end
			if mode == "high" and a.playing ~= b.playing then return a.playing > b.playing end
			const ap, bp = tonumber(a.ping) or math.huge, tonumber(b.ping) or math.huge
			if ap ~= bp then return ap < bp end
			return tostring(a.id) < tostring(b.id)
		end)
	end
	const server = servers[1]
	if mode == "ping" and (not server or (tonumber(server.ping) or 0) <= 0) then
		return nil, "Roblox did not report a valid ping for these servers"
	end
	if server then
		server.latency = tonumber(server.ping) or 0
		server.latencyEstimated = false
	end
	return server
end

NAmanage.ServerhopLegacyServer = function(mode, action, label)
	DebugNotif("Searching with the legacy Roblox server list")
	local server, scanErr = NAmanage.ServerhopLegacyPick(mode)
	if not server or not server.id then
		DebugNotif("No server found"..(scanErr and (": "..tostring(scanErr)) or ""))
		return false, scanErr or "no server found"
	end
	const ping = tonumber(server.ping) or 0
	const pingText = ping > 0 and (tostring(math.floor(ping)).." ms") or "unknown ping"
	DebugNotif(tostring(label or "Serverhop").." | "..pingText.." | Players: "..tostring(server.playing or "?"))
	return NAmanage.TeleportServiceCall("TeleportToPlaceInstance", { PlaceId, server.id, Services.Players.LocalPlayer }, {
		placeId = PlaceId;
		placeName = game.Name;
		action = tostring(action or "SERVER HOP");
		detail = "Legacy Roblox data | Ping: "..pingText.." | Players: "..tostring(server.playing or "?");
	})
end

NAmanage.ServerhopAdvanced = function()
	DebugNotif("Searching with RoValra for the best-latency server")
	if type(NAStuff.srv) ~= "table" or type(NAStuff.srv.scan) ~= "function" then
		DebugNotif("RoValra serverhop is unavailable")
		return false, "RoValra serverhop is unavailable"
	end

	local id, pl, latency, server, scanErr = NAStuff.srv:scan("high")
	if not id then
		DebugNotif("No server found"..(scanErr and (": "..tostring(scanErr)) or ""))
		return false, scanErr or "no server found"
	end

	const latencyText = NAStuff.srv:latencyText(server, latency)
	DebugNotif("serverhopping | "..latencyText.." | Player Count: "..tostring(pl or "?"))
	local ok, err = NAmanage.TeleportServiceCall("TeleportToPlaceInstance", { PlaceId, id, Services.Players.LocalPlayer }, {
		placeId = PlaceId;
		placeName = game.Name;
		action = "SERVER HOP";
		detail = "RoValra | Latency: "..latencyText.." | Players: "..tostring(pl or "?");
	})
	if not ok then
		DebugNotif("Teleport failed: "..tostring(err or "?"))
		return false, err
	end
	return true, id, pl, latency, server
end

