NAmanage.ServerhopHybrid = function(mode, title, provider)
	const api = provider or "auto"
	const label = api == "betterblox" and "BetterBLOX" or api == "rovalra" and "RoValra" or "Auto Regions"
	DebugNotif("Searching with "..label)
	const server, err = NAStuff.srv:pickHybrid(PlaceId, mode, api)
	if not server then
		DebugNotif("No server found: "..tostring(err or "unknown"))
		return false, err
	end
