end

NAmanage.ServerhopChoices = function(mode, title)
	const items = {
		{ Text = "Roblox API", Key = "roblox", Callback = function()
			return NAmanage.ServerhopLegacyServer(mode, title, "Roblox API")
		end },
		{ Text = mode == "ping" and "Near Me (Auto)" or "Auto Regions", Key = "auto", Callback = function()
			return NAmanage.ServerhopHybrid(mode, title, "auto")
		end },
		{ Text = "RoValra", Key = "rovalra", Callback = function()
			if mode == "low" then return NAmanage.SmallServerhopRoValra() end
			if mode == "ping" then return NAmanage.PingServerhopRoValra() end
			return NAmanage.ServerhopAdvanced()
		end },
		{ Text = "BetterBLOX", Key = "betterblox", Callback = function()
			return NAmanage.ServerhopHybrid(mode, title, "betterblox")
		end },
	}
	if mode == "high" then
		table.insert(items, 1, { Text = "Roblox Default", Key = "default", Callback = NAmanage.ServerhopDefault })
	elseif mode == "ping" then
		items[1], items[2] = items[2], items[1]
	end
	local picked = false
	for _, item in items do
		const run = item.Callback
		item.Callback = function(...)
			if picked then return false end
			picked = true
			return run(...)
		end
	end
	return items
end

NAmanage.ServerhopResolveMethod = function(method, mode, title)
	const key = Lower(tostring(method or "")):gsub("[%s_%-%+]+", "")
	const aliases = {
		legacy = "roblox"; old = "roblox"; api = "roblox";
		advanced = "rovalra"; high = "rovalra"; rivalra = "rovalra";
		hybrid = "auto"; combined = "auto"; robloxrovalra = "auto";
		bb = "betterblox"; better = "betterblox";
	}
	local choice = aliases[key] or key
	if mode == "high" and (key == "legacy" or key == "old") then choice = "default" end
	if choice == "default" and mode ~= "high" then choice = "roblox" end
	const items = NAmanage.ServerhopChoices(mode, title)
	if choice ~= "" then
		for _, item in items do
			if item.Key == choice then return item.Callback() end
		end
		DoNotif("Choose auto, rovalra, betterblox, or roblox"..(mode == "high" and " (or default)." or "."), 4, "Serverhop")
		return false
	end
	const show = Window or DoWindow
	if type(show) == "function" then
		show({
			Title = title or "Serverhop",
			Description = mode == "ping"
				and "Near Me checks both location providers for servers near you. Roblox API sorts by reported ping."
				or "Auto Regions uses both location APIs. You can also choose RoValra or BetterBLOX separately. Roblox API has reported ping without server locations."..(mode == "high" and " Roblox Default lets Roblox choose the server." or ""),
			Buttons = items,
		})
		return true
	end
	return NAmanage.ServerhopHybrid(mode, title, "auto")
end

