			const baseCF = NAmanage.UG_clientCFrame(hrp) or hrp.CFrame
			NAmanage.UG_setRootCFrame(hrp, CFrame.new(sinX * dist, sinY * dist, 0) * (baseCF - baseCF.p) + thrp.CFrame.p)
