do
	const function send(inst, event, ...)
		const fire = type(replicatesignal) == "function" and replicatesignal or replicate_signal
		if type(fire) ~= "function" then return false, "Your executor does not support replicatesignal." end
		if not inst then return false, "The signal source is unavailable." end
		const found, sig = pcall(function() return inst[event] end)
		if not found or typeof(sig) ~= "RBXScriptSignal" then
			return false, event.." is unavailable on this Roblox build."
		end
		const check = cansignalreplicate or can_signal_replicate or issignalreplicateable
		if type(check) == "function" then
			const checked, allowed = pcall(check, sig)
			if not checked or allowed ~= true then return false, event.." cannot replicate in this session." end
		end
		const ok, err = pcall(fire, sig, ...)
		if not ok then return false, "Could not replicate "..event..": "..tostring(err) end
		return true
	end

	cmd.register({
		name = "serverreset",
		aliases = { "sreset" },
		description = "Request a server-side reset for your character",
		usage = "serverreset (sreset)",
		callback = function()
			const hum = getHum()
			if not hum or not hum:IsA("Humanoid") or hum.Health <= 0 then
				return DoNotif("Your character is already dead or unavailable.", 3)
			end
			const ok, err = send(hum, "ServerResetCharacter")
			if not ok then DoNotif(err, 4) end
		end,
	})

	cmd.register({
		name = "signalclick",
		aliases = { "clicksignal" },
		description = "Click the in-range ClickDetector you are aiming at using signal replication",
		usage = "signalclick (clicksignal)",
		callback = function()
			const ws = Services.Workspace
			const char = getChar()
			const root = char and getRoot(char)
			if not root then return DoNotif("Your character is unavailable.", 3) end
			local part
			local point
			if IsOnMobile then
				const cam = ws.CurrentCamera
				if not cam then return end
				const ray = cam:ViewportPointToRay(cam.ViewportSize.X / 2, cam.ViewportSize.Y / 2)
				const params = RaycastParams.new()
				params.FilterType = Enum.RaycastFilterType.Exclude
				params.FilterDescendantsInstances = {char}
				const hit = ws:Raycast(ray.Origin, ray.Direction * 512, params)
				if hit then part, point = hit.Instance, hit.Position end
			else
				part = NAmanage.GetMouseTargetPart(mouse, {char})
				if part then point = mouse.Hit.Position end
			end
			local obj = part
			while obj and obj ~= ws do
				const det = obj:FindFirstChildOfClass("ClickDetector")
				if det then
					if (root.Position - point).Magnitude > det.MaxActivationDistance then
						return DoNotif("Move closer to the ClickDetector.", 3)
					end
					const ok, err = send(det, "MouseActionReplicated", LocalPlayer, 0)
					if not ok then DoNotif(err, 4) end
					return
				end
				obj = obj.Parent
			end
			DoNotif("Aim at a part with a ClickDetector.", 3)
		end,
	})

	cmd.register({
		name = "instantrespawn",
		aliases = { "instantr", "irespawn" },
		description = "respawn instantly",
		usage = "instantrespawn (instantr, irespawn)",
		callback = function()
			const char = getChar()
			const rootPart = char and getRoot(char)
			const respawnCF = rootPart and (NAmanage.UG_clientCFrame(rootPart) or rootPart.CFrame) or nil
			const cam = Services.Workspace.CurrentCamera
			const ok, err = send(LocalPlayer, "ConnectDiedSignalBackend")
			if not ok then return DoNotif(err.." Use serverreset for a normal reset.", 5) end

			Wait(Services.Players.RespawnTime - 0.165)

			const humanoid = getHum()
			if humanoid then
				humanoid:ChangeState(Enum.HumanoidStateType.Dead)
			end

			Wait(0.5)

			if respawnCF then
				const newChar = getChar()
				const newRoot = newChar and getRoot(newChar)
				if newRoot then
					NAmanage.UG_setClientCFrame(newRoot, respawnCF)
				end
			end

			Services.Workspace.CurrentCamera = cam
		end,
	})
end

function getAllTools()
	const tools={}
	const backpack=localPlayer:FindFirstChildWhichIsA("Backpack")
	if backpack then
		for i,v in backpack:GetChildren() do
			if v:IsA("Tool") then
				Insert(tools,v)
			end
		end
	end
	for i,v in character:GetChildren() do
		if v:IsA("Tool") then
			Insert(tools,v)
		end
	end
	return tools
end

cmd.register({
	name = "circlemath",
	aliases = { "cm" },
	description = "Gay circle math\nModes: a,b,c,d,e",
	usage = "circlemath <mode> <size>",
	requiresArguments = true,
	callback = function(mode, size)
		const mode = mode or "a"
		const backpack = getBp()
		NAlib.disconnect("cm")
		if backpack and character.Parent then
			const tools = getAllTools()
			for i, tool in tools do
				local cpos, g = (math.pi*2)*(i/#tools), CFrame.new()
				const tcon = {}
				tool.Parent = backpack

				if mode == "a" then
					size = tonumber(size) or 2
					g = (
						CFrame.new(0, 0, size)*
							CFrame.Angles(rad(90), 0, cpos)
					)
				elseif mode == "b" then
					size = tonumber(size) or 2
					g = (
						CFrame.new(i - #tools/2, 0, 0)*
							CFrame.Angles(rad(90), 0, 0)
					)
				elseif mode == "c" then
					size = tonumber(size) or 2
					g = (
						CFrame.new(cpos/3, 0, 0)*
							CFrame.Angles(rad(90), 0, cpos*2)
					)
				elseif mode == "d" then
					size = tonumber(size) or 2
					g = (
						CFrame.new(clamp(tan(cpos), -3, 3), 0, 0)*
							CFrame.Angles(rad(90), 0, cpos)
					)
				elseif mode == "e" then
					size = tonumber(size) or 2
					g = (
						CFrame.new(0, 0, clamp(tan(cpos), -5, 5))*
							CFrame.Angles(rad(90), 0, cpos)
					)
				end
				tool.Grip = g
				tool.Parent = character

				tcon[#tcon] = NAlib.connect("cm", mouse.Button1Down:Connect(function()
					tool:Activate()
				end))
				tcon[#tcon] = NAlib.connect("cm", tool.Changed:Connect(function(p)
					if p == "Grip" and tool.Grip ~= g then
						tool.Grip = g
					end
				end))

				NAlib.connect("cm", tool.AncestryChanged:Connect(function()
					for i = 1, #tcon do
						tcon[i]:Disconnect()
					end
				end))
			end
		end
	end,
})

