NAmanage.toolCache = NAmanage.ensureWeakKeyTable(NAmanage.toolCache or {})
NAmanage.toolGrabCol = NAmanage.ensureWeakKeyTable(NAmanage.toolGrabCol or {})
NAmanage.grabBusy = NAmanage.ensureWeakKeyTable(NAmanage.grabBusy or {})
NAmanage.toolCacheReady = NAmanage.toolCacheReady or false

NAmanage.isOwnPackTool = NAmanage.isOwnPackTool or function(tool)
	if typeof(tool) ~= "Instance" or not tool:IsA("Tool") then
		return false
	end

	const char = getChar()
	const bp = getBp()
	return (char and tool:IsDescendantOf(char)) or (bp and tool:IsDescendantOf(bp))
end

NAmanage.isCharTool = NAmanage.isCharTool or function(tool)
	const RawWorkspace = __lt.gs("Workspace")
	if typeof(tool) ~= "Instance" or not tool:IsA("Tool") then
		return false
	end

	if NAmanage.isOwnPackTool(tool) then
		return false
	end

	local inst = tool.Parent
	while inst and inst ~= RawWorkspace do
		if inst:IsA("Model") then
			local okPlr, plr = pcall(function()
				return Services.Players:GetPlayerFromCharacter(inst)
			end)
			if okPlr and plr then
				return true
			end
			if inst:FindFirstChildOfClass("Humanoid") then
				return true
			end
		end
		inst = inst.Parent
	end

	return false
end

NAmanage.isDroppedTool = NAmanage.isDroppedTool or function(tool)
	if typeof(tool) ~= "Instance" or not tool:IsA("Tool") then
		return false
	end
	if not tool:IsDescendantOf(Services.Workspace) then
		return false
	end
	if NAmanage.isOwnPackTool(tool) then
		return false
	end
	if NAmanage.isCharTool(tool) then
		return false
	end
	return true
end

NAmanage.toolPart = NAmanage.toolPart or function(tool)
	if typeof(tool) ~= "Instance" then
		return nil
	end

	const handle = tool:FindFirstChild("Handle")
	if handle and handle:IsA("BasePart") then
		return handle
	end

	for _, d in NAmanage.QueryDescendants(tool, "BasePart") do
		return d
	end

	return nil
end

NAmanage.toolParts=function(tool)
	const parts = {}
	if typeof(tool) ~= "Instance" then
		return parts
	end

	const handle = tool:FindFirstChild("Handle")
	if handle and handle:IsA("BasePart") then
		parts[#parts + 1] = handle
	end

	for _, d in NAmanage.QueryDescendants(tool, "BasePart") do
		if d ~= handle then
			parts[#parts + 1] = d
		end
	end

	return parts
end

NAmanage.toolPrompts = NAmanage.toolPrompts or function(tool)
	const prompts = {}
	if typeof(tool) ~= "Instance" then
		return prompts
	end

	for _, inst in NAmanage.QueryDescendants(tool, "ProximityPrompt") do
		if inst.Parent then
			prompts[#prompts + 1] = inst
		end
	end

	return prompts
end

NAmanage.toolHasPrompt = NAmanage.toolHasPrompt or function(tool)
	return #NAmanage.toolPrompts(tool) > 0
end

NAmanage.fireToolPrompts = NAmanage.fireToolPrompts or function(tool, waitTime, attempts)
	if typeof(tool) ~= "Instance" or typeof(fireproximityprompt) ~= "function" then
		return false, false
	end

	const prompts = NAmanage.toolPrompts(tool)
	if #prompts == 0 then
		return false, false
	end

	local fired = false
	const tries = math.max(1, tonumber(attempts) or 1)
	for attempt = 1, tries do
		for _, inst in prompts do
			if inst and inst.Parent then
				fired = true
				const holdDuration = inst.HoldDuration
				const maxDistance = inst.MaxActivationDistance

				NACaller(function()
					if holdDuration > 0 then
						inst.HoldDuration = 0
					end
					if maxDistance < 32 then
						inst.MaxActivationDistance = 32
					end
				end)

				pcall(fireproximityprompt, inst)

				NACaller(function()
					if inst and inst.Parent then
						if inst.HoldDuration ~= holdDuration then
							inst.HoldDuration = holdDuration
						end
						if inst.MaxActivationDistance ~= maxDistance then
							inst.MaxActivationDistance = maxDistance
						end
					end
				end)
			end
		end

		if NAmanage.isOwnPackTool(tool) then
			break
		end

		const settleBetween = tonumber(waitTime)
		if settleBetween and settleBetween > 0 and attempt < tries then
			Wait(settleBetween)
		end
	end

	const settle = tonumber(waitTime)
	if settle and settle > 0 then
		Wait(settle)
	end

	return fired, NAmanage.isOwnPackTool(tool)
end

NAmanage.fireToolPromptsFromCharacter = NAmanage.fireToolPromptsFromCharacter or function(tool)
	if typeof(tool) ~= "Instance" or typeof(fireproximityprompt) ~= "function" then
		return false, false
	end

	const prompts = NAmanage.toolPrompts(tool)
	if #prompts == 0 then
		return false, false
	end

	const char = getChar()
	const root = char and getRoot(char)
	if not (char and root) then
		return false, false
	end

	const oldCF = NAmanage.UG_clientCFrame(root) or root.CFrame
	local moved = false
	local firedAny = false

	for _, pp in prompts do
		if pp and pp.Parent then
			const part = (NAindex and NAindex.getPromptPart and NAindex.getPromptPart(pp)) or nil
			if part and part.Parent then
				const offset = math.max(3, math.min(6, (pp.MaxActivationDistance or 0) * 0.6))
				const targetPos = part.Position + Vector3.new(0, 0, offset)
				const targetCF = CFrame.new(targetPos, part.Position)
				NAmanage.safePivotModel(char, targetCF)
				moved = true
				Wait(0.2)

				local fired = false
				fired, _ = NAmanage.fireToolPrompts(tool, 0.12, 3)
				firedAny = firedAny or fired
				if NAmanage.isOwnPackTool(tool) then
					break
				end
			end
		end
	end

	if moved and char and char.Parent and root and root.Parent then
		NAmanage.UG_setClientCFrame(root, oldCF)
		NAmanage.safePivotModel(char, oldCF)
	end

	return firedAny, NAmanage.isOwnPackTool(tool)
end

NAmanage.touchEquipTool = NAmanage.touchEquipTool or function(tool, root, hum, settleTime)
	if not (tool and root) then
		return false
	end

	NAmanage.touchTool(tool, root)
	const settle = tonumber(settleTime) or 0.05
	if settle > 0 then
		Wait(settle)
	end

	if NAmanage.isOwnPackTool(tool) then
		return true
	end

	if hum then
		NACaller(function()
			hum:EquipTool(tool)
		end)
		if settle > 0 then
			Wait(settle)
		end
	end

	return NAmanage.isOwnPackTool(tool)
end

NAmanage.addToolCache=function(tool)
	if typeof(tool) == "Instance" and tool:IsA("Tool") then
		NAmanage.toolCache[tool] = true
	end
end

NAmanage.scanToolBranch=function(inst)
	if typeof(inst) ~= "Instance" then
		return
	end

	if inst:IsA("Tool") then
		NAmanage.addToolCache(inst)
		return
	end

	if inst:IsA("Folder") or inst:IsA("Model") then
		for _, d in NAmanage.QueryDescendants(inst, "Tool") do
			NAmanage.addToolCache(d)
		end
	end
end

-- PART 14
NAmanage.dropToolCache=function(tool)
	if typeof(tool) == "Instance" and tool:IsA("Tool") then
		NAmanage.toolCache[tool] = nil
		NAmanage.grabBusy[tool] = nil
		NAmanage.restoreToolCollision(tool)
	end
end

NAmanage.initToolCache=function()
	if NAmanage.toolCacheStarted then
		return
	end

	NAmanage.toolCacheStarted = true
	NAmanage.toolCache = NAmanage.ensureWeakKeyTable(NAmanage.toolCache)
	NAmanage.grabBusy = NAmanage.ensureWeakKeyTable(NAmanage.grabBusy)
	NAmanage.toolGrabCol = NAmanage.ensureWeakKeyTable(NAmanage.toolGrabCol)

	for _, ch in Services.Workspace:GetChildren() do
		NAmanage.scanToolBranch(ch)
	end

	NAlib.connect("grabtools_cache_add", NAmanage.descAdd(Services.Workspace, function(inst)
		NAmanage.scanToolBranch(inst)
		if inst:IsA("Folder") or inst:IsA("Model") then
			Defer(function()
				if inst and inst.Parent then
					NAmanage.scanToolBranch(inst)
				end
			end)
		end
	end, function(inst)
		return inst and (inst:IsA("Tool") or inst:IsA("Folder") or inst:IsA("Model"))
	end))

	NAlib.connect("grabtools_cache_rem", NAmanage.descRem(Services.Workspace, function(inst)
		if inst:IsA("Tool") then
			NAmanage.dropToolCache(inst)
		end
	end, function(inst)
		return inst and inst:IsA("Tool")
	end))

	Spawn(function()
		local scanned = 0
		for _, inst in NAmanage.QueryDescendants(Services.Workspace, "Tool") do
			NAmanage.addToolCache(inst)
			scanned += 1
			if scanned % 2500 == 0 then
				Wait()
			end
		end
		NAmanage.toolCacheReady = true
	end)
end

NAmanage.toolList=function(forceScan)
	NAmanage.initToolCache()

	const list = {}
	const seen = {}
	for tool in NAmanage.toolCache do
		if NAmanage.isDroppedTool(tool) then
			if not seen[tool] then
				seen[tool] = true
				list[#list + 1] = tool
			end
		else
			NAmanage.toolCache[tool] = nil
			NAmanage.grabBusy[tool] = nil
			NAmanage.restoreToolCollision(tool)
		end
	end

	if forceScan ~= true and (#list > 0 or NAmanage.toolCacheReady) then
		return list
	end

	for _, tool in NAmanage.QueryDescendants(Services.Workspace, "Tool") do
		NAmanage.addToolCache(tool)
		if NAmanage.isDroppedTool(tool) and not seen[tool] then
			seen[tool] = true
			list[#list + 1] = tool
		end
	end
	if #list > 0 then
		return list
	end

	for _, ch in Services.Workspace:GetChildren() do
		NAmanage.scanToolBranch(ch)
	end

	for tool in NAmanage.toolCache do
		if NAmanage.isDroppedTool(tool) and not seen[tool] then
			seen[tool] = true
			list[#list + 1] = tool
		end
	end

	return list
end

NAmanage.saveToolCollision=function(tool)
	if not tool or NAmanage.toolGrabCol[tool] then
		return
	end

	const saved = setmetatable({}, { __mode = "k" })
	for _, part in NAmanage.toolParts(tool) do
		local ok, val = pcall(function()
			return part.CanCollide
		end)
		if ok then
			saved[part] = val
			if val ~= false then
				NACaller(function()
					part.CanCollide = false
				end)
			end
		end
	end
	NAmanage.toolGrabCol[tool] = saved
end

NAmanage.restoreToolCollision=function(tool)
	const saved = tool and NAmanage.toolGrabCol[tool]
	if not saved then
		return
	end

	for part, val in saved do
		if part and part.Parent then
			NACaller(function()
				part.CanCollide = val
			end)
		end
	end
	NAmanage.toolGrabCol[tool] = nil
end

NAmanage.touchTool=function(tool, root)
	if not tool or not root then
		return
	end

	for _, part in NAmanage.toolParts(tool) do
		if part and part.Parent and firetouchinterest then
			NACaller(function()
				firetouchinterest(root, part, 0)
				firetouchinterest(part, root, 0)
				firetouchinterest(root, part, 1)
				firetouchinterest(part, root, 1)
			end)
		end
	end
end

NAmanage.pullTool=function(tool, root)
	if not tool or not root then
		return
	end

	const cf = root.CFrame
	local n = 0
	for _, part in NAmanage.toolParts(tool) do
		if part and part.Parent then
			n += 1
			NACaller(function()
				part.AssemblyLinearVelocity = Vector3.zero
				part.AssemblyAngularVelocity = Vector3.zero
				part.CFrame = cf * CFrame.new((n % 3 - 1) * 0.35, 0, -0.7 - (n * 0.03))
			end)
		end
	end
end

NAmanage.grabTool=function(tool, tries)
	if not NAmanage.isDroppedTool(tool) then
		return false
	end
	if NAmanage.grabBusy[tool] then
		return false
	end

	NAmanage.grabBusy[tool] = true
	const wantsPrompt = NAmanage.toolHasPrompt(tool)
	if not wantsPrompt then
		NAmanage.saveToolCollision(tool)
	end

	local ok = false
	tries = tonumber(tries) or 6

	for _ = 1, tries do
		const char = getChar()
		const hum = char and getHum(char)
		const root = char and getRoot(char)

		if not (char and hum and root) then
			break
		end

		if not NAmanage.isDroppedTool(tool) then
			ok = NAmanage.isOwnPackTool(tool)
			break
		end

		if wantsPrompt then
			local fired, picked = NAmanage.fireToolPrompts(tool, 0.12, 2)
			if picked then
				ok = true
				break
			end

			if fired and not picked then
				_, picked = NAmanage.fireToolPromptsFromCharacter(tool)
				if picked then
					ok = true
					break
				end
			end

			if NAmanage.touchEquipTool(tool, root, hum, 0.08) then
				ok = true
				break
			end
		else
			NAmanage.pullTool(tool, root)
			NAmanage.touchTool(tool, root)
		end

		if NAmanage.isOwnPackTool(tool) then
			ok = true
			break
		end

		NACaller(function()
			hum:EquipTool(tool)
		end)

		if NAmanage.isOwnPackTool(tool) then
			ok = true
			break
		end

		Defer(function()
			const c = getChar()
			const r = c and getRoot(c)
			const h = c and getHum(c)
			if tool and r and NAmanage.isDroppedTool(tool) then
				if wantsPrompt then
					local fired, picked = NAmanage.fireToolPrompts(tool, 0.12, 2)
					if not picked then
						if fired then
							NAmanage.fireToolPromptsFromCharacter(tool)
						end
						NAmanage.touchEquipTool(tool, r, h, 0.08)
					end
				else
					NAmanage.pullTool(tool, r)
					NAmanage.touchTool(tool, r)
				end
			end
		end)

		Defer(function()
			const c = getChar()
			const h = c and getHum(c)
			const r = c and getRoot(c)
			if tool and h and r and NAmanage.isDroppedTool(tool) then
				if wantsPrompt then
					local fired, picked = NAmanage.fireToolPrompts(tool, 0.12, 2)
					if not picked then
						if fired then
							NAmanage.fireToolPromptsFromCharacter(tool)
						end
						NAmanage.touchEquipTool(tool, r, h, 0.08)
					end
				else
					NAmanage.pullTool(tool, r)
					NAmanage.touchTool(tool, r)
				end
			end
		end)

		Wait(0.01)
	end

	ok = ok or NAmanage.isOwnPackTool(tool)
	NAmanage.grabBusy[tool] = nil
	NAmanage.restoreToolCollision(tool)

	if ok then
		NAmanage.toolCache[tool] = nil
	end

	return ok
end

NAmanage.parseGrabToolArgs=function(forceQuery, ...)
	const packed = table.pack(...)
	const args = {}
	for index = 1, packed.n do
		const text = tostring(packed[index] or ""):match("^%s*(.-)%s*$") or ""
		if text ~= "" then args[#args + 1] = text end
	end

	local range
	if #args > 0 then
		const firstNumber = tonumber(args[1])
		const lastNumber = tonumber(args[#args])
		if forceQuery ~= true and firstNumber and firstNumber > 0 then
			range = firstNumber
			table.remove(args, 1)
		elseif #args > 1 and lastNumber and lastNumber > 0 then
			range = lastNumber
			table.remove(args, #args)
		elseif #args > 1 and firstNumber and firstNumber > 0 then
			range = firstNumber
			table.remove(args, 1)
		end
	end

	const query = (Concat(args, " "):match("^%s*(.-)%s*$") or "")
	return range, query
end

NAmanage.toolGrabNameMatches=function(tool, query, partial)
	query = tostring(query or "")
	if query == "" then return true end
	const name = Lower(tostring(tool and tool.Name or ""))
	const needle = Lower(query)
	if partial == true then
		return string.find(name, needle, 1, true) ~= nil
	end
	return name == needle
end

NAmanage.grabAllTools=function(range, query, partial, preserveEquipped)
	const char = getChar()
	const hum = char and getHum(char)
	const root = char and getRoot(char)
	if not hum or not root then return 0, 0 end

	range = tonumber(range)
	query = tostring(query or ""):match("^%s*(.-)%s*$") or ""
	const useRange = range and range > 0
	const keepEquipped = preserveEquipped == true
	const equippedTool = keepEquipped and char:FindFirstChildOfClass("Tool") or nil
	const hadEquippedTool = equippedTool ~= nil

	local count = 0
	local matched = 0
	for _, tool in NAmanage.QueryDescendants(Services.Workspace, "Tool") do
		if NAmanage.toolGrabNameMatches(tool, query, partial) then
			if useRange then
				const handle = tool:FindFirstChild("Handle") or tool:FindFirstChildWhichIsA("BasePart")
				if handle and (handle.Position - root.Position).Magnitude <= range then
					matched += 1
					if NACaller(function() hum:EquipTool(tool) end) then count += 1 end
				end
			else
				matched += 1
				if NACaller(function() hum:EquipTool(tool) end) then count += 1 end
			end
		end
	end

	if keepEquipped then
		const currentChar = getChar()
		const currentHum = currentChar and getHum(currentChar)
		const currentBackpack = getBp()
		if currentHum then
			if equippedTool and equippedTool.Parent and (equippedTool.Parent == currentChar or equippedTool.Parent == currentBackpack) then
				if equippedTool.Parent ~= currentChar then
					NACaller(function() currentHum:EquipTool(equippedTool) end)
				end
			elseif not hadEquippedTool then
				NACaller(function() currentHum:UnequipTools() end)
			end
		end
	end

	return count, matched
end

NAmanage.notifyGrabToolsResult=function(count, matched, range, query, partial)
	query = tostring(query or "")
	if count > 0 then
		local text = ("Grabbed %d tool%s"):format(count, count == 1 and "" or "s")
		if query ~= "" then
			text ..= partial == true and (" matching '%s'"):format(query) or (" named '%s'"):format(query)
		end
		if range and range > 0 then text ..= (" within %d studs"):format(range) end
		DebugNotif(text, 2)
	elseif query ~= "" and matched == 0 then
		DebugNotif((partial == true and "No tools matched '" or "No tool named '")..query.."'", 2)
	else
		DebugNotif("No tools to grab", 2)
	end
end

cmd.register({
	name = "grabtools",
	aliases = { "gtools", "gtls" },
	description = "Grabs dropped tools, optionally filtering by exact tool name",
	usage = "grabtools [tool name] [range]",
	callback = function(...)
		const range, query = NAmanage.parseGrabToolArgs(false, ...)
		const count, matched = NAmanage.grabAllTools(range, query, false)
		NAmanage.notifyGrabToolsResult(count, matched, range, query, false)
	end,
})

cmd.register({
	name = "grabtoolsfind",
	aliases = { "gtoolsfind", "gtlsfind", "grabfind" },
	description = "Grabs dropped tools whose names contain the given text",
	usage = "grabtoolsfind <tool name> [range]",
	callback = function(...)
		const range, query = NAmanage.parseGrabToolArgs(true, ...)
		if query == "" then
			DebugNotif("Usage: grabtoolsfind <tool name> [range]", 3)
			return
		end
		const count, matched = NAmanage.grabAllTools(range, query, true)
		NAmanage.notifyGrabToolsResult(count, matched, range, query, true)
	end,
})

cmd.register({
	name = "loopgrabtools",
	aliases = { "loopgrab", "lgtools", "lgtls", "lgrab", "lg" },
	description = "Loop grabs dropped tools without changing your equipped tool",
	usage = "loopgrabtools [range]",
	callback = function(...)
		if loopgrab then
			DebugNotif("Loop grab already running", 2)
			return
		end
		const firstArg = ...
		const range = tonumber(firstArg)

		loopgrab = true
		DebugNotif("Started loop grabbing tools", 2)
		SpawnCall(function()
			while loopgrab do
				NAmanage.grabAllTools(range, nil, false, true)
				Wait(1)
			end
			DebugNotif("Stopped loop grabbing tools", 2)
		end)
	end,
})

cmd.register({
	name = "unloopgrabtools",
	aliases = { "unloopgrab", "unlgtools", "unlgtls", "unlgrab", "unlg" },
	description = "Stops the loop grab command",
	callback = function()
		if not loopgrab then
			DebugNotif("Loop grab is not running", 2)
			return
		end
		loopgrab = false
	end,
})

