cmd.register({
	name = "freegamepass",
	aliases = { "freegp" },
	description = "Pretends you own every gamepass and fires product purchase signals",
	usage = "freegamepass (freegp)",
	callback = function()
		const market = SafeGetService("MarketplaceService")
		if not market then
			DoNotif("MarketplaceService is unavailable in this session", 3, "Free Gamepasses")
			return
		end

		if hookfunction and not NAStuff._freeGamepassHooked then
			const ok = pcall(function()
				return hookfunction(market.UserOwnsGamePassAsync, newcclosure(function(...)
					return true
				end))
			end)
			if ok then
				NAStuff._freeGamepassHooked = true
			end
		end

		local products = {}
		local okProducts, errProducts = pcall(function()
			products = __lt.cm("MarketplaceService", "GetDeveloperProductsAsync"):GetCurrentPage()
		end)

		const gamepasses = (function()
			const result = {}

			pcall(function()
				const decoded = NAmanage.FetchRobloxApiJSON(Format("https://apis.roblox.com/game-passes/v1/universes/%s/game-passes?passView=Full&pageSize=100", tostring(GameId)), { Timeout = 5 })
				if type(decoded) ~= "table" then return end

				for _, gamepass in next, decoded.gamePasses do
					Insert(result, gamepass.id)
				end
			end)

			return result
		end)()

		const function fireProductPurchaseSignals(id)
			local fired = 0
			if pcall(function()
				__lt.cm("MarketplaceService", "SignalPromptProductPurchaseFinished", LocalPlayer.UserId, id, true)
			end) then
				fired += 1
			end
			if pcall(function()
				__lt.cm("MarketplaceService", "SignalPromptBulkPurchaseFinished", LocalPlayer.UserId, id, true)
			end) then
				fired += 1
			end
			if pcall(function()
				__lt.cm("MarketplaceService", "SignalPromptPurchaseFinished", LocalPlayer.UserId, id, true)
			end) then
				fired += 1
			end
			return fired
		end

		const function fireGamePassPurchaseSignals(id)
			local fired = 0
			if pcall(function()
				__lt.cm("MarketplaceService", "SignalPromptGamePassPurchaseFinished", LocalPlayer, id, true)
			end) then
				fired += 1
			end
			if pcall(function()
				__lt.cm("MarketplaceService", "SignalPromptBulkPurchaseFinished", LocalPlayer.UserId, id, true)
			end) then
				fired += 1
			end
			if pcall(function()
				__lt.cm("MarketplaceService", "SignalPromptPurchaseFinished", LocalPlayer.UserId, id, true)
			end) then
				fired += 1
			end
			return fired
		end

		local totalSignals = 0

		for _, product in next, (products or {}) do
			for key, id in next, product do
				if (key == "ProductId") or (key == "DeveloperProductId") then
					totalSignals += fireProductPurchaseSignals(id)
				end
			end
		end

		for _, gamepass in next, (gamepasses or {}) do
			totalSignals += fireGamePassPurchaseSignals(gamepass)
		end

		if okProducts then
			DoNotif(Format("Hooked gamepass ownership and fired %d purchase signals", totalSignals), 8, "Free Gamepasses")
		else
			DoNotif("Failed to spoof gamepasses: "..tostring(errProducts), 8, "Free Gamepasses")
		end
	end,
})

NA_DEVPROD_GUI=nil

-- PART 15
do
	const cfgs = {
		product = {
			title = "Developer Products";
			page = "Products";
			tab = "Products";
			method = "SignalPromptProductPurchaseFinished";
			event = "PromptProductPurchaseFinished";
			request = "PromptProductPurchaseRequested";
			info = Enum.InfoType.Product;
		};
		pass = {
			title = "Game Passes";
			page = "GamePasses";
			tab = "Game Passes";
			method = "SignalPromptGamePassPurchaseFinished";
			event = "PromptGamePassPurchaseFinished";
			request = "PromptGamePassPurchaseRequested";
			info = Enum.InfoType.GamePass;
		};
	}
	const live = {}
	const kinds = { "product", "pass" }
	local liveWin
	local bound
	local tab = "product"
	const colors = {
		panel = Color3.fromRGB(31, 32, 42);
		text = Color3.fromRGB(245, 246, 250);
		muted = Color3.fromRGB(160, 167, 184);
		accent = Color3.fromRGB(115, 72, 195);
		danger = Color3.fromRGB(135, 46, 62);
	}
	const modes = { "Auto", "Native", "Local" }
	const ctrl = {}
	ctrl.__index = ctrl
	const win = {}
	win.__index = win
	const sizing = {
		key = "Purchases"; baseWidth = 820; baseHeight = 640;
		minWidth = 460; minHeight = 360; mobileMinWidth = 280; mobileMinHeight = 280;
		center = true;
	}
	const function saveSize(frame)
		if not frame or NAmanage.GetAttr(frame, "NAMenuMaximized") == true then return end
		NAmanage.ExecutorWindowSizing.Save(frame, "NAPurchasesSavedSizeX", "NAPurchasesSavedSizeY")
	end

	const function idNum(value)
		if type(value) == "string" then
			value = value:match("^%s*(%d+)%s*$")
		end
		const id = tonumber(value)
		if not id or id ~= id or id < 1 or id > 9007199254740991 or id % 1 ~= 0 then
			return nil
		end
		return id
	end

	const function short(value, limit)
		const text = tostring(value or ""):gsub("%c", " ")
		return #text > (limit or 140) and text:sub(1, (limit or 140) - 3).."..." or text
	end

	function ctrl:alive()
		return self.on and self.hub.on and self.gui and self.gui.Parent ~= nil
	end

	function ctrl:bind(signal, fn, row)
		const conn = signal:Connect(fn)
		self.cons[conn] = true
		if row then row.cons[conn] = true end
		return conn
	end

	function ctrl:note(text)
		if self:alive() then self.ui.status.Text = short(text, 200) end
	end

	function ctrl:delay()
		local secs = tonumber(self.ui.delay.Text)
		if not secs or secs ~= secs or math.abs(secs) == math.huge then secs = 0.25 end
		return math.clamp(secs, 0.05, 60)
	end

	function ctrl:draw(row)
		if not self:alive() or self.rows[row.id] ~= row then return end
		const info = row.info
		row.name.Text = info.name or ("ID "..tostring(row.id))
		const price = info.sale == false and "Offsale" or (info.price ~= nil and (tostring(info.price).." R$") or "Price N/A")
		row.meta.Text = "ID "..tostring(row.id).."  |  "..price.."  |  "..(row.origin or "Catalog")
		row.result.Text = short(row.last or "Ready", 120)..(row.sends > 0 and ("  |  "..row.sends.." sent") or "")
		row.result.TextColor3 = row.failed and Color3.fromRGB(255, 142, 151) or colors.muted
		row.auto.Text = self.auto[row.id] and "Auto ON" or "Auto"
		row.auto.BackgroundColor3 = self.auto[row.id] and colors.danger or colors.panel
		const icon = idNum(info.icon)
		const image = self.kind == "pass" and ("rbxthumb://type=GamePass&id="..tostring(row.id).."&w=150&h=150") or (icon and ("rbxthumb://type=Asset&id="..tostring(icon).."&w=150&h=150") or "")
		row.icon.Image = image
		row.icon.Visible = image ~= ""
		const left = image ~= "" and 70 or 12
		row.name.Position = UDim2.fromOffset(left, 10)
		row.name.Size = UDim2.new(1, -left - 12, 0, 24)
		row.meta.Position = UDim2.fromOffset(left, 36)
		row.meta.Size = UDim2.new(1, -left - 12, 0, 20)
	end

	function ctrl:filter()
		if not self:alive() then return end
		const query = string.lower(self.ui.search.Text)
		local count, active = 0, 0
		for _, id in self.ids do
			const row = self.rows[id]
			const visible = query == "" or string.find(string.lower(row.info.name or ""), query, 1, true) ~= nil or string.find(tostring(id), query, 1, true) ~= nil
			row.frame.Visible = visible
			if visible then count += 1 end
			if self.auto[id] then active += 1 end
		end
		self.ui.count.Text = string.format("%d / %d items  |  %d auto", count, #self.ids, active)
		self.ui.empty.Visible = count == 0
		self.ui.empty.Text = #self.ids == 0 and "No items yet. Add an ID or open a purchase prompt in the game." or "No matching items."
		self.hub:tabs()
	end

	function ctrl:stop(quiet)
		self.worker = nil
		self.batch = false
		self.head = 1
		table.clear(self.todo)
		table.clear(self.pending)
		table.clear(self.auto)
		for _, row in self.rows do self:draw(row) end
		self:filter()
		if not quiet then self:note("Stopped all auto runs and queued signals.") end
	end

	function ctrl:close()
		if not self.on then return end
		self.on = false
		self.rev += 1
		self:stop(true)
		for conn in self.cons do pcall(conn.Disconnect, conn) end
		table.clear(self.cons)
		for _, row in self.rows do pcall(row.frame.Destroy, row.frame) end
		table.clear(self.rows)
		table.clear(self.ids)
		table.clear(self.meta)
		table.clear(self.sent)
		self.lookup = nil
		if live[self.kind] == self then live[self.kind] = nil end
	end

	function ctrl:fire(value)
		const id = idNum(value)
		if not id then return false, "Invalid item ID" end
		if not self:alive() then return false, "Window closed" end
		const target = self.kind == "product" and self.player.UserId or self.player
		const mode = modes[self.mode]
		self.sent[id] = os.clock() + 1
		local err = self.nativeErr or "Native signal unavailable"
		if mode ~= "Local" and (mode == "Native" or self.native ~= false) then
			const ok, result = pcall(function()
				__lt.cm("MarketplaceService", self.cfg.method, target, id, true)
			end)
			if ok then
				self.native = true
				return true, "Sent using native signal"
			end
			err = tostring(result)
			self.nativeErr = err
			self.native = false
		end
		if mode ~= "Native" and type(firesignal) == "function" then
			const ok, result = pcall(function()
				firesignal(Services.MarketplaceService[self.cfg.event], target, id, true)
			end)
			if ok then return true, "Sent to local listeners" end
			err = tostring(result)
		elseif mode == "Local" then
			err = "This executor does not support firesignal"
		end
		self.sent[id] = nil
		return false, short(err)
	end

	function ctrl:nextId()
		const id = self.todo[self.head]
		if id then
			self.head += 1
			self.pending[id] = nil
			return id
		end
		table.clear(self.todo)
		self.head = 1
		self.batch = false
		for _ = 1, #self.ids do
			self.turn = self.turn % #self.ids + 1
			const nextId = self.ids[self.turn]
			if self.auto[nextId] then return nextId end
		end
		return nil
	end

	function ctrl:kick()
		if self.worker or not self:alive() then return end
		const token = {}
		self.worker = token
		SpawnCall(function()
			while self:alive() and self.worker == token do
				const id = self:nextId()
				if not id then break end
				const ok, msg = self:fire(id)
				if not self:alive() or self.worker ~= token then break end
				const row = self.rows[id]
				if row then
					row.failed = not ok
					row.last = msg
					if ok then row.sends += 1 else self.auto[id] = nil end
					self:draw(row)
				end
				self:note((ok and "ID " or "Failed ID ")..tostring(id)..": "..msg)
				if not ok then self:filter() end
				const untilAt = os.clock() + self:delay()
				repeat
					Wait(math.max(0.001, math.min(0.1, untilAt - os.clock())))
				until not self:alive() or self.worker ~= token or os.clock() >= untilAt
			end
			if self.worker == token then self.worker = nil end
		end)
	end

	function ctrl:queue(id)
		if not self:alive() or not self.rows[id] or self.pending[id] then return end
		self.pending[id] = true
		self.todo[#self.todo + 1] = id
	end

	function ctrl:runAll()
		if self.batch then self:note("A batch is running. Stop All cancels it.") return end
		local count = 0
		for _, id in self.ids do
			if self.rows[id].frame.Visible then self:queue(id) count += 1 end
		end
		if count == 0 then self:note("No matching items to run.") return end
		self.batch = true
		self:note("Queued "..tostring(count).." visible item(s).")
		self:kick()
	end

	const function child(parent, name)
		const obj = parent and parent:FindFirstChild(name)
		assert(obj, "Purchase UI is missing "..name)
		return obj
	end

	function ctrl:action(btn, fn, row)
		self:bind(btn.Activated, function()
			if self:alive() then fn() end
		end, row)
	end

	function ctrl:row(info, origin)
		const id = idNum(info.id)
		if not id or not self:alive() then return nil end
		local row = self.rows[id]
		if row then
			for key, value in info do row.info[key] = value end
			if origin ~= "Catalog" then row.keep = true row.origin = origin end
			self:draw(row)
			return row
		end
		row = { id = id; info = info; origin = origin; keep = origin ~= "Catalog"; cons = {}; sends = 0; }
		self.rows[id] = row
		self.ids[#self.ids + 1] = id
		row.frame = self.ui.template:Clone()
		row.frame.Name = "Item_"..tostring(id)
		row.frame.LayoutOrder = #self.ids
		row.frame.Visible = true
		row.frame.Parent = self.ui.list
		row.icon = child(row.frame, "Icon")
		row.name = child(row.frame, "ItemName")
		row.meta = child(row.frame, "Meta")
		row.result = child(row.frame, "Result")
		row.run = child(row.frame, "Run")
		row.auto = child(row.frame, "Auto")
		row.copy = child(row.frame, "Copy")
		if NAgui.RegisterStrokesFrom then NAgui.RegisterStrokesFrom(row.frame) end
		self:action(row.run, function()
			self:queue(id)
			self:kick()
		end, row)
		self:action(row.auto, function()
			self.auto[id] = not self.auto[id] or nil
			self:draw(row)
			self:filter()
			self:kick()
		end, row)
		self:action(row.copy, function()
			if type(setclipboard) ~= "function" then self:note("Clipboard is unavailable.") return end
			const ok, err = pcall(setclipboard, tostring(id))
			self:note(ok and ("Copied ID "..tostring(id)..".") or ("Copy failed: "..short(err)))
		end, row)
		self:draw(row)
		self.ui.empty.Visible = false
		if not self.fetching then self:filter() end
		return row
	end

	function ctrl:drop(id)
		const row = self.rows[id]
		if not row then return end
		for conn in row.cons do
			pcall(conn.Disconnect, conn)
			self.cons[conn] = nil
		end
		self.rows[id] = nil
		self.auto[id] = nil
		self.sent[id] = nil
		row.frame:Destroy()
		const index = table.find(self.ids, id)
		if index then table.remove(self.ids, index) end
	end

	function ctrl:info(id)
		const row = self.rows[id]
		if not row or row.lookup then return end
		row.lookup = true
		self.meta[#self.meta + 1] = row
		if self.lookup then return end
		const token = {}
		self.lookup = token
		SpawnCall(function()
			while self:alive() and self.lookup == token and #self.meta > 0 do
				const item = table.remove(self.meta, 1)
				local ok, data = pcall(function()
					return __lt.cm("MarketplaceService", "GetProductInfoAsync", item.id, self.cfg.info)
				end)
				if not ok and self:alive() and self.lookup == token then
					ok, data = pcall(function()
						return __lt.cm("MarketplaceService", "GetProductInfo", item.id, self.cfg.info)
					end)
				end
				if not self:alive() or self.lookup ~= token then break end
				if self.rows[item.id] == item then
					item.lookup = nil
					if ok and type(data) == "table" then
						self:row({ id = item.id; name = data.Name; price = data.PriceInRobux; sale = data.IsForSale; icon = data.IconImageAssetId; }, item.origin)
						self:filter()
					else
						self:note("Info lookup failed for ID "..item.id..": "..short(data))
					end
				end
				Wait(0.05)
			end
			if self.lookup == token then self.lookup = nil end
		end)
	end

	function ctrl:add(value)
		const id = idNum(value)
		if not id then self:note("Enter a positive whole-number item ID.") return end
		const row = self:row({ id = id }, "Manual")
		if not row then return end
		self.ui.search.Text = ""
		self:info(id)
		self:note("Added ID "..tostring(id)..".")
	end

	function ctrl:capture(who, value, result, opened)
		if not self:alive() then return end
		const mine = who == self.player or (type(who) == "number" and who == self.player.UserId)
		if not mine then return end
		const id = idNum(value)
		if not id or (not opened and (self.sent[id] or 0) > os.clock()) then return end
		local row = self.rows[id]
		if not row then
			if self.extra >= 300 then self:note("Captured ID limit reached. Reopen this window to clear it.") return end
			self.extra += 1
		end
		row = self:row({ id = id }, "Captured")
		if not row then return end
		row.last = (opened and "Prompt opened" or (result and "Prompt closed: accepted" or "Prompt closed: cancelled")).." at "..os.date("%H:%M:%S")
		row.failed = false
		self:draw(row)
		self:info(id)
	end

	function ctrl:listen()
		for _, data in { { self.cfg.event, false }, { self.cfg.request, true } } do
			const opened = data[2]
			pcall(function()
				self:bind(Services.MarketplaceService[data[1]], function(who, id, result)
					self:capture(who, id, result, opened)
				end)
			end)
		end
	end

	function ctrl:fetch(rev)
		const items, seen = {}, {}
		if self.kind == "product" then
			const pages = __lt.cm("MarketplaceService", "GetDeveloperProductsAsync")
			while self:alive() and self.rev == rev do
				const ok, page = pcall(pages.GetCurrentPage, pages)
				if not ok or type(page) ~= "table" then return items, "Could not read a product page: "..short(page) end
				local added = 0
				for _, data in page do
					const id = idNum(data.ProductId or data.DeveloperProductId)
					if id and not seen[id] then
						seen[id] = true
						added += 1
						items[#items + 1] = { id = id; name = data.Name; price = data.PriceInRobux; sale = data.IsForSale; icon = data.IconImageAssetId; }
					end
				end
				if pages.IsFinished then return items end
				if added == 0 then return items, "Product pagination returned a repeated or empty page" end
				const nextOk, err = pcall(pages.AdvanceToNextPageAsync, pages)
				if not nextOk then return items, "Product pagination failed: "..short(err) end
				Wait()
			end
		else
			const base = "https://apis.roblox.com/game-passes/v1/universes/"..tostring(GameId).."/game-passes?passView=Full&pageSize=100"
			const tokens = {}
			local cursor = nil
			repeat
				if not self:alive() or self.rev ~= rev then break end
				const url = base..(cursor and ("&pageToken="..__lt.cm("HttpService", "UrlEncode", cursor)) or "")
				const ok, data = pcall(NAmanage.FetchRobloxApiJSON, url, { Timeout = 5 })
				const page = ok and type(data) == "table" and (data.gamePasses or data.data)
				if type(page) ~= "table" then return items, "Could not fetch a game pass page: "..short(data) end
				for _, pass in page do
					const id = idNum(pass.id)
					if id and not seen[id] then
						seen[id] = true
						items[#items + 1] = { id = id; name = pass.displayName or pass.name; price = pass.price or pass.displayPrice; sale = pass.isForSale; icon = pass.iconImageAssetId or pass.iconImageAssetID or pass.imageAssetId; }
					end
				end
				cursor = data.nextPageToken or data.nextPageCursor
				if cursor == "" then cursor = nil end
				if cursor and (type(cursor) ~= "string" or tokens[cursor]) then return items, "Game pass pagination returned a repeated or invalid token" end
				if cursor then tokens[cursor] = true Wait() end
			until not cursor
		end
		return items
	end

	function ctrl:refresh()
		if self.fetching or not self:alive() then return end
		self.loaded = true
		self:stop(true)
		self.native = nil
		self.nativeErr = nil
		self.fetching = true
		self.rev += 1
		const rev = self.rev
		self:note("Loading "..string.lower(self.cfg.title).."...")
		SpawnCall(function()
			local ok, items, err = pcall(self.fetch, self, rev)
			if not self:alive() or self.rev ~= rev then return end
			if not ok then err = tostring(items) items = {} end
			const seen = {}
			for index, info in items do
				if not self:alive() or self.rev ~= rev then return end
				seen[info.id] = true
				self:row(info, "Catalog")
				if index % 8 == 0 then Wait() end
			end
			if not err then
				const stale = {}
				for id, row in self.rows do
					if not seen[id] and not row.keep then stale[#stale + 1] = id end
				end
				for _, id in stale do self:drop(id) end
			end
			if not self:alive() or self.rev ~= rev then return end
			self.fetching = false
			self:filter()
			self:note(err and ("Loaded "..#items.." items; "..short(err)) or ("Loaded "..#items.." items. Listening for purchase prompts."))
		end)
	end

	function ctrl:create(page)
		const content = child(page, "Content")
		const controls = child(content, "Controls")
		const body = child(content, "Body")
		const ui = self.ui
		ui.page = page
		page.CanvasPosition = Vector2.new(0, 0)
		ui.search = child(controls, "Search")
		ui.id = child(controls, "ID")
		ui.delay = child(controls, "Delay")
		ui.method = child(controls, "Method")
		ui.list = child(body, "List")
		ui.empty = child(body, "Empty")
		ui.status = child(content, "Status")
		ui.count = child(content, "Count")
		ui.template = child(child(content, "Templates"), "Row")
		ui.search.Text = ""
		ui.id.Text = ""
		ui.delay.Text = "0.25"
		ui.method.Text = "Auto method"
		ui.list.CanvasPosition = Vector2.new(0, 0)
		ui.count.Text = "0 / 0 items  |  0 auto"
		ui.empty.Visible = true
		self:note("Fake purchase signals; no Robux are spent.")
		self:action(child(controls, "Refresh"), function() self:refresh() end)
		self:action(child(controls, "RunAll"), function() self:runAll() end)
		self:action(child(controls, "StopAll"), function() self.hub:stop() end)
		self:action(child(controls, "Add"), function() self:add(ui.id.Text) end)
		self:action(ui.method, function()
			self.mode = self.mode % #modes + 1
			self.native = nil
			self.nativeErr = nil
			ui.method.Text = modes[self.mode].." method"
			self:note(self.mode == 1 and "Auto uses the native signal, with a local fallback." or (self.mode == 2 and "Native sends the matching marketplace completion signal." or "Local fires only local completion listeners."))
		end)
		self:bind(ui.search:GetPropertyChangedSignal("Text"), function() self:filter() end)
		self:bind(ui.delay.FocusLost, function()
			const text = tostring(self:delay())
			if ui.delay.Text ~= text then ui.delay.Text = text end
		end)
		self:bind(ui.id.FocusLost, function(enter) if enter then self:add(ui.id.Text) end end)
		self:listen()
	end

	function win:bind(signal, fn)
		const conn = signal:Connect(fn)
		self.cons[conn] = true
		return conn
	end

	function win:tabs()
		if not self.on then return end
		for _, kind in kinds do
			const page = live[kind]
			const btn = self.buttons[kind]
			if page and btn then
				local count = 0
				for _ in page.auto do count += 1 end
				btn.Text = page.cfg.tab..(count > 0 and (" ("..count.." auto)") or "")
				btn.BackgroundColor3 = self.kind == kind and colors.accent or colors.panel
			end
		end
	end

	function win:select(kind)
		if not self.on then return end
		self.kind = kind
		tab = kind
		for _, key in kinds do live[key].ui.page.Visible = key == kind end
		self:tabs()
		const page = live[kind]
		if not page.loaded then page:refresh() end
	end

	function win:stop()
		for _, kind in kinds do
			if live[kind] then live[kind]:stop() end
		end
	end

	function win:close()
		if not self.on then return end
		self.on = false
		saveSize(self.gui)
		for _, kind in kinds do
			if live[kind] then live[kind]:close() end
		end
		for conn in self.cons do pcall(conn.Disconnect, conn) end
		table.clear(self.cons)
		if NAgui.pruneRegisteredStrokes then NAgui.pruneRegisteredStrokes(true) end
		NAlib.disconnect("MarketPurchasesUI")
		if liveWin == self then liveWin = nil end
		if self.gui and self.gui.Visible then pcall(function() self.gui.Visible = false end) end
	end

	NAmanage.PurchaseWindow_Init = function()
		const frame = NAUIMANAGER and NAUIMANAGER.PurchaseFrame
		if not (frame and frame.Parent) then return false end
		const mini = NAmanage.GetAttr(frame, "NAMenuMinimized") == true
		if bound ~= frame or mini then
			const wide, tall = NAmanage.ExecutorWindowSizing.GetSaved(frame, "NAMenuStoredSizeX", "NAMenuStoredSizeY")
			NAgui.menu(frame)
			if mini and wide and tall then
				const size = UDim2.fromOffset(wide, tall)
				if frame.Size ~= size then frame.Size = size end
				saveSize(frame)
			end
			if NAgui.RegisterStrokesFrom then NAgui.RegisterStrokesFrom(frame) end
			bound = frame
		end
		NAStuff.LazyMenuBound_PurchaseFrame = frame
		const metrics = NAmanage.ExecutorWindowSizing.GetSize(sizing.baseWidth, sizing.baseHeight, sizing)
		NAgui.resizeable(frame, Vector2.new(metrics.minWidth, metrics.minHeight), Vector2.new(1400, 1000))
		return true
	end

	function win:create()
		assert(NAmanage.PurchaseWindow_Init(), "Purchase window is unavailable; update NAUI/NAUITEST")
		self.gui = NAUIMANAGER.PurchaseFrame
		const body = child(self.gui, "Container")
		const tabs = child(body, "Tabs")
		const pages = child(body, "Pages")
		for _, kind in kinds do
			const cfg = cfgs[kind]
			const page = setmetatable({
				kind = kind; cfg = cfg; player = Services.Players.LocalPlayer; hub = self; gui = self.gui;
				on = true; rev = 0; extra = 0; mode = 1; turn = 0; head = 1;
				ui = {}; rows = {}; ids = {}; cons = {}; auto = {}; sent = {};
				todo = {}; pending = {}; meta = {};
			}, ctrl)
			live[kind] = page
			page:create(child(pages, cfg.page))
			self.buttons[kind] = child(tabs, cfg.page)
			self:bind(self.buttons[kind].Activated, function() self:select(kind) end)
		end
		self:bind(self.gui:GetPropertyChangedSignal("Size"), function() saveSize(self.gui) end)
		self:bind(self.gui:GetPropertyChangedSignal("Visible"), function()
			if not self.gui.Visible then self:close() end
		end)
		self:bind(self.gui.Destroying, function() self:close() end)
		self:bind(self.gui.AncestryChanged, function()
			if not self.gui.Parent then self:close() end
		end)
		NAlib.connect("MarketPurchasesUI", { Connected = true; Disconnect = function() self:close() end; })
	end

	const function open(kind, value)
		kind = cfgs[kind] and kind or tab
		const frame = NAUIMANAGER and NAUIMANAGER.PurchaseFrame
		if not (frame and frame.Parent) then
			DoNotif("Purchase window is unavailable. Update NAUI/NAUITEST.", 6, "Purchases")
			return false
		end
		if liveWin and not liveWin.gui.Parent then liveWin:close() end
		if not liveWin then
			NAlib.disconnect("MarketPurchasesUI")
			liveWin = setmetatable({ on = true; cons = {}; buttons = {}; }, win)
			const ok, err = pcall(liveWin.create, liveWin)
			if not ok then
				liveWin:close()
				DoNotif("Could not open purchases: "..short(err), 6, "Purchases")
				return false
			end
			if NAmanage.GetAttr(liveWin.gui, "NAPurchasesDefaultSized") ~= true then
				NAmanage.ExecutorWindowSizing.Apply(liveWin.gui, sizing)
			end
		end
		if NAmanage.WindowAppearance and NAmanage.WindowAppearance.applyFrame then
			pcall(NAmanage.WindowAppearance.applyFrame, liveWin.gui)
		end
		NAgui.setWindowVisible(liveWin.gui, true)
		liveWin:select(kind)
		if value and value ~= "" then live[kind]:add(value) end
		if NAmanage.OnUIWindowShown then pcall(NAmanage.OnUIWindowShown, liveWin.gui) end
		if NAmanage.centerFrame then
			Defer(function()
				if frame.Parent and frame.Visible then pcall(NAmanage.centerFrame, frame) end
			end)
		end
		return true
	end

	NAmanage.PurchaseWindow_Open = open
	NAmanage.PurchaseWindow_Toggle = function()
		const frame = NAUIMANAGER and NAUIMANAGER.PurchaseFrame
		if NAgui.isWindowOpen(frame) then
			NAgui.closeWindow(frame)
			return true
		end
		return open()
	end

	NAmanage.RegisterUnloadCleanup("market_windows", function()
		if liveWin then liveWin:close() end
	end)

