NAmanage.SetWeldReplicationRoot = function(Root, TargetPart)
	local setter = (opt and opt.hiddenprop) or sethiddenproperty or set_hidden_property or set_hidden_prop
	if type(setter) ~= "function" then return end

	pcall(setter, Root, "PhysicsRepRootPart", TargetPart)
	if not InstanceHandle then return end
	local ok, reference = pcall(function()
		return InstanceHandle.new(TargetPart)
	end)
	if ok then
		pcall(setter, Root, "PhysicsRepRootRef", reference)
	end
end

NAmanage.AcquireWeldReplicationRoot = function(Root)
	local Character = Root.Parent
	if Character then
		for _, accessory in Character:QueryDescendants("Accessory") do
			local constraint = accessory:FindFirstChildWhichIsA("RigidConstraint", true)
			if constraint and constraint.Enabled then
				constraint.Enabled = false
				task.delay(0.05, function()
					if constraint.Parent then
						constraint.Enabled = true
					end
				end)
			end
		end
	end

	NAStuff.weldReplicationState = NAStuff.weldReplicationState or setmetatable({}, { __mode = "k" })
	local states = NAStuff.weldReplicationState
	local state = states[Root]
	if not state then
		state = { Users = 0 }
		local getter = gethiddenproperty or get_hidden_property or gethiddenprop or get_hidden_prop
		if type(getter) == "function" then
			local ok, value = pcall(getter, Root, "PhysicsRepRootPart")
			if ok then
				state.Part = value
				state.HasPart = true
			end
			ok, value = pcall(getter, Root, "PhysicsRepRootRef")
			if ok then
				state.Reference = value
				state.HasReference = true
			end
		end
		states[Root] = state
	end
	state.Users += 1
	return state
end

NAmanage.ReleaseWeldReplicationRoot = function(Root, state)
	if not state or state.Users <= 0 then return end
	state.Users -= 1
	if state.Users > 0 then return end
	local states = NAStuff.weldReplicationState
	if not states or states[Root] ~= state then return end
	states[Root] = nil

	local setter = (opt and opt.hiddenprop) or sethiddenproperty or set_hidden_property or set_hidden_prop
	if type(setter) ~= "function" then return end
	if state.HasPart then
		pcall(setter, Root, "PhysicsRepRootPart", state.Part)
	else
		pcall(setter, Root, "PhysicsRepRootPart", Root)
	end
	if state.HasReference then
		pcall(setter, Root, "PhysicsRepRootRef", state.Reference)
	elseif InstanceHandle then
		local ok, reference = pcall(function()
			return InstanceHandle.new(Root)
		end)
		if ok then
			pcall(setter, Root, "PhysicsRepRootRef", reference)
		end
	end
end

NAmanage.WeldToPlayerPart = NAmanage.WeldToPlayerPart or function(TargetPart, Offset, Speaker, AnimationId)
	local Character = Speaker == LocalPlayer and getChar() or getPlrChar(Speaker)
	if not Character then return nil end

	local Root = getRoot(Character)
	local Humanoid = getHum(Character)
	if not Root or not Humanoid then return nil end

	local AnimTrack = nil
	if AnimationId then
		local Animator = Character:FindFirstChildWhichIsA("Animator", true)
		if Animator then
			local Animation = InstanceNew("Animation")
			Animation.AnimationId = "rbxassetid://" .. tostring(AnimationId)
			AnimTrack = Animator:LoadAnimation(Animation)
			AnimTrack:Play()
		end
	end

	local Weld = { Connected = true }
	local Connection = nil
	local Destroyed = false
	local replicationState = NAmanage.AcquireWeldReplicationRoot(Root)
	NAStuff.weldState = NAStuff.weldState or setmetatable({}, { __mode = "k" })
	const states = NAStuff.weldState
	local state = states[Root]
	if not state then
		state = {
			Users = 0;
			Parts = {};
		}
		states[Root] = state
	end
	state.Users += 1

	for _, v in Character:GetDescendants() do
		if v:IsA("BasePart") then
			if not state.Parts[v] then
				state.Parts[v] = {
					CanCollide = v.CanCollide;
					Massless = v.Massless;
				}
			end
			v.CanCollide = false
			v.Massless = true
		end
	end

	Connection = Services.RunService.Heartbeat:Connect(function()
		if Destroyed then return end
		if not Character.Parent or not TargetPart.Parent then
			Weld:Destroy()
			return
		end

		Root.CFrame = TargetPart.CFrame * Offset
		Root.AssemblyLinearVelocity = Vector3.zero
		Root.AssemblyAngularVelocity = Vector3.zero

		NAmanage.SetWeldReplicationRoot(Root, TargetPart)
	end)

	function Weld:Destroy()
		if Destroyed then return end
		Destroyed = true
		Weld.Connected = false

		if Connection then
			Connection:Disconnect()
			Connection = nil
		end
		if AnimTrack then
			AnimTrack:Stop()
			AnimTrack:Destroy()
			AnimTrack = nil
		end

		NAmanage.ReleaseWeldReplicationRoot(Root, replicationState)
		state.Users -= 1
		if state.Users <= 0 then
			if states[Root] == state then
				states[Root] = nil
			end
			for part, props in state.Parts do
				if part and part.Parent then
					pcall(function()
						part.CanCollide = props.CanCollide
						part.Massless = props.Massless
					end)
				end
			end
			state.Parts = {}
		end

		if Root and Root.Parent then
			Root.AssemblyLinearVelocity = Vector3.zero
			Root.AssemblyAngularVelocity = Vector3.zero
		end
	end

	Weld.Disconnect = Weld.Destroy
	return Weld
end

platformParts = {}
headsitWeld = nil

function stopHeadSit(launchHumanoid)
	NAStuff.headsitActive = false
	NAStuff.headsitToken = (tonumber(NAStuff.headsitToken) or 0) + 1

	NAlib.disconnect("headsit_follow")
	NAlib.disconnect("headsit_died")
	NAlib.disconnect("headsit_jump")
	NAlib.disconnect("headsit_state")

	if headsitWeld then
		headsitWeld:Destroy()
		headsitWeld = nil
	end

	for _, part in platformParts do
		pcall(function()
			part:Destroy()
		end)
	end
	platformParts = {}

	const char = getChar()
	const hum = char and getHum(char)
	if hum then
		hum.Sit = false
		if launchHumanoid then
			NAmanage.LaunchHumanoid(hum, getRoot(char))
		end
	end
end

NAmanage.RegisterUnloadCleanup("headsit_cleanup", function()
	stopHeadSit(false)
end, 60)

cmd.register({
	name = "headsit",
	description = "Sit on a player or NPC's head",
	usage = "headsit <player|npc:filter>",
	requiresArguments = true,
	callback = function(...)
		const query = Concat({...}, " ")
		const targets = getPlr(query)
		const plr = targets and targets[1]
		if not plr then return end

		stopHeadSit(false)

		const char = getChar()
		const hum = char and getHum(char)
		const targetChar = NAmanage.PlayerArgChar(plr)
		const targetHead = targetChar and getHead(targetChar)
		if not char or not char.Parent
			or not hum or not hum.Parent or hum.Health <= 0
			or not targetHead or not targetHead.Parent then
			return
		end

		NAStuff.headsitActive = true
		hum.Sit = true
		headsitWeld = NAmanage.WeldToPlayerPart(targetHead, CFrame.new(0, 1.6, 0.4), LocalPlayer, nil)
		if not headsitWeld then
			NAStuff.headsitActive = false
			hum.Sit = false
			return
		end

		NAlib.connect("headsit_died", NAmanage.ConnectHumanoidDeath(hum, function()
			stopHeadSit(false)
		end))
		NAlib.connect("headsit_jump", hum:GetPropertyChangedSignal("Jump"):Connect(function()
			if hum.Jump then
				stopHeadSit(false)
			end
		end))
		NAlib.connect("headsit_state", hum.StateChanged:Connect(function(_, state)
			if state == Enum.HumanoidStateType.Jumping then
				stopHeadSit(false)
			end
		end))
	end,
})

cmd.register({
	name = "unheadsit",
