	callback = function()
		NAStuff.loopjp = false
		NAlib.disconnect("loopjp_apply")
		NAlib.disconnect("loopjp_mode")
		NAlib.disconnect("loopjp_char")
	end,
})

cmd.register({
	name = "stopanimations",
	aliases = { "stopanims", "stopanim", "noanim" },
	description = "Stops running animations",
	usage = "stopanimations (stopanims,stopanim,noanim)",
	callback = function()
		const char = Services.Players.LocalPlayer and Services.Players.LocalPlayer.Character
		const hum = getHum()
		if not hum then return end

