cmd.register({
	name = "refreshanimations",
	aliases = { "refreshanimation", "refreshanims", "refreshanim" },
	description = "Reload character animations",
	usage = "refreshanimations (refreshanimation,refreshanims,refreshanim)",
	callback = function()
		const char=getChar()
		if not char then
			DoNotif("Character unavailable",2)
			return
		end
		const humanoid=getPlrHum(char)
		const animate=char:FindFirstChild("Animate")
		if not humanoid or not animate then
			DoNotif("Failed to locate Animate or Humanoid",3)
			return
		end
		animate.Disabled=true
		pcall(function()
			for _,track in humanoid:GetPlayingAnimationTracks() do
				track:Stop()
			end
		end)
		animate.Disabled=false
		DoNotif("Animations refreshed",2)
	end,
})

loopwave = false

cmd.register({
	name = "loopwaveat",
	aliases = { "loopwat" },
	description = "Wave to a player or NPC in a loop",
	usage = "loopwaveat <player|npc:filter> (loopwat)",
	requiresArguments = true,
	callback = function(...)
		loopwave = true
		const playerName = (...)
		const targets = getPlr(playerName)
		for _, plr in next, targets do
			const char = getChar()
			const root = char and getRoot(char)
			const hum = char and char:FindFirstChildOfClass("Humanoid")
			if not (root and hum) then return end
			const oldCFrame = NAmanage.UG_clientCFrame(root) or root.CFrame
			repeat
				Wait(0.2)
				if getChar() ~= char or not root.Parent or not hum.Parent then break end
				const targetChar = NAmanage.PlayerArgChar(plr)
				const targetRoot = targetChar and getRoot(targetChar)
				if not targetRoot then break end
				const targetCFrame = targetRoot.CFrame
				const waveAnim = InstanceNew("Animation")
				if hum.RigType == Enum.HumanoidRigType.R15 then
					waveAnim.AnimationId = "rbxassetid://507770239"
				else
					waveAnim.AnimationId = "rbxassetid://128777973"
				end
				NAmanage.UG_setRootCFrame(root, targetCFrame * CFrame.new(0, 0, -3))
				const charPos = root.Position
				const tpos = targetRoot.Position
				const newCFrame = CFrame.new(charPos, Vector3.new(tpos.X, charPos.Y, tpos.Z))
				NAmanage.UG_pivotModel(char, newCFrame)
				const wave = hum:LoadAnimation(waveAnim)
				wave:Play(-1, 5, -1)
				Wait(1.6)
				wave:Stop()
			until not loopwave
			if root.Parent then NAmanage.UG_setClientCFrame(root, oldCFrame) end
		end
	end,
})

cmd.register({
	name = "unloopwaveat",
	aliases = { "unloopwat" },
	description = "Stops the loopwaveat command",
	usage = "unloopwaveat (unloopwat)",
	callback = function()
		loopwave = false
	end,
})

cmd.register({
	name = "tools",
	aliases = { "gears" },
	description = "Copies tools from ReplicatedStorage and Lighting",
	usage = "tools (gears)",
	callback = function()
		function copyTools(source)
			for _, className in { "Tool", "HopperBin" } do
				for _, item in NAmanage.QueryDescendants(source, className) do
					item:Clone().Parent = getBp()
				end
			end
		end

		copyTools(Services.Lighting)
		copyTools(Services.ReplicatedStorage)

		Wait()
		DebugNotif("Copied tools from ReplicatedStorage and Lighting", 3)
	end,
})

