	description = "Stops the custom air momentum command",
	usage = "unairmomentum (unamomentum, unaircontrol)",
	callback = function()
		NAmanage.DisableAirMomentum()
	end,
})

bringc = {}

NAmanage.parseBringDistance=function(args, defaultDistance)
	const distance = tonumber(args[#args])
	if distance then
		table.remove(args, #args)
		return math.clamp(distance, 0, 1000)
	end
	return defaultDistance or 0
end

NAmanage.bringOffsetCFrame=function(cf, distance)
	if not cf then return nil end
	distance = tonumber(distance) or 0
	return cf + cf.LookVector * distance
end

cmd.register({
	name = "cbring",
	aliases = { "clientbring", "clientb" },
	description = "Brings a player or NPC once on your client",
	usage = "cbring <player|npc:filter> [distance]",
	requiresArguments = true,
	callback = function(...)
		const args = {...}
		const distance = NAmanage.parseBringDistance(args, 3)
		const username = args[1]
		const target = getPlr(username)
		if #target == 0 then return end
		const localChar = getChar()
		if not localChar then return end
		const localRoot = getRoot(localChar)
		if not localRoot then return end
		for _, plr in next, target do
			const targetChar = getPlrChar(plr)
			if targetChar then
				const targetRoot = getRoot(targetChar)
				if targetRoot then
					targetRoot.CFrame = NAmanage.bringOffsetCFrame(localRoot.CFrame, distance)
				end
			end
		end
	end,
})

NAmanage.CBringStop = function()
	NAlib.disconnect("cbring")
	NAlib.disconnect("cbnoclip")
	table.clear(bringc)
end
NAmanage.RegisterUnloadCleanup("cbring_cleanup", NAmanage.CBringStop)

cmd.register({
	name = "loopcbring",
	aliases = { "loopclientb", "loppclientb", "loopclientbring", "lcbring", "lclientb" },
	description = "Continuously brings a player or NPC on your client",
	usage = "loopcbring <player|npc:filter> [distance]",
	requiresArguments = true,
	callback = function(...)
		const args = {...}
		const distance = NAmanage.parseBringDistance(args, 3)
		const target = getPlr(args[1])
		if #target == 0 then return end
		NAmanage.CBringStop()
		NAlib.connect("cbnoclip", Services.RunService.PreSimulation:Connect(function()
			const char = getChar()
			if not char then return end
			for part in NAmanage.GetCharacterParts(char) do
				if part.Parent and part.CanCollide then part.CanCollide = false end
			end
		end))
		Insert(bringc, NAlib.connect("cbring", Services.RunService.RenderStepped:Connect(function()
			const char = getChar()
			const root = char and getRoot(char)
			if not root then return end
			const cf = NAmanage.bringOffsetCFrame(root.CFrame, distance)
			for _, plr in target do
				const model = getPlrChar(plr)
				const part = model and getRoot(model)
				if part then part.CFrame = cf end
			end
		end)))
	end,
})

cmd.register({
	name = "unloopcbring",
	aliases = { "unloopclientb", "unloopcientb", "unlcbring", "unlclientb", "uncbring", "unclientb" },
	description = "Disable looped client bring",
	callback = NAmanage.CBringStop,
})

cmd.register({
	name = "mute",
	aliases = { "muteboombox" },
	description = "Mutes sounds from a player or NPC",
	usage = "mute <player|npc:filter> (muteboombox)",
	requiresArguments = true,
	callback = function(...)
		const uuuu = ...
		const pp = getPlr(uuuu)
		if #pp == 0 then return end

		const function NONOSOUND(container)
			for _, descendant in NAmanage.QueryDescendants(container, "Sound") do
				if descendant.Playing then
					descendant.Playing = false
				end
			end
		end

		for _, plr in pp do
			const targetChar = plr and NAmanage.PlayerArgChar(plr)
			if targetChar then
				NONOSOUND(targetChar)
			end

			const BK = plr:IsA("Player") and plr:FindFirstChildOfClass("Backpack") or nil
			if BK then
				NONOSOUND(BK)
			end
		end
	end,
})

NAmanage.GetOffsetWalkState = function()
	if type(NAStuff.OffsetWalkState) ~= "table" then
		NAStuff.OffsetWalkState = {}
	end
	const state = NAStuff.OffsetWalkState
	state.holdDuration = math.max(0.01, tonumber(state.holdDuration) or 0.13)
	state.interval = state.holdDuration
	state.bindName = tostring(state.bindName or "NA_OffsetWalkReplication")
	state.externalTeleportDistance = math.max(0.5, tonumber(state.externalTeleportDistance) or 4)
	return state
end

NAmanage.OffsetWalkCFrameNear = function(a, b, distance)
	return typeof(a) == "CFrame" and typeof(b) == "CFrame"
		and (a.Position - b.Position).Magnitude <= (distance or 0.05)
end

NAmanage.OffsetWalkAdoptExternalCFrame = function(root, observed)
	const state = NAmanage.GetOffsetWalkState()
	if not root or typeof(observed) ~= "CFrame" then
		return false
	end
	if typeof(state.localCFrame) ~= "CFrame" then
		state.localCFrame = observed
		state.serverCFrame = observed
		state.lastBurst = os.clock()
		return true
	end
	if NAmanage.OffsetWalkCFrameNear(observed, state.serverCFrame) then
		return false
	end
	const dynamicDistance = math.max(state.externalTeleportDistance, (tonumber(state.speed) or 16) * 0.04)
	if (observed.Position - state.localCFrame.Position).Magnitude < dynamicDistance then
		return false
	end
	state.localCFrame = observed
	state.serverCFrame = observed
	state.lastBurst = os.clock()
	state.lastWriteCFrame = observed
	return true
end

NAmanage.OffsetWalkGetUndergroundState = function(root)
	const undergroundState = NAStuff.NAundergroundState
	if type(undergroundState) ~= "table" or undergroundState.Underground ~= true then
		return nil
	end
	if root and type(NAmanage.UG_isLocalRoot) == "function" and not NAmanage.UG_isLocalRoot(root) then
		return nil
	end
	return undergroundState
end

NAmanage.OffsetWalkReplicationCFrame = function(root, hum, baseCFrame, localCFrame)
	if typeof(baseCFrame) ~= "CFrame" then
		return baseCFrame
	end
	const undergroundState = NAmanage.OffsetWalkGetUndergroundState(root)
	if not undergroundState then
		return baseCFrame
	end
	if typeof(localCFrame) == "CFrame" then
		undergroundState.UndergroundCurrent = localCFrame
	end
	const activeTransform = type(NAmanage.UG_getTransform) == "function"
		and NAmanage.UG_getTransform(undergroundState) or CFrame.new()
	const activeOffset = type(NAmanage.UG_getActiveOffset) == "function"
		and NAmanage.UG_getActiveOffset(undergroundState, root, hum)
		or (undergroundState.UndergroundOffset or Vector3.new(0, 0, 0))
	undergroundState.UndergroundResolvedOffset = activeOffset
	undergroundState.UndergroundServerCFrame = (baseCFrame * activeTransform) + activeOffset
	return undergroundState.UndergroundServerCFrame
end

NAmanage.OffsetWalkRestoreDirectSpeed = function(state, hum)
	state = type(state) == "table" and state or NAmanage.GetOffsetWalkState()
	hum = hum or getHum()
	if not hum then
		return
	end
	local restore = nil
	if NAStuff.SafeSpeedMethod == false then
		if NAStuff.loopws and tonumber(_na_env.NamelessWs) then
			restore = tonumber(_na_env.NamelessWs)
		elseif tonumber(_na_env.NamelessSpeed) then
			restore = tonumber(_na_env.NamelessSpeed)
		end
	end
	restore = restore or tonumber(state.originalWalkSpeed)
	if restore then
		pcall(function()
			hum.WalkSpeed = restore
		end)
	end
end

NAmanage.StopOffsetWalk = function(silent)
	const state = NAmanage.GetOffsetWalkState()
	const localCFrame = state.localCFrame
	state.active = false
	NAlib.disconnect("na_offsetwalk_heartbeat")
	NAlib.disconnect("na_offsetwalk_post")
	if Services.RunService and Services.RunService.UnbindFromRenderStep then
		pcall(Services.RunService.UnbindFromRenderStep, Services.RunService, state.bindName)
	end
	const root = getRoot(getChar())
	if root and typeof(localCFrame) == "CFrame" then
		pcall(function()
			root.CFrame = localCFrame
			if typeof(state.localLinearVelocity) == "Vector3" then
				root.AssemblyLinearVelocity = state.localLinearVelocity
			end
		end)
	end
	const hum = getHum()
	NAmanage.OffsetWalkRestoreDirectSpeed(state, hum)
	state.root = nil
	state.humanoid = nil
	state.originalWalkSpeed = nil
	state.localCFrame = nil
	state.serverCFrame = nil
	state.lastBurst = nil
	state.lastWriteCFrame = nil
	state.lastAnchorUpdate = nil
	state.localLinearVelocity = nil
	state.phase = nil
	state.phaseStarted = nil
	state.suppressExternalAdoptUntil = nil
	state.speed = nil
	if NAStuff._unloading ~= true then
		if NAStuff.SafeSpeedMethod ~= false then
			NAmanage.StopVelocityWalkSpeed()
			if tonumber(_na_env.NamelessSpeed) and tonumber(_na_env.NamelessSpeed) > 0 then
				NAmanage.RefreshVelocityWalkSpeed()
			end
		elseif NAStuff.loopws and tonumber(_na_env.NamelessWs) then
			NAmanage.StartLegacyLoopWalkSpeed(tonumber(_na_env.NamelessWs))
		end
	else
		NAmanage.StopVelocityWalkSpeed()
		NAmanage.StopLegacyLoopWalkSpeed()
	end
	if not silent then
		DoNotif("Offset Walk disabled", 2)
	end
end

NAmanage.OffsetWalkResetRootState = function(state, root, hum)
	if not (state and root and hum) then
		return false
	end
	state.root = root
	state.humanoid = hum
	state.originalWalkSpeed = state.originalWalkSpeed or tonumber(hum.WalkSpeed)
	const undergroundState = NAmanage.OffsetWalkGetUndergroundState(root)
	const resetCFrame = undergroundState and typeof(undergroundState.UndergroundCurrent) == "CFrame"
		and undergroundState.UndergroundCurrent or root.CFrame
	state.localCFrame = resetCFrame
	state.serverCFrame = resetCFrame
	state.lastAnchorUpdate = os.clock()
	state.lastBurst = state.lastAnchorUpdate
	state.lastWriteCFrame = resetCFrame
	const velocity = NAlib.isProperty(root, "AssemblyLinearVelocity")
	if typeof(velocity) == "Vector3" then
		state.localLinearVelocity = velocity
	end
	return true
end

NAmanage.OffsetWalkWriteAnchor = function(state, root, hum)
	if not (state and root and hum) then
		return
	end
	const anchor = state.serverCFrame or state.localCFrame or root.CFrame
	const replicationCFrame = NAmanage.OffsetWalkReplicationCFrame(root, hum, anchor, state.localCFrame) or anchor
	state.lastWriteCFrame = replicationCFrame
	pcall(function()
		root.CFrame = replicationCFrame
		if typeof(state.localLinearVelocity) == "Vector3" then
			root.AssemblyLinearVelocity = Vector3.zero
		end
	end)
end

NAmanage.OffsetWalkStep = function(state)
	if not (state and state.active == true) then
		return
	end
	const currentChar = getChar()
	const currentHum = getHum(currentChar)
	const currentRoot = getRoot(currentChar)
	if not (currentChar and currentHum and currentRoot) then
		return
	end
	if state.root ~= currentRoot then
		NAmanage.OffsetWalkResetRootState(state, currentRoot, currentHum)
	end
	if NAStuff.SafeSpeedMethod ~= false then
		if not NAlib.isConnected("na_velocityws_apply") then
			NAmanage.RefreshVelocityWalkSpeed()
		end
	elseif currentHum.WalkSpeed ~= state.speed then
		currentHum.WalkSpeed = state.speed
	end

	const observed = currentRoot.CFrame
	const heldBase = state.serverCFrame
	const heldReplication = typeof(heldBase) == "CFrame"
		and NAmanage.OffsetWalkReplicationCFrame(currentRoot, currentHum, heldBase, state.localCFrame) or nil
	const nearHeld = NAmanage.OffsetWalkCFrameNear(observed, heldBase)
		or NAmanage.OffsetWalkCFrameNear(observed, heldReplication)
	const suppressExternalAdopt = os.clock() < (tonumber(state.suppressExternalAdoptUntil) or 0)
	if typeof(state.localCFrame) ~= "CFrame" or (not nearHeld and not suppressExternalAdopt) then
		state.localCFrame = observed
		const velocity = NAlib.isProperty(currentRoot, "AssemblyLinearVelocity")
		if typeof(velocity) == "Vector3" then
			state.localLinearVelocity = velocity
		end
	end

	const now = os.clock()
	if now - (tonumber(state.lastAnchorUpdate) or now) >= state.holdDuration then
		state.serverCFrame = state.localCFrame or observed
		state.lastAnchorUpdate = now
		state.lastBurst = now
	end

	NAmanage.OffsetWalkWriteAnchor(state, currentRoot, currentHum)
end

NAmanage.OffsetWalkRender = function(state)
	if not (state and state.active == true) then
		return
	end
	const currentRoot = getRoot(getChar())
	if not currentRoot then
		return
	end
	const localCFrame = state.localCFrame
	if typeof(localCFrame) ~= "CFrame" then
		return
	end
	pcall(function()
		currentRoot.CFrame = localCFrame
		if typeof(state.localLinearVelocity) == "Vector3" then
			currentRoot.AssemblyLinearVelocity = state.localLinearVelocity
		end
	end)
	const undergroundState = NAmanage.OffsetWalkGetUndergroundState(currentRoot)
	if undergroundState then
		undergroundState.UndergroundCurrent = localCFrame
	end
end

NAmanage.StartOffsetWalk = function(value)
	const speed = tonumber(value)
	if not speed or speed <= 0 then
		NAmanage.StopOffsetWalk(true)
		return false
	end
	const char = getChar()
	const hum = getHum(char)
	const root = getRoot(char)
	if not (char and hum and root) then
		return false
	end
	if TPWalk then
		TPWalk = false
		NAlib.disconnect("TPWalkingConnection")
	end
	const state = NAmanage.GetOffsetWalkState()
	if state.active ~= true or state.root ~= root then
		state.originalWalkSpeed = tonumber(hum.WalkSpeed)
	end
	state.active = true
	state.speed = speed
	state.holdDuration = 0.13
	state.interval = state.holdDuration
	NAmanage.OffsetWalkResetRootState(state, root, hum)
	NAmanage.StopLegacyLoopWalkSpeed()
	if NAStuff.SafeSpeedMethod ~= false then
		NAmanage.RefreshVelocityWalkSpeed()
	else
		NAmanage.StopVelocityWalkSpeed()
		hum.WalkSpeed = speed
	end
	NAlib.disconnect("na_offsetwalk_heartbeat")
	NAlib.disconnect("na_offsetwalk_post")
	if Services.RunService and Services.RunService.UnbindFromRenderStep then
		pcall(Services.RunService.UnbindFromRenderStep, Services.RunService, state.bindName)
	end
	if Services.RunService and Services.RunService.PostSimulation then
		NAlib.connect("na_offsetwalk_post", Services.RunService.PostSimulation:Connect(function()
			NAmanage.OffsetWalkStep(state)
		end))
	end
	NAlib.connect("na_offsetwalk_heartbeat", Services.RunService.Heartbeat:Connect(function()
		NAmanage.OffsetWalkStep(state)
	end))
	if Services.RunService and Services.RunService.BindToRenderStep then
		Services.RunService:BindToRenderStep(state.bindName, Enum.RenderPriority.First.Value, function()
			NAmanage.OffsetWalkRender(state)
		end)
	end
	return true
end

cmd.register({
	name = "offsetwalk",
	aliases = { "owalk", "offsetspeed", "ospeed" },
	description = "moves the character by teleporting it a set number of studs every frame",
	usage = "offsetwalk <number|off> (owalk,offsetspeed,ospeed)",
	requiresArguments = true,
	callback = function(...)
		const args = {...}
		const value = args[2] or args[1]
		const text = string.lower(tostring(value or "16"))
		if text == "off" or text == "disable" or text == "disabled" or text == "reset" then
			NAmanage.StopOffsetWalk(true)
			DoNotif("Offset Walk disabled", 2)
			return
		end
		const speed = tonumber(value) or 16
		if speed <= 0 then
			NAmanage.StopOffsetWalk(true)
			DoNotif("Offset Walk disabled", 2)
			return
		end
		if NAmanage.StartOffsetWalk(speed) then
			DoNotif("Offset Walk: "..tostring(speed).." ("..(NAStuff.SafeSpeedMethod ~= false and "Safe Speed" or "WalkSpeed")..")", 2)
		else
			DoNotif("Offset Walk failed: character is not ready", 3)
		end
	end,
})

cmd.register({
	name = "unoffsetwalk",
	aliases = { "unowalk", "unoffsetspeed", "unospeed" },
	description = "Stops Offset Walk",
	usage = "unoffsetwalk (unowalk,unoffsetspeed,unospeed)",
	callback = function()
		NAmanage.StopOffsetWalk(true)
		DoNotif("Offset Walk disabled", 2)
	end,
})

TPWalk = false

cmd.register({
	name = "tpwalk",
	aliases = { "tpwalk" },
	description = "More undetectable walkspeed script",
	usage = "tpwalk <number>",
	requiresArguments = true,
	callback = function(...)
		if type(NAmanage.StopOffsetWalk) == "function" then
			NAmanage.StopOffsetWalk(true)
		end
		if TPWalk then
			TPWalk = false
			NAlib.disconnect("TPWalkingConnection")
		end

		TPWalk = true
		const Speed = tonumber(...) or 1
		const stepRate = 1 / 60
		const maxSteps = 3
		local accumulator = 0

		NAlib.connect("TPWalkingConnection", Services.RunService.Heartbeat:Connect(function(deltaTime)
			if not TPWalk then
				return
			end
			accumulator = math.min(accumulator + (tonumber(deltaTime) or 0), stepRate * maxSteps)
			const humanoid = getHum()
			const char = getChar()
			if not humanoid or not char or humanoid.MoveDirection.Magnitude <= 0 then
				return
			end
			const moveDirection = humanoid.MoveDirection
			local steps = 0
			while accumulator >= stepRate and steps < maxSteps do
				const stepDelta = moveDirection * Speed * stepRate * 10
				const undergroundState = NAStuff and NAStuff.NAundergroundState
				if undergroundState and undergroundState.Underground then
					undergroundState.PendingTranslation = (undergroundState.PendingTranslation or Vector3.new(0, 0, 0)) + stepDelta
				else
					char:TranslateBy(stepDelta)
				end
				accumulator -= stepRate
				steps += 1
			end
		end))
	end,
})

cmd.register({
	name = "untpwalk",
	description = "Stops the tpwalk command",
	callback = function()
		TPWalk = false
		NAlib.disconnect("TPWalkingConnection")
	end,
})

TPJump = false

NAmanage.TPJumpInputAllowed = function(hum)
	if not hum then
		return false
	end
	if hum.FloorMaterial ~= Enum.Material.Air then
		return true
	end
	return (NAlib.isConnected("infjump_jump") or NAlib.isConnected("flyjump")) and true or false
end

NAmanage.TPJumpPulse = function(force)
	const st = NAStuff and NAStuff.TPJumpState
	if not (TPJump and st) then
		return false
	end

	const char = getChar()
	const hum = char and getHum(char)
	const root = char and getRoot(char)
	if not (char and hum and root and hum.Health > 0) then
		return false
	end

	if not force and not NAmanage.TPJumpInputAllowed(hum) then
		return false
	end

	const now = os.clock()
	st.untilTime = math.max(st.untilTime or 0, now + (force and 0.2 or 0.15))
	st.accumulator = math.max(st.accumulator or 0, st.stepRate or (1 / 60))
	st.lastPulse = now
	return true
end

cmd.register({
	name = "tpjump",
	aliases = { "tjump" },
	description = "",
	usage = "tpjump <number>",
	requiresArguments = true,
	callback = function(...)
		if TPJump then
			TPJump = false
			NAlib.disconnect("TPJumpConnection")
			NAlib.disconnect("TPJumpRequest")
			NAlib.disconnect("TPJumpCharacter")
			NAlib.disconnect("TPJumpHumanoidJump")
		end

		TPJump = true
		const Speed = math.clamp(math.abs(tonumber(...) or 1), 0.1, 100)
		const stepRate = 1 / 60
		const maxSteps = 3
		const st = {
			speed = Speed,
			stepRate = stepRate,
			maxSteps = maxSteps,
			accumulator = 0,
			untilTime = 0,
			lastPulse = 0,
		}
		NAStuff.TPJumpState = st

		const function bindHumanoidJump()
			NAlib.disconnect("TPJumpHumanoidJump")
			const hum = getHum()
			if hum then
				NAlib.connect("TPJumpHumanoidJump", hum.Jumping:Connect(function(active)
					if active then
						NAmanage.TPJumpPulse()
					end
				end))
			end
		end

		bindHumanoidJump()

		NAlib.reconnect("TPJumpRequest", Services.UserInputService.JumpRequest:Connect(function()
			NAmanage.TPJumpPulse()
		end))

		NAlib.reconnect("TPJumpCharacter", LocalPlayer.CharacterAdded:Connect(function()
			st.accumulator = 0
			st.untilTime = 0
			Defer(function()
				Wait(0.15)
				if TPJump then
					bindHumanoidJump()
				end
			end)
		end))

		NAlib.reconnect("TPJumpConnection", Services.RunService.Heartbeat:Connect(function(deltaTime)
			if not TPJump then
				return
			end

			const humanoid = getHum()
			const char = getChar()
			if not humanoid or not char or humanoid.Health <= 0 then
				return
			end

			const state = humanoid:GetState()
			const jumping = humanoid.Jump == true or state == Enum.HumanoidStateType.Jumping
			if jumping then
				NAmanage.TPJumpPulse()
			end

			if os.clock() > (st.untilTime or 0) then
				st.accumulator = 0
				return
			end

			st.accumulator = math.min((st.accumulator or 0) + (tonumber(deltaTime) or 0), stepRate * maxSteps)
			const root = getRoot(char)
			local steps = 0
			while st.accumulator >= stepRate and steps < maxSteps do
				const stepDelta = Vector3.new(0, st.speed * stepRate * 10, 0)
				const undergroundState = NAStuff and NAStuff.NAundergroundState
				if undergroundState and undergroundState.Underground then
					undergroundState.PendingTranslation = (undergroundState.PendingTranslation or Vector3.new(0, 0, 0)) + stepDelta
				else
					char:TranslateBy(stepDelta)
				end
				st.accumulator -= stepRate
				steps += 1
			end
			if root then
				const vel = NAlib.isProperty(root, "AssemblyLinearVelocity") or root.Velocity
				if typeof(vel) == "Vector3" and vel.Y > 20 then
					NAlib.setProperty(root, "AssemblyLinearVelocity", Vector3.new(vel.X, 20, vel.Z))
				end
			end
		end))
	end,
})

