NAStuff.instantProximityPrompts = { active = false; epoch = 0 }
NAStuff.fastProximityPrompts = type(NAStuff.fastProximityPrompts) == "table" and NAStuff.fastProximityPrompts or {}
NAStuff.fastProximityPrompts.active = NAStuff.fastProximityPrompts.active == true
NAStuff.fastProximityPrompts.multiplier = math.max(tonumber(NAStuff.fastProximityPrompts.multiplier) or 2, 0.01)
NAStuff.fastProximityPrompts.prompts = NAmanage.ensureWeakKeyTable(NAStuff.fastProximityPrompts.prompts)

NAmanage.InstantProximityPromptsDisable = function()
	const state = NAStuff.instantProximityPrompts
	state.active = false
	state.epoch = (state.epoch or 0) + 1
	NAlib.disconnect("instantpp")
end

NAmanage.FastProximityPromptsTrack = function(pp)
	const state = NAStuff.fastProximityPrompts
	if state.active ~= true or typeof(pp) ~= "Instance" or not pp:IsA("ProximityPrompt") or state.prompts[pp] then
		return
	end
	local okDuration, duration = pcall(function()
		return pp.HoldDuration
	end)
	if not okDuration then
		return
	end
	const record = {
		restore = duration;
		applied = math.max(duration / state.multiplier, 0);
		connection = nil;
		writing = false;
	}
	state.prompts[pp] = record
	local okConnection, connection = pcall(function()
		return pp:GetPropertyChangedSignal("HoldDuration"):Connect(function()
			if state.active ~= true or state.prompts[pp] ~= record or record.writing then
				return
			end
			local okCurrent, current = pcall(function()
				return pp.HoldDuration
			end)
			if okCurrent and current ~= record.applied then
				record.restore = current
				record.applied = math.max(current / state.multiplier, 0)
				record.writing = true
				pcall(function()
					pp.HoldDuration = record.applied
					record.applied = pp.HoldDuration
				end)
				record.writing = false
			end
		end)
	end)
	if okConnection then
		record.connection = connection
	end
	record.writing = true
	pcall(function()
		pp.HoldDuration = record.applied
		record.applied = pp.HoldDuration
	end)
	record.writing = false
end

-- PART 17
NAmanage.FastProximityPromptsUntrack = function(pp, restore)
	const state = NAStuff.fastProximityPrompts
	const record = state.prompts[pp]
	if not record then
		return
	end
	state.prompts[pp] = nil
	record.connection = NAmanage.tryDisconnect(record.connection)
	if restore == true and typeof(pp) == "Instance" and pp:IsA("ProximityPrompt") then
		pcall(function()
			pp.HoldDuration = record.restore
		end)
	end
end

NAmanage.FastProximityPromptsDisable = function()
	const state = NAStuff.fastProximityPrompts
	state.active = false
	NAlib.disconnect("fastpp")
	NAmanage.clrWsH("fastpp_duration")
	const prompts = {}
	for pp in state.prompts do
		prompts[#prompts + 1] = pp
	end
	for i = 1, #prompts do
		NAmanage.FastProximityPromptsUntrack(prompts[i], true)
	end
end

do
	const pps = SafeGetService("ProximityPromptService")
	const pending = NAmanage.ensureWeakKeyTable()
	NAStuff.ppWalls = { active = false; prompts = NAmanage.ensureWeakKeyTable() }
	NAStuff.ppDistance = { active = false; prompts = NAmanage.ensureWeakKeyTable(); multiplier = 2 }
	NAStuff.multiProximityPrompts = { active = false; prompts = NAmanage.ensureWeakKeyTable(); shown = NAmanage.ensureWeakKeyTable() }

	NAmanage.PromptPropertyUntrack = function(state, pp, restore)
		const rec = state.prompts[pp]
		if not rec then return end
		state.prompts[pp] = nil
		for _, conn in rec.conns do NAmanage.tryDisconnect(conn) end
		if restore then
			pcall(function()
				if pp[state.property] ~= rec.restore then pp[state.property] = rec.restore end
			end)
		end
	end

	NAmanage.PromptPropertyStop = function(state)
		state.active = false
		state.epoch = (state.epoch or 0) + 1
		if state.key then
			NAmanage.clrWsH(state.key)
			NAlib.disconnect(state.key.."_shown")
		end
		const list = {}
		for pp in state.prompts do list[#list + 1] = pp end
		for _, pp in list do NAmanage.PromptPropertyUntrack(state, pp, true) end
	end

	NAmanage.PromptPropertyStart = function(state, key, property, value)
		NAmanage.PromptPropertyStop(state)
		state.active, state.key, state.property = true, key, property
		const epoch = state.epoch
		const function track(pp)
			if not state.active or state.epoch ~= epoch or typeof(pp) ~= "Instance" or not pp:IsA("ProximityPrompt")
				or not pp:IsDescendantOf(Services.Workspace) or state.prompts[pp] then return end
			const rec = { restore = pp[property]; applied = pp[property]; writing = false; conns = {} }
			state.prompts[pp] = rec
			const function apply()
				if not state.active or state.epoch ~= epoch or state.prompts[pp] ~= rec or rec.writing then return end
				const current = pp[property]
				if current ~= rec.applied then rec.restore = current end
				const wanted = value(rec.restore)
				rec.applied = wanted
				if current ~= wanted then
					rec.writing = true
					pp[property] = wanted
					rec.applied = pp[property]
					rec.writing = false
				end
			end
			rec.conns[1] = pp:GetPropertyChangedSignal(property):Connect(apply)
			rec.conns[2] = pp:GetPropertyChangedSignal("Enabled"):Connect(apply)
			rec.conns[3] = pp.Destroying:Connect(function() NAmanage.PromptPropertyUntrack(state, pp, false) end)
			apply()
		end
		state.track = track
		NAmanage.setWsH(key, {
			added = track;
			removing = function(pp) NAmanage.PromptPropertyUntrack(state, pp, true) end;
			classNames = { "ProximityPrompt" };
			enabled = function() return state.active and state.epoch == epoch end;
		})
		NAlib.connect(key.."_shown", pps.PromptShown:Connect(track))
		const work = {}
		for _, pp in NAmanage.QueryDescendants(Services.Workspace, "ProximityPrompt") do
			if not state.active or state.epoch ~= epoch then break end
			track(pp)
			NAmanage.WorkBudgetStep(work, 160, 0.003)
		end
	end

	NAmanage.IsAutomaticPrompt = function(pp)
		const rec = pending[pp]
		return rec ~= nil and (rec.busy or os.clock() < rec.untilTime)
	end

	NAmanage.FirePromptOnce = function(pp, enabled)
		if typeof(pp) ~= "Instance" or not pp:IsA("ProximityPrompt") or not pp.Parent or not pp.Enabled
			or NAmanage.IsAutomaticPrompt(pp) or type(fireproximityprompt) ~= "function" then return false end
		const rec = { busy = true; untilTime = math.huge }
		pending[pp] = rec
		Spawn(function()
			if not enabled or enabled() then pcall(fireproximityprompt, pp) end
			rec.busy = false
			rec.untilTime = os.clock() + 0.15
			Delay(0.2, function() if pending[pp] == rec then pending[pp] = nil end end)
		end)
		return true
	end

	NAmanage.PromptWorldPosition = function(pp)
		const parent = pp and pp.Parent
		if not parent then return nil end
		if parent:IsA("Attachment") then return parent.WorldPosition end
		if parent:IsA("BasePart") then return parent.Position end
		if parent:IsA("Model") and parent.PrimaryPart then return parent.PrimaryPart.Position end
		return nil
	end

	NAmanage.MultiPromptVisible = function(pp)
		const state = NAStuff.multiProximityPrompts
		if not state.active or state.shown[pp] == false or not state.prompts[pp] or not pps.Enabled or not pp.Parent or not pp.Enabled then return false end
		const camera = Services.Workspace.CurrentCamera
		const pos = NAmanage.PromptWorldPosition(pp)
		const char = rPlayer.Character
		const root = char and (char:FindFirstChild("HumanoidRootPart") or char.PrimaryPart)
		if not camera or not pos or not root or (root.Position - pos).Magnitude > pp.MaxActivationDistance + 0.01 then return false end
		const point, visible = camera:WorldToViewportPoint(pos)
		if not visible or point.Z <= 0 then return false end
		if pp.RequiresLineOfSight then
			const params = RaycastParams.new()
			params.FilterType = Enum.RaycastFilterType.Exclude
			params.FilterDescendantsInstances = { char }
			const hit = Services.Workspace:Raycast(camera.CFrame.Position, pos - camera.CFrame.Position, params)
			const owner = pp.Parent:IsA("Attachment") and pp.Parent.Parent or pp.Parent
			if hit and hit.Instance ~= owner and not (owner:IsA("Model") and hit.Instance:IsDescendantOf(owner)) then return false end
		end
		return true
	end

	NAmanage.MultiPromptFire = function(source)
		const state = NAStuff.multiProximityPrompts
		if not state.active then return end
		const epoch = state.epoch
		const list = {}
		for pp in state.prompts do
			if pp ~= source and NAmanage.MultiPromptVisible(pp) then list[#list + 1] = pp end
		end
		for _, pp in list do
			NAmanage.FirePromptOnce(pp, function() return state.active and state.epoch == epoch end)
		end
	end

	NAmanage.MultiPromptsDisable = function()
		const state = NAStuff.multiProximityPrompts
		NAmanage.PromptPropertyStop(state)
		NAlib.disconnect("multiprompts_events")
		table.clear(state.shown)
	end

	NAmanage.PromptWallsDisable = function() NAmanage.PromptPropertyStop(NAStuff.ppWalls) end
	NAmanage.PromptDistanceDisable = function() NAmanage.PromptPropertyStop(NAStuff.ppDistance) end
	NAmanage.RegisterUnloadCleanup("promptwalls_restore", NAmanage.PromptWallsDisable)
	NAmanage.RegisterUnloadCleanup("promptdistance_restore", NAmanage.PromptDistanceDisable)
	NAmanage.RegisterUnloadCleanup("multiprompts_restore", NAmanage.MultiPromptsDisable)
	NAmanage.RegisterUnloadCleanup("instantprompts_stop", NAmanage.InstantProximityPromptsDisable)
	NAmanage.RegisterUnloadCleanup("fastprompts_restore", NAmanage.FastProximityPromptsDisable)

	do
		const uis = Services.UserInputService
		const gui = SafeGetService("GuiService")
		const state = { active = false; focus = true; prompts = NAmanage.ensureWeakKeyTable(); keys = {} }
		NAStuff.holdInteract = state

		const function release(pp, rec, pause)
			const holding = rec.holding
			rec.holding, rec.kind, rec.key = false, nil, nil
			rec.ready = os.clock() + (pause or 0)
			if holding then pcall(pp.InputHoldEnd, pp) end
		end

		const function clear()
			NAlib.disconnect("holdinteract_step")
			table.clear(state.keys)
			for pp, rec in state.prompts do
				if rec.holding then release(pp, rec) end
			end
		end

		NAmanage.HoldInteractDisable = function()
			state.active = false
			NAlib.disconnect("holdinteract")
			clear()
		end

		const function blocked()
			return not state.focus or uis:GetFocusedTextBox() ~= nil or gui.MenuIsOpen
		end

		const function mark(input, down)
			const kind = input.UserInputType
			if kind ~= Enum.UserInputType.Keyboard and kind.Name:sub(1, 7) ~= "Gamepad" then return false end
			const key = input.KeyCode
			if key == Enum.KeyCode.Unknown then return false end
			local keys = state.keys[kind]
			if down then
				if not keys then keys = {}; state.keys[kind] = keys end
				keys[key] = true
			elseif keys then
				keys[key] = nil
				if not next(keys) then state.keys[kind] = nil end
			end
			return true
		end

		const function seed()
			if blocked() then return end
			for _, input in uis:GetKeysPressed() do mark(input, true) end
			for _, pad in uis:GetConnectedGamepads() do
				for _, input in uis:GetGamepadState(pad) do
					if uis:IsGamepadButtonDown(pad, input.KeyCode) then mark(input, true) end
				end
			end
		end

		const function held(pp)
			for kind, keys in state.keys do
				const keyboard = kind == Enum.UserInputType.Keyboard
				const key = keyboard and pp.KeyboardKeyCode or pp.GamepadKeyCode
				if key ~= Enum.KeyCode.Unknown and keys[key] then
					if keyboard and uis:IsKeyDown(key) or not keyboard and uis:IsGamepadButtonDown(kind, key) then
						return kind, key
					end
					keys[key] = nil
				end
			end
			return nil
		end

		const function visible(pp)
			if not pps.Enabled or not pp.Parent or not pp.Enabled or not pp:IsDescendantOf(Services.Workspace) then return false end
			const camera = Services.Workspace.CurrentCamera
			const pos = NAmanage.PromptWorldPosition(pp)
			const char = rPlayer.Character
			const root = char and (char:FindFirstChild("HumanoidRootPart") or char.PrimaryPart)
			if not camera or not pos or not root or (root.Position - pos).Magnitude > pp.MaxActivationDistance + 0.01 then return false end
			const point, shown = camera:WorldToViewportPoint(pos)
			return shown and point.Z > 0
		end

		const function track(pp)
			local rec = state.prompts[pp]
			if not rec then
				rec = { holding = false; ready = 0 }
				state.prompts[pp] = rec
			end
			return rec
		end

		const function step()
			if not state.active or blocked() then clear(); return end
			const now = os.clock()
			local busy = false
			for pp, rec in state.prompts do
				if not pp.Parent or not pp:IsDescendantOf(Services.Workspace) then
					state.prompts[pp] = nil
					release(pp, rec)
					continue
				end
				const kind, key = held(pp)
				if kind then busy = true end
				if not kind or not visible(pp) then
					if rec.holding then release(pp, rec) end
					continue
				end
				if rec.holding and (rec.kind ~= kind or rec.key ~= key) then release(pp, rec) end
				if not rec.holding and now >= rec.ready and not NAmanage.IsAutomaticPrompt(pp) then
					rec.holding, rec.kind, rec.key = true, kind, key
					if not pcall(pp.InputHoldBegin, pp) then release(pp, rec, 0.25) end
				end
			end
			if not busy then NAlib.disconnect("holdinteract_step") end
		end

		const function wake()
			if not state.active or blocked() or not next(state.keys) or NAlib.isConnected("holdinteract_step") then return end
			local elapsed = 0
			NAlib.connect("holdinteract_step", Services.RunService.Heartbeat:Connect(function(dt)
				elapsed += dt
				if elapsed < 0.03 then return end
				elapsed = 0
				step()
			end))
		end

		NAlib.connect("holdinteract_shown", pps.PromptShown:Connect(function(pp)
			track(pp)
			wake()
		end))
		NAlib.connect("holdinteract_shown", pps.PromptHidden:Connect(function(pp)
			const rec = state.prompts[pp]
			state.prompts[pp] = nil
			if rec then release(pp, rec) end
		end))

		NAmanage.RegisterUnloadCleanup("holdinteract_stop", function()
			NAmanage.HoldInteractDisable()
			NAlib.disconnect("holdinteract_shown")
			table.clear(state.prompts)
		end)

		cmd.register({
			name = "holdinteract",
			aliases = { "holdautointeract", "holdprompts", "holdpp" },
			description = "Hold a prompt's assigned key or gamepad button to keep interacting with visible prompts, respecting their hold duration",
			usage = "holdinteract (holdautointeract,holdprompts,holdpp)",
			callback = function()
				NAmanage.HoldInteractDisable()
				state.active, state.focus = true, true

				NAlib.connect("holdinteract", uis.InputBegan:Connect(function(input)
					if not blocked() and mark(input, true) then wake() end
				end))
				NAlib.connect("holdinteract", uis.InputEnded:Connect(function(input)
					if mark(input, false) then step() end
				end))
				NAlib.connect("holdinteract", uis.TextBoxFocused:Connect(clear))
				NAlib.connect("holdinteract", uis.WindowFocusReleased:Connect(function()
					state.focus = false
					clear()
				end))
				NAlib.connect("holdinteract", uis.WindowFocused:Connect(function() state.focus = true end))
				NAlib.connect("holdinteract", gui.MenuOpened:Connect(clear))
				NAlib.connect("holdinteract", rPlayer.CharacterRemoving:Connect(clear))
				NAlib.connect("holdinteract", pps:GetPropertyChangedSignal("Enabled"):Connect(function()
					if not pps.Enabled then clear() end
				end))
				NAlib.connect("holdinteract", pps.PromptButtonHoldBegan:Connect(function(pp, player)
					if not state.active or blocked() or (player and player ~= rPlayer) or NAmanage.IsAutomaticPrompt(pp) then return end
					local kind, key = held(pp)
					if not kind then seed(); kind, key = held(pp) end
					if not kind then return end
					const rec = track(pp)
					rec.holding, rec.kind, rec.key = true, kind, key
					wake()
				end))
				NAlib.connect("holdinteract", pps.PromptButtonHoldEnded:Connect(function(pp, player)
					const rec = state.prompts[pp]
					if not state.active or not rec or not rec.holding or (player and player ~= rPlayer) then return end
					rec.holding, rec.kind, rec.key = false, nil, nil
					rec.ready = os.clock() + 0.15
					wake()
				end))
				NAlib.connect("holdinteract", pps.PromptTriggered:Connect(function(pp, player)
					if not state.active or blocked() or (player and player ~= rPlayer) then return end
					if not held(pp) then seed() end
					if not held(pp) then return end
					const rec = track(pp)
					rec.holding = true
					release(pp, rec, 0.15)
					wake()
				end))

				seed()
				wake()
				DebugNotif("Hold a prompt's key to keep interacting; release it to stop",2)
			end,
		})

		cmd.register({
			name = "unholdinteract",
			aliases = { "unholdautointeract", "unholdprompts", "unholdpp" },
			description = "Stops hold auto interact and cancels active prompt holds",
			usage = "unholdinteract (unholdautointeract,unholdprompts,unholdpp)",
			callback = function()
				NAmanage.HoldInteractDisable()
			end,
		})
	end

	cmd.register({
		name = "instantproximityprompts",
		aliases = { "instantpp", "ipp" },
		description = "Fires a proximity prompt as soon as you begin holding it",
		usage = "instantproximityprompts (instantpp,ipp)",
		callback = function()
			if type(fireproximityprompt) ~= "function" then return DoNotif("Your executor does not support fireproximityprompt",3) end
			NAmanage.InstantProximityPromptsDisable()
			const state = NAStuff.instantProximityPrompts
			state.active = true
			const epoch = state.epoch
			NAlib.connect("instantpp", pps.PromptButtonHoldBegan:Connect(function(pp, player)
				if not state.active or state.epoch ~= epoch or (player and player ~= rPlayer) or NAmanage.IsAutomaticPrompt(pp) then return end
				NAmanage.FirePromptOnce(pp, function() return state.active and state.epoch == epoch end)
				NAmanage.MultiPromptFire(pp)
			end))
		end,
	})

	cmd.register({
		name = "uninstantproximityprompts",
		aliases = { "uninstantpp", "unipp" },
		description = "Stops firing prompts when a hold begins",
		usage = "uninstantproximityprompts (uninstantpp,unipp)",
		callback = function()
			NAmanage.InstantProximityPromptsDisable()
		end,
	})

	cmd.register({
		name = "multiprompts",
		aliases = { "multiproximityprompts", "multipp" },
		description = "Trigger one prompt to fire the other visible prompts in your viewport",
		usage = "multiprompts (multiproximityprompts,multipp)",
		callback = function()
			if type(fireproximityprompt) ~= "function" then return DoNotif("Your executor does not support fireproximityprompt",3) end
			NAmanage.MultiPromptsDisable()
			const state = NAStuff.multiProximityPrompts
			NAlib.connect("multiprompts_events", pps.PromptShown:Connect(function(pp) state.shown[pp] = true end))
			NAlib.connect("multiprompts_events", pps.PromptHidden:Connect(function(pp) state.shown[pp] = false end))
			NAlib.connect("multiprompts_events", pps.PromptTriggered:Connect(function(pp, player)
				if (player and player ~= rPlayer) or NAmanage.IsAutomaticPrompt(pp) then return end
				NAmanage.MultiPromptFire(pp)
			end))
			NAmanage.PromptPropertyStart(state, "multiprompts_exclusivity", "Exclusivity", function() return Enum.ProximityPromptExclusivity.AlwaysShow end)
			DebugNotif("Trigger one prompt to fire the other visible prompts",2)
		end,
	})

	cmd.register({
		name = "unmultiprompts",
		aliases = { "unmultiproximityprompts", "unmultipp" },
		description = "Stops firing multiple prompts and restores prompt exclusivity",
		usage = "unmultiprompts (unmultiproximityprompts,unmultipp)",
		callback = function()
			NAmanage.MultiPromptsDisable()
		end,
	})

	cmd.register({
		name = "promptwalls",
		aliases = { "proximitypromptwalls", "ppwalls" },
		description = "Keeps proximity prompt line-of-sight checks disabled within interaction range",
		usage = "promptwalls (proximitypromptwalls,ppwalls)",
		callback = function()
			NAmanage.PromptPropertyStart(NAStuff.ppWalls, "ppwalls", "RequiresLineOfSight", function() return false end)
			DebugNotif("Prompt wall checks disabled within interaction range",2)
		end,
	})

	cmd.register({
		name = "unpromptwalls",
		aliases = { "unproximitypromptwalls", "unppwalls" },
		description = "Restores the original proximity prompt wall checks",
		usage = "unpromptwalls (unproximitypromptwalls,unppwalls)",
		callback = function()
			NAmanage.PromptWallsDisable()
			DebugNotif("Prompt wall checks restored",2)
		end,
	})

	cmd.register({
		name = "promptdistance",
		aliases = { "proximitypromptdistance", "ppdistance", "pprange" },
		description = "Multiplies prompt activation distances and keeps the range applied; default 2x",
		usage = "promptdistance [multiplier] (proximitypromptdistance,ppdistance,pprange)",
		callback = function(...)
			const raw = (...)
			const multiplier = raw == nil and 2 or tonumber(raw)
			if not multiplier or multiplier ~= multiplier or multiplier <= 0 or multiplier == math.huge then
				return DoNotif("Prompt distance multiplier must be a finite number greater than 0",3)
			end
			const state = NAStuff.ppDistance
			state.multiplier = multiplier
			NAmanage.PromptPropertyStart(state, "ppdistance", "MaxActivationDistance", function(base) return math.min(base * multiplier, 1000000) end)
			DebugNotif("Prompt distance multiplier: "..tostring(multiplier).."x",2)
		end,
	})

	cmd.register({
		name = "unpromptdistance",
		aliases = { "unproximitypromptdistance", "unppdistance", "unpprange" },
		description = "Restores the original proximity prompt activation distances",
		usage = "unpromptdistance (unproximitypromptdistance,unppdistance,unpprange)",
		callback = function()
			NAmanage.PromptDistanceDisable()
		end,
	})
end

cmd.register({
	name = "fastprompts",
	aliases = { "fastproximityprompts", "fastpp" },
	description = "Makes proximity prompts use the specified speed multiplier, defaulting to 2x",
