				for _,obj in part:GetChildren() do
					if obj:IsA("AlignPosition") or obj:IsA("Torque") or obj:IsA("Attachment") then obj:Destroy() end
				end
			end
		end

		DebugNotif("Blackhole follow disabled.")
	end,
})

