NAmanage.HB_Defaults=function()
	return {
		size = 10;
		transparency = 0.9;
		color = { R = 0; G = 0; B = 0 };
		material = "Neon";
		noCollide = true;
		massless = true;
	}
end

NAmanage.HB_Coerce=function(opts)
	const base = NAmanage.HB_Defaults()
	if type(opts) ~= "table" then
		return base
	end
	if typeof(opts.color) == "Color3" then
		base.color = { R = opts.color.R; G = opts.color.G; B = opts.color.B }
	elseif type(opts.color) == "table" then
		base.color = {
			R = math.clamp(opts.color.R or opts.color.r or opts.color[1] or base.color.R, 0, 1);
			G = math.clamp(opts.color.G or opts.color.g or opts.color[2] or base.color.G, 0, 1);
			B = math.clamp(opts.color.B or opts.color.b or opts.color[3] or base.color.B, 0, 1);
		}
	end
	base.size = math.clamp(tonumber(opts.size) or base.size, 0.1, 200)
	base.transparency = math.clamp(tonumber(opts.transparency) or base.transparency, 0, 1)
	if opts.material ~= nil then
		base.material = NAmanage.HB_ResolveMaterial(opts.material)
	end
	base.noCollide = opts.noCollide ~= false
	base.massless = opts.massless ~= false
	return base
end

NAmanage.HB_ColorFromOpt=function(opt)
	if typeof(opt) == "Color3" then
		return opt
	end
	if type(opt) == "table" then
		const r = tonumber(opt.R or opt.r or opt[1])
		const g = tonumber(opt.G or opt.g or opt[2])
		const b = tonumber(opt.B or opt.b or opt[3])
		if r and g and b then
			return Color3.new(math.clamp(r, 0, 1), math.clamp(g, 0, 1), math.clamp(b, 0, 1))
		end
	end
	return BrickColor.new("Really black").Color
end

NAmanage.HB_ResolveMaterial=function(matName)
	const items = Enum.Material:GetEnumItems()
	const defaultMat = "Neon"
	if matName == nil then return defaultMat end
	const input = tostring(matName)
	if input == "" then return defaultMat end
	const lowerInput = input:lower()

	local bestName = nil
	local bestScore = math.huge

	const function score(name)
		const lname = name:lower()
		if lname == lowerInput then return 0 end
		if lname:sub(1, #lowerInput) == lowerInput then return 1 end
		if lname:find(lowerInput, 1, true) then return 2 end
		return 3
	end

	for _, item in items do
		const s = score(item.Name)
		if s < bestScore or (s == bestScore and #item.Name < #(bestName or item.Name)) then
			bestScore = s
			bestName = item.Name
			if s == 0 then
				break
			end
		end
	end

	return bestName or defaultMat
end

NAStuff.HitboxOptions = NAmanage.HB_Coerce(NAStuff.HitboxOptions or (NAmanage.NASettingsGet and NAmanage.NASettingsGet("hitboxOptions")))

function NAmanage.GetHitboxOpts()
	NAStuff.HitboxOptions = NAmanage.HB_Coerce(NAStuff.HitboxOptions)
	return NAStuff.HitboxOptions
end

function NAmanage.SetHitboxOpt(key, value)
	local opts = NAmanage.HB_Coerce(NAStuff.HitboxOptions)
	opts[key] = value
	opts = NAmanage.HB_Coerce(opts)
	NAStuff.HitboxOptions = opts
	if NAmanage.NASettingsSet then
		pcall(NAmanage.NASettingsSet, "hitboxOptions", opts)
	end
	if NAmanage.HitboxUpdateActive then
		NAmanage.HitboxUpdateActive(opts)
	end
	return opts
end

function NAmanage.HitboxUpdateActive(newOpts)
	const opts = NAmanage.HB_Coerce(newOpts or NAmanage.GetHitboxOpts())
	const function rescan(D)
		if not (D and D.ps) then return end
		for key,_ in D.ps do
			local ch = nil
			if typeof(key) == "Instance" and key:IsA("Player") then
				ch = getPlrChar(key)
			elseif typeof(key) == "Instance" and key:IsA("Model") then
				ch = key
			end
			if ch and ch.Parent then
				for _,bp in ch:GetChildren() do
					if bp:IsA("BasePart") then
						D.ps[key] = D.ps[key] or {}
						D.ps[key][bp] = true
					end
				end
			end
		end
	end
	const function updateCfg(D)
		if not (D and D.cfg) then return end
		rescan(D)
		D.cfg.sz = Vector3.new(opts.size, opts.size, opts.size)
		D.cfg.tr = opts.transparency
		D.cfg.bc = BrickColor.new(NAmanage.HB_ColorFromOpt(opts.color))
		D.cfg.mat = Enum.Material[NAmanage.HB_ResolveMaterial(opts.material or "Neon")] or Enum.Material.Neon
		D.cfg.noCollide = opts.noCollide ~= false
		D.cfg.massless = opts.massless ~= false
		const function match(bp)
			if not bp then return false end
			if D.cfg.limb == "All" then return true end
			return Lower(bp.Name) == D.cfg.limbL
		end
		for key, set in D.ps or {} do
			for bp,_ in set do
				if bp and bp.Parent and match(bp) then
					D.og[key] = D.og[key] or {}
					if not D.og[key][bp] then
						D.og[key][bp] = {
							Size=bp.Size, Transparency=bp.Transparency, BrickColor=bp.BrickColor,
							Material=bp.Material, CanCollide=bp.CanCollide, Massless=bp.Massless
						}
					end
					if bp.Size ~= D.cfg.sz then bp.Size = D.cfg.sz end
					if bp.Transparency ~= D.cfg.tr then bp.Transparency = D.cfg.tr end
					if bp.BrickColor ~= D.cfg.bc then bp.BrickColor = D.cfg.bc end
					if bp.Material ~= D.cfg.mat then bp.Material = D.cfg.mat end
					if D.cfg.noCollide then
						if bp.CanCollide then bp.CanCollide = false end
					else
						const og = D.og[key][bp]
						if og and bp.CanCollide ~= og.CanCollide then
							bp.CanCollide = og.CanCollide
						end
					end
					if D.cfg.massless then
						if not bp.Massless then bp.Massless = true end
					else
						const og = D.og[key][bp]
						if og and bp.Massless ~= og.Massless then
							bp.Massless = og.Massless
						end
					end
				end
			end
		end
	end
	updateCfg(NAStuff.HB and NAStuff.HB.P)
	updateCfg(NAStuff.HB and NAStuff.HB.N)
end

cmd.register({
	name = "hitbox",
	aliases = { "hbox" },
	description = "Resize a selected body part or All",
	usage = "hitbox <player|npc:filter> [size] [limb]",
	requiresArguments = true,
	callback = function(pArg, sArg, ...)
		NAStuff.HB = NAStuff.HB or {};
		NAStuff.HB.P = NAStuff.HB.P or {
			ps = {},
			og = {},
			ca = {},
			da = {},
			ac = {},
			tc = {},
			addConn = nil,
			remConn = nil,
			run = nil,
			cfg = nil
		};
		NAStuff.HB.N = NAStuff.HB.N or {
			ps = {},
			og = {},
			md = {},
			ac = {},
			wc = nil,
			run = nil,
			cfg = nil
		};
		const targets = getPlr(pArg);
		const hbOpts = NAmanage.GetHitboxOpts();
		const n = tonumber(sArg) or hbOpts.size or 10;
		const argL = Lower(pArg or "");
		const npc = argL == "npc";
		const selectorMode = ({
			all = true,
			others = true,
			nonteam = true,
			noteam = true,
			noteams = true,
			nonteams = true,
			notteam = true,
			enemies = true,
			enemy = true,
			team = true,
			allies = true,
			ally = true,
		})[argL] and argL or nil;
		const glb = selectorMode == "all" or selectorMode == "others";
		const allowEmpty = npc or selectorMode ~= nil;
		if #targets == 0 and (not allowEmpty) then
			DoNotif("No targets found", 2);
			return;
		end;
		const defaultTransparency = math.clamp(tonumber(hbOpts.transparency) or 0.9, 0, 1);
		const defaultColor = NAmanage.HB_ColorFromOpt(hbOpts.color);
		const defaultMaterial = Enum.Material[NAmanage.HB_ResolveMaterial(hbOpts.material or "Neon")] or Enum.Material.Neon;
		const defaultNoCollide = hbOpts.noCollide ~= false;
		const defaultMassless = hbOpts.massless ~= false;
		const function GetChar(t)
			if typeof(t) == "Instance" and t:IsA("Player") then
				return getPlrChar(t);
			elseif typeof(t) == "Instance" and t:IsA("Model") then
				return t;
			end;
		end;
		const limbArg = Concat({...}, " ");
		const partSet = {
			All = true
		};
		if limbArg ~= "" then partSet[limbArg] = true end;
		if #targets == 0 then
			const defaults = {
				"Head",
				"UpperTorso",
				"LowerTorso",
				"Torso",
				"LeftUpperArm",
				"LeftLowerArm",
				"LeftHand",
				"RightUpperArm",
				"RightLowerArm",
				"RightHand",
				"LeftUpperLeg",
				"LeftLowerLeg",
				"LeftFoot",
				"RightUpperLeg",
				"RightLowerLeg",
				"RightFoot"
			};
			for _, limb in defaults do
				partSet[limb] = true;
			end;
		end;
		for _, t in targets do
			const c = GetChar(t);
			if c then
				for _, p in c:GetChildren() do
					if p:IsA("BasePart") then
						partSet[p.Name] = true;
					end;
				end;
			end;
		end;
		const btns = {};
		for limb, _ in partSet do
			Insert(btns, {
				Text = limb,
				Callback = function()
					const sz = Vector3.new(n, n, n);
					const bc = BrickColor.new(defaultColor);
					const mat = defaultMaterial;
					const limbL = Lower(limb);
					const isAll = limb == "All";
					const function MatchBp(bp)
						if isAll then
							return true;
						end;
						return Lower(bp.Name) == limbL;
					end;
					const function Cache(D, key, bp)
						D.og[key] = D.og[key] or {};
						if not D.og[key][bp] then
							D.og[key][bp] = {
								Size = bp.Size,
								Transparency = bp.Transparency,
								BrickColor = bp.BrickColor,
								Material = bp.Material,
								CanCollide = bp.CanCollide,
								Massless = bp.Massless
							};
						end;
						if not NAmanage.GetAttr(bp, "NAHB_HasOrig") then
							const c = bp.BrickColor.Color;
							NAmanage.SetAttr(bp, "NAHB_HasOrig", true);
							NAmanage.SetAttr(bp, "NAHB_OSizeX", bp.Size.X);
							NAmanage.SetAttr(bp, "NAHB_OSizeY", bp.Size.Y);
							NAmanage.SetAttr(bp, "NAHB_OSizeZ", bp.Size.Z);
							NAmanage.SetAttr(bp, "NAHB_OTransparency", bp.Transparency);
							NAmanage.SetAttr(bp, "NAHB_OColorR", c.R);
							NAmanage.SetAttr(bp, "NAHB_OColorG", c.G);
							NAmanage.SetAttr(bp, "NAHB_OColorB", c.B);
							NAmanage.SetAttr(bp, "NAHB_OMaterial", bp.Material.Name);
							NAmanage.SetAttr(bp, "NAHB_OCanCollide", bp.CanCollide);
							NAmanage.SetAttr(bp, "NAHB_OMassless", bp.Massless);
						end;
					end;
					const function ApplyBp(D, key, bp)
						Cache(D, key, bp);
						const og = D.og[key] and D.og[key][bp] or nil;
						if bp.Size ~= D.cfg.sz then
							bp.Size = D.cfg.sz;
						end;
						if bp.Transparency ~= D.cfg.tr then
							bp.Transparency = D.cfg.tr;
						end;
						if bp.BrickColor ~= D.cfg.bc then
							bp.BrickColor = D.cfg.bc;
						end;
						if bp.Material ~= D.cfg.mat then
							bp.Material = D.cfg.mat;
						end;
						if D.cfg.noCollide then
							if bp.CanCollide then
								bp.CanCollide = false;
							end;
						elseif og and bp.CanCollide ~= og.CanCollide then
							bp.CanCollide = og.CanCollide;
						end;
						if D.cfg.massless then
							if not bp.Massless then
								bp.Massless = true;
							end;
						elseif og and bp.Massless ~= og.Massless then
							bp.Massless = og.Massless;
						end;
					end;
					if npc then
						const D = NAStuff.HB.N;
						if D.run then
							D.run:Disconnect();
							D.run = nil;
						end;
						NAlib.disconnect("hitbox_npc_loop");
						if D.wc then
							D.wc:Disconnect();
							D.wc = nil;
						end;
						for m, c in D.md do
							if c then
								c:Disconnect();
							end;
							D.md[m] = nil;
						end;
						for m, c in D.ac do
							if c then
								c:Disconnect();
							end;
							D.ac[m] = nil;
						end;
						for m, _ in D.ps do
							D.ps[m] = nil;
						end;
						D.cfg = {
							limb = limb,
							limbL = limbL,
							sz = sz,
							bc = bc,
							mat = mat,
							tr = defaultTransparency,
							noCollide = defaultNoCollide,
							massless = defaultMassless
						};
						const function Track(m, bp)
							if not (bp and bp.Parent) then
								return;
							end;
							if not bp:IsA("BasePart") then
								return;
							end;
							if not MatchBp(bp) then
								return;
							end;
							D.ps[m] = D.ps[m] or {};
							D.ps[m][bp] = true;
							ApplyBp(D, m, bp);
						end;
						const function Scan(m)
							if not (m and m.Parent) then
								return;
							end;
							for _, c in m:GetChildren() do
								if c:IsA("BasePart") then
									Track(m, c);
								end;
							end;
						end;
						const function Setup(m)
							if not (m and m.Parent) then
								return;
							end;
							if D.md[m] then
								D.md[m]:Disconnect();
							end;
							D.md[m] = NAmanage.descAdd(m, function(inst)
								if inst and inst:IsA("BasePart") then
									Track(m, inst);
								end;
							end, function(inst)
								return inst and inst:IsA("BasePart")
							end);
							if D.ac[m] then
								D.ac[m]:Disconnect();
							end;
							D.ac[m] = m.AncestryChanged:Connect(function(_, parent)
								if not D.cfg then
									return;
								end;
								if parent and Services.Workspace and m:IsDescendantOf(Services.Workspace) then
									Defer(function()
										Scan(m);
									end);
								end;
							end);
							Scan(m);
						end;
						const function IsNPC(inst)
							if inst and inst:IsA("Model") and CheckIfNPC(inst) then
								return inst;
							end;
							const m = inst and inst:FindFirstAncestorWhichIsA("Model") or nil;
							if m and CheckIfNPC(m) then
								return m;
							end;
							return nil;
						end;
						for _, t in targets do
							const m = GetChar(t);
							if m then
								Setup(m);
							end;
						end;
						D.wc = NAmanage.wsAdd(function(inst)
							const m = IsNPC(inst);
							if m then
								Defer(function()
									if not D.md[m] then
										Setup(m);
									end;
								end);
							end;
						end);
						local acc = 0;
						local acc2 = 0;
						D.run = NAlib.reconnect("hitbox_npc_loop", Services.RunService.Heartbeat:Connect(function(dt)
							acc += dt;
							acc2 += dt;
							if acc >= 0.12 then
								acc = 0;
								for m, c in D.md do
									if not (m and m.Parent) then
										if c then
											c:Disconnect();
										end;
										D.md[m] = nil;
										if D.ac[m] then
											D.ac[m]:Disconnect();
											D.ac[m] = nil;
										end;
										D.ps[m] = nil;
										D.og[m] = nil;
									end;
								end;
								for m, set in D.ps do
									if not (m and m.Parent) then
										D.ps[m] = nil;
										D.og[m] = nil;
										if D.md[m] then
											D.md[m]:Disconnect();
											D.md[m] = nil;
										end;
										if D.ac[m] then
											D.ac[m]:Disconnect();
											D.ac[m] = nil;
										end;
									else
										for bp, _ in set do
											if not (bp and bp.Parent) then
												set[bp] = nil;
											elseif MatchBp(bp) then
												ApplyBp(D, m, bp);
											end;
										end;
									end;
								end;
							end;
							if acc2 >= 0.35 then
								acc2 = 0;
								for _, ch in Services.Workspace:GetChildren() do
									if ch:IsA("Model") and CheckIfNPC(ch) and (not D.md[ch]) then
										Setup(ch);
									end;
								end;
							end;
						end));
					else
						const D = NAStuff.HB.P;
						if D.run then
							D.run:Disconnect();
							D.run = nil;
						end;
						NAlib.disconnect("hitbox_player_loop");
						if D.addConn then
							D.addConn:Disconnect();
							D.addConn = nil;
						end;
						if D.remConn then
							D.remConn:Disconnect();
							D.remConn = nil;
						end;
						for k, c in D.ca do
							if c then
								c:Disconnect();
							end;
							D.ca[k] = nil;
						end;
						for k, c in D.da do
							if c then
								c:Disconnect();
							end;
							D.da[k] = nil;
						end;
						for k, c in D.ac do
							if c then
								c:Disconnect();
							end;
							D.ac[k] = nil;
						end;
						D.tc = D.tc or {};
						for k, c in D.tc do
							if c then
								c:Disconnect();
							end;
							D.tc[k] = nil;
						end;
						for k, _ in D.ps do
							D.ps[k] = nil;
						end;
						D.cfg = {
							limb = limb,
							limbL = limbL,
							sz = sz,
							bc = bc,
							mat = mat,
							tr = defaultTransparency,
							noCollide = defaultNoCollide,
							massless = defaultMassless
						};
						D.tc = D.tc or {};
						D.selectorMode = selectorMode;
						D.targetSet = {};
						const function ModeAllows(plr)
							if not (typeof(plr) == "Instance" and plr:IsA("Player")) then
								return false;
							end;
							if selectorMode == "all" then
								return true;
							elseif selectorMode == "others" then
								return plr ~= Services.Players.LocalPlayer;
							elseif selectorMode == "nonteam" or selectorMode == "noteam" or selectorMode == "noteams" or selectorMode == "nonteams" or selectorMode == "notteam" or selectorMode == "enemies" or selectorMode == "enemy" then
								return NAmanage.PlayerArgNonTeam(plr);
							elseif selectorMode == "team" or selectorMode == "allies" or selectorMode == "ally" then
								return NAmanage.PlayerArgSameTeam(plr);
							end;
							return D.targetSet[plr] == true;
						end;
						const function Track(k, bp)
							if not (bp and bp.Parent) then
								return;
							end;
							if not bp:IsA("BasePart") then
								return;
							end;
							if not MatchBp(bp) then
								return;
							end;
							D.ps[k] = D.ps[k] or {};
							D.ps[k][bp] = true;
							ApplyBp(D, k, bp);
						end;
						const function Scan(k, ch)
							if not (ch and ch.Parent) then
								return;
							end;
							for _, c in ch:GetChildren() do
								if c:IsA("BasePart") then
									Track(k, c);
								end;
							end;
						end;
						const function SetupChar(k, ch)
							if D.da[k] then
								D.da[k]:Disconnect();
							end;
							D.da[k] = NAmanage.descAdd(ch, function(inst)
								if inst and inst:IsA("BasePart") then
									Track(k, inst);
								end;
							end, function(inst)
								return inst and inst:IsA("BasePart")
							end);
							if D.ac[k] then
								D.ac[k]:Disconnect();
							end;
							D.ac[k] = ch.AncestryChanged:Connect(function(_, parent)
								if not D.cfg then
									return;
								end;
								if parent and Services.Workspace and ch:IsDescendantOf(Services.Workspace) then
									Defer(function()
										const cc = GetChar(k);
										if cc then
											Scan(k, cc);
										end;
									end);
								end;
							end);
							Scan(k, ch);
						end;
						const function SetupKey(k)
							if not (k and typeof(k) == "Instance") then
								return;
							end;
							D.targetSet[k] = true;
							const ch = GetChar(k);
							if ch then
								SetupChar(k, ch);
							end;
							if typeof(k) == "Instance" and k:IsA("Player") and k.CharacterAdded then
								if D.ca[k] then
									D.ca[k]:Disconnect();
								end;
								D.ca[k] = k.CharacterAdded:Connect(function(c)
									Defer(function()
										if c and ModeAllows(k) then
											SetupChar(k, c);
										end;
									end);
								end);
								if D.tc[k] then
									D.tc[k]:Disconnect();
								end;
								D.tc[k] = k:GetPropertyChangedSignal("Team"):Connect(function()
									if ModeAllows(k) then
										const cc = GetChar(k);
										if cc then
											SetupChar(k, cc);
										end;
									end;
								end);
							end;
							Defer(function()
								const cc = GetChar(k);
								if cc and ModeAllows(k) then
									Scan(k, cc);
								end;
							end);
						end;
						for _, t in targets do
							if selectorMode == nil or ModeAllows(t) then
								SetupKey(t);
							end;
						end;
						if selectorMode then
							for _, plr in __lt.cm("Players", "GetPlayers") do
								if ModeAllows(plr) and not D.ca[plr] then
									SetupKey(plr);
								end;
							end;
						end;
						if selectorMode then
							D.addConn = Services.Players.PlayerAdded:Connect(function(plr)
								if ModeAllows(plr) then
									SetupKey(plr);
								end;
							end);
							D.remConn = Services.Players.PlayerRemoving:Connect(function(plr)
								if D.ca[plr] then
									D.ca[plr]:Disconnect();
									D.ca[plr] = nil;
								end;
								if D.da[plr] then
									D.da[plr]:Disconnect();
									D.da[plr] = nil;
								end;
								if D.ac[plr] then
									D.ac[plr]:Disconnect();
									D.ac[plr] = nil;
								end;
								if D.tc and D.tc[plr] then
									D.tc[plr]:Disconnect();
									D.tc[plr] = nil;
								end;
								D.ps[plr] = nil;
								D.og[plr] = nil;
							end);
						end;
						local acc = 0;
						D.run = NAlib.reconnect("hitbox_player_loop", Services.RunService.Heartbeat:Connect(function(dt)
							acc += dt;
							if acc < 0.12 then
								return;
							end;
							acc = 0;
							for k, set in D.ps do
								const ch = GetChar(k);
								if not (ch and ch.Parent) then
									D.ps[k] = nil;
								else
									for bp, _ in set do
										if not (bp and bp.Parent) then
											set[bp] = nil;
										elseif MatchBp(bp) then
											ApplyBp(D, k, bp);
										end;
									end;
								end;
							end;
							if selectorMode then
								for _, plr in __lt.cm("Players", "GetPlayers") do
									if ModeAllows(plr) and not D.ca[plr] then
										SetupKey(plr);
									end;
								end;
							end;
						end));
					end;
				end
			});
		end;
		NAmanage.RunPicker({
			Title = "Hitbox Menu",
			Description = "Choose limb to resize",
			Buttons = btns
		}, limbArg);
	end,
});

cmd.register({
	name = "unhitbox",
	aliases = { "unhbox" },
	description = "",
	usage = "unhitbox <player|npc:filter>",
	requiresArguments = true,
	callback = function(pArg)
		NAStuff.HB = NAStuff.HB or {}
		NAStuff.HB.P = NAStuff.HB.P or {
			ps = {},
			og = {},
			ca = {},
			da = {},
			ac = {},
			tc = {},
			addConn = nil,
			remConn = nil,
			run = nil,
			cfg = nil
		}
		NAStuff.HB.N = NAStuff.HB.N or {
			ps = {},
			og = {},
			md = {},
			ac = {},
			wc = nil,
			run = nil,
			cfg = nil
		}

		const argL = pArg and Lower(pArg) or ""
		const targets = getPlr(pArg)
		const npc = argL == "npc"
		const glb = argL == "" or argL == "all" or argL == "others"
		const allowEmpty = npc or glb

		if #targets == 0 and not allowEmpty then
			DoNotif("No targets found", 2)
			return
		end

		const function RestorePart(bp, pr)
			if not (bp and bp.Parent) then
				return
			end

			const sx = NAmanage.GetAttr(bp, "NAHB_OSizeX")
			const sy = NAmanage.GetAttr(bp, "NAHB_OSizeY")
			const sz = NAmanage.GetAttr(bp, "NAHB_OSizeZ")
			if sx and sy and sz then
				bp.Size = Vector3.new(sx, sy, sz)
			elseif pr and pr.Size then
				bp.Size = pr.Size
			end

			const tr = NAmanage.GetAttr(bp, "NAHB_OTransparency")
			if tr ~= nil then
				bp.Transparency = tr
			elseif pr and pr.Transparency ~= nil then
				bp.Transparency = pr.Transparency
			end

			const cr = NAmanage.GetAttr(bp, "NAHB_OColorR")
			const cg = NAmanage.GetAttr(bp, "NAHB_OColorG")
			const cb = NAmanage.GetAttr(bp, "NAHB_OColorB")
			if cr and cg and cb then
				bp.BrickColor = BrickColor.new(Color3.new(cr, cg, cb))
			elseif pr and pr.BrickColor then
				bp.BrickColor = pr.BrickColor
			end

			const matName = NAmanage.GetAttr(bp, "NAHB_OMaterial")
			if matName then
				const em = Enum.Material[matName]
				if em then
					bp.Material = em
				end
			elseif pr and pr.Material then
				bp.Material = pr.Material
			end

			const cc = NAmanage.GetAttr(bp, "NAHB_OCanCollide")
			if cc ~= nil then
				bp.CanCollide = cc
			elseif pr and pr.CanCollide ~= nil then
				bp.CanCollide = pr.CanCollide
			end

			const ml = NAmanage.GetAttr(bp, "NAHB_OMassless")
			if ml ~= nil then
				bp.Massless = ml
			elseif pr and pr.Massless ~= nil then
				bp.Massless = pr.Massless
			end

			NAmanage.SetAttr(bp, "NAHB_HasOrig", nil)
			NAmanage.SetAttr(bp, "NAHB_OSizeX", nil)
			NAmanage.SetAttr(bp, "NAHB_OSizeY", nil)
			NAmanage.SetAttr(bp, "NAHB_OSizeZ", nil)
			NAmanage.SetAttr(bp, "NAHB_OTransparency", nil)
			NAmanage.SetAttr(bp, "NAHB_OColorR", nil)
			NAmanage.SetAttr(bp, "NAHB_OColorG", nil)
			NAmanage.SetAttr(bp, "NAHB_OColorB", nil)
			NAmanage.SetAttr(bp, "NAHB_OMaterial", nil)
			NAmanage.SetAttr(bp, "NAHB_OCanCollide", nil)
			NAmanage.SetAttr(bp, "NAHB_OMassless", nil)
		end

		const function RestoreMap(mp)
			for bp, pr in mp do
				RestorePart(bp, pr)
			end
		end

		const function GetChar(t)
			if typeof(t) == "Instance" and t:IsA("Player") then
				return getPlrChar(t)
			elseif typeof(t) == "Instance" and t:IsA("Model") then
				return t
			end
		end

		const function restoreEntryPlayer(D, k)
			const ch = GetChar(k)
			if ch and ch.Parent then
				const mp = D.og[k]
				for _, bp in NAmanage.QueryDescendants(ch, "BasePart") do
					const pr = mp and mp[bp] or nil
					RestorePart(bp, pr)
				end
			elseif D.og[k] then
				RestoreMap(D.og[k])
			end
			D.og[k] = nil
			D.ps[k] = nil
			if D.ca[k] then
				D.ca[k]:Disconnect()
				D.ca[k] = nil
			end
			if D.da[k] then
				D.da[k]:Disconnect()
				D.da[k] = nil
			end
			if D.ac[k] then
				D.ac[k]:Disconnect()
				D.ac[k] = nil
			end
			if type(D.tc) == "table" and D.tc[k] then
				D.tc[k]:Disconnect()
				D.tc[k] = nil
			end
		end

		const function restoreEntryNPC(D, k)
			const ch = GetChar(k)
			if ch and ch.Parent then
				const mp = D.og[k]
				for _, bp in NAmanage.QueryDescendants(ch, "BasePart") do
					const pr = mp and mp[bp] or nil
					RestorePart(bp, pr)
				end
			elseif D.og[k] then
				RestoreMap(D.og[k])
			end
			D.og[k] = nil
			D.ps[k] = nil
		end

		const function cleanupPlayers(D)
			local any = false
			for _ in D.ps do
				any = true
				break
			end
			if any then
				return
			end
			for _, c in D.ca do
				if c then
					c:Disconnect()
				end
			end
			for _, c in D.da do
				if c then
					c:Disconnect()
				end
			end
			for _, c in D.ac do
				if c then
					c:Disconnect()
				end
			end
			if type(D.tc) == "table" then
				for _, c in D.tc do
					if c then
						c:Disconnect()
					end
				end
			end
			D.ca = {}
			D.da = {}
			D.ac = {}
			D.tc = {}
			if D.addConn then
				D.addConn:Disconnect()
				D.addConn = nil
			end
			if D.remConn then
				D.remConn:Disconnect()
				D.remConn = nil
			end
			if D.run then
				D.run:Disconnect()
				D.run = nil
			end
			NAlib.disconnect("hitbox_player_loop")
			D.cfg = nil
		end

		const function cleanupNPC(D)
			local any = false
			for _ in D.ps do
				any = true
				break
			end
			if any then
				return
			end
			for _, c in D.md do
				if c then
					c:Disconnect()
				end
			end
			for _, c in D.ac do
				if c then
					c:Disconnect()
				end
			end
			D.md = {}
			D.ac = {}
			if D.wc then
				D.wc:Disconnect()
				D.wc = nil
			end
			if D.run then
				D.run:Disconnect()
				D.run = nil
			end
			NAlib.disconnect("hitbox_npc_loop")
			D.cfg = nil
		end

		if npc then
			const D = NAStuff.HB.N
			for k in D.og do
				restoreEntryNPC(D, k)
			end
			for _, t in targets do
				restoreEntryNPC(D, t)
			end
			cleanupNPC(D)
			return
		end

		const D = NAStuff.HB.P
		const lp = Services.Players.LocalPlayer

		if glb then
			if argL == "others" then
				for _, plr in __lt.cm("Players", "GetPlayers") do
					if plr ~= lp then
						restoreEntryPlayer(D, plr)
					end
				end
			else
				for _, plr in __lt.cm("Players", "GetPlayers") do
					restoreEntryPlayer(D, plr)
				end
			end
			cleanupPlayers(D)
			return
		end

		for _, t in targets do
			restoreEntryPlayer(D, t)
		end
		cleanupPlayers(D)
	end,
})

if type(NAStuff.PST) == "table" and type(NAStuff.PST.conn) == "table" then
	for _, cs in NAStuff.PST.conn do
		if type(cs) == "table" then
			for _, c in cs do
				if c then pcall(function() c:Disconnect() end) end
			end
		elseif cs then
			pcall(function() cs:Disconnect() end)
		end
	end
end

NAlib.disconnect("partsizeExact")
NAlib.disconnect("partsizeFind")
NAlib.disconnect("partsizeWatch")
NAlib.disconnect("partsizeFlush")
NAlib.disconnect("partsizeClean")

NAStuff.PST = {
	orig = {},
	sizeE = {},
	sizeP = {},
	queue = {},
	qSet = {},
	qHead = 1,
	qTail = 0,
}

NAmanage.PST_Defaults = function()
	return {
		transparency = 0.5,
		color = { R = 0, G = 0, B = 0 },
		material = "Neon",
		noCollide = true,
		massless = false,
		changeColor = false,
		changeMaterial = false,
	}
end

NAmanage.PST_ColorFromOpt = function(opt)
	if typeof(opt) == "Color3" then
		return opt
	end
	if type(opt) == "table" then
		const r = tonumber(opt.R or opt.r or opt[1])
		const g = tonumber(opt.G or opt.g or opt[2])
		const b = tonumber(opt.B or opt.b or opt[3])
		if r and g and b then
			return Color3.new(math.clamp(r, 0, 1), math.clamp(g, 0, 1), math.clamp(b, 0, 1))
		end
	end
	return BrickColor.new("Really black").Color
end

NAmanage.PST_ResolveMaterial = function(matName)
	if NAmanage.HB_ResolveMaterial then
		return NAmanage.HB_ResolveMaterial(matName)
	end
	const defaultMat = "Neon"
	if matName == nil then return defaultMat end
	const input = tostring(matName)
	if input == "" then return defaultMat end
	const lowerInput = input:lower()
	local bestName = nil
	local bestScore = math.huge
	const function score(name)
		const lname = name:lower()
		if lname == lowerInput then return 0 end
		if lname:sub(1, #lowerInput) == lowerInput then return 1 end
		if lname:find(lowerInput, 1, true) then return 2 end
		return 3
	end
	for _, item in Enum.Material:GetEnumItems() do
		const s = score(item.Name)
		if s < bestScore or (s == bestScore and #item.Name < #(bestName or item.Name)) then
			bestScore = s
			bestName = item.Name
			if s == 0 then
				break
			end
		end
	end
	return bestName or defaultMat
end

NAmanage.PST_Coerce = function(opts)
	const base = NAmanage.PST_Defaults()
	if type(opts) ~= "table" then
		return base
	end
	base.transparency = math.clamp(tonumber(opts.transparency) or base.transparency, 0, 1)
	if typeof(opts.color) == "Color3" then
		base.color = { R = opts.color.R, G = opts.color.G, B = opts.color.B }
	elseif type(opts.color) == "table" then
		base.color = {
			R = math.clamp(tonumber(opts.color.R or opts.color.r or opts.color[1]) or base.color.R, 0, 1),
			G = math.clamp(tonumber(opts.color.G or opts.color.g or opts.color[2]) or base.color.G, 0, 1),
			B = math.clamp(tonumber(opts.color.B or opts.color.b or opts.color[3]) or base.color.B, 0, 1),
		}
	end
	if opts.material ~= nil then
		base.material = NAmanage.PST_ResolveMaterial(opts.material)
	end
	base.noCollide = opts.noCollide ~= false
	base.massless = opts.massless == true
	base.changeColor = opts.changeColor == true
	base.changeMaterial = opts.changeMaterial == true
	return base
end

NAStuff.PartSizeOptions = NAmanage.PST_Coerce(NAStuff.PartSizeOptions or (NAmanage.NASettingsGet and NAmanage.NASettingsGet("partSizeOptions")))

NAmanage.GetPartSizeOpts = function()
	NAStuff.PartSizeOptions = NAmanage.PST_Coerce(NAStuff.PartSizeOptions)
	return NAStuff.PartSizeOptions
end

NAmanage.SetPartSizeOpt = function(key, value)
	local opts = NAmanage.PST_Coerce(NAStuff.PartSizeOptions)
	opts[key] = value
	opts = NAmanage.PST_Coerce(opts)
	NAStuff.PartSizeOptions = opts
	if NAmanage.NASettingsSet then
		pcall(NAmanage.NASettingsSet, "partSizeOptions", opts)
	end
	if NAmanage.PST_UpdateActive then
		NAmanage.PST_UpdateActive(opts)
	end
	return opts
end

do
	const pst = NAStuff.PST
	const world = Services.Workspace
	const maxWork = IsOnMobile and 24 or 48
	const maxScan = IsOnMobile and 90 or 180
	const timeWork = IsOnMobile and 0.001 or 0.002
	local scan, scanPos, scanAt = nil, 1, 0
	local opts = NAStuff.PartSizeOptions
	local color, mat

	const function setStyle(newOpts)
		opts = newOpts
		color = opts.changeColor and BrickColor.new(NAmanage.PST_ColorFromOpt(opts.color)).Color or nil
		mat = opts.changeMaterial and (Enum.Material[opts.material] or Enum.Material.Neon) or nil
	end
	setStyle(opts)

	const function active()
		return next(pst.sizeE) ~= nil or next(pst.sizeP) ~= nil
	end

	const function target(part)
		if next(pst.sizeE) then
			local obj = part
			while obj do
				const term = Lower(obj.Name)
				const size = pst.sizeE[term]
				if size then
					return size, "exact", term
				end
				obj = obj.Parent
			end
		end

		if next(pst.sizeP) then
			local obj = part
			while obj do
				const name = Lower(obj.Name)
				for term, size in pst.sizeP do
					if Find(name, term, 1, true) then
						return size, "partial", term
					end
				end
				obj = obj.Parent
			end
		end
	end

	const function queue(part)
		if pst.qSet[part] then return end
		pst.qSet[part] = true
		pst.qTail += 1
		pst.queue[pst.qTail] = part
	end

	const function restore(part, rec)
		pst.orig[part] = nil
		for _, conn in rec.conns do conn:Disconnect() end
		NACaller(function()
			if part.Size ~= rec.size then part.Size = rec.size end
			if part.Transparency ~= rec.alpha then part.Transparency = rec.alpha end
			if part.CanCollide ~= rec.collide then part.CanCollide = rec.collide end
			if part.Color ~= rec.color then part.Color = rec.color end
			if part.Material ~= rec.mat then part.Material = rec.mat end
			if part.Massless ~= rec.massless then part.Massless = rec.massless end
		end)
	end

	const function refresh(part, isScan)
		local rec = pst.orig[part]
		local size, kind, term
		if part.Parent and part:IsDescendantOf(world) then
			size, kind, term = target(part)
		end
		if not size then
			if rec then
				restore(part, rec)
				return true
			end
			return false
		end
		if isScan and rec and rec.request == size and rec.kind == kind and rec.term == term
			and rec.opts == opts and part.Size == rec.applied then
			return
		end
		if not rec then
			rec = {
				size = part.Size,
				alpha = part.Transparency,
				collide = part.CanCollide,
				color = part.Color,
				mat = part.Material,
				massless = part.Massless,
			}
			pst.orig[part] = rec
			rec.conns = {
				part:GetPropertyChangedSignal("Size"):Connect(function()
					if not rec.busy and part.Size ~= rec.applied then queue(part) end
				end),
				part:GetPropertyChangedSignal("Name"):Connect(function()
					queue(part)
				end),
				part.AncestryChanged:Connect(function()
					queue(part)
				end),
			}
		end

		const collide = rec.collide and not opts.noCollide
		const massless = rec.massless or opts.massless
		const wantCol = color or rec.color
		const wantMat = mat or rec.mat
		rec.kind, rec.term, rec.opts = kind, term, opts
		rec.busy = true
		NACaller(function()
			if part.CanCollide ~= collide then part.CanCollide = collide end
			if part.Massless ~= massless then part.Massless = massless end
			if part.Size ~= size and (rec.request ~= size or part.Size ~= rec.applied) then
				part.Size = size
			end
			if part.Transparency ~= opts.transparency then part.Transparency = opts.transparency end
			if part.Color ~= wantCol then part.Color = wantCol end
			if part.Material ~= wantMat then part.Material = wantMat end
		end)
		rec.request, rec.applied = size, part.Size
		rec.busy = false
		return true
	end

	const function clearQueue()
		table.clear(pst.queue)
		table.clear(pst.qSet)
		pst.qHead, pst.qTail = 1, 0
	end

	const function flush()
		const deadline = os.clock() + timeWork
		local work = 0
		while pst.qHead <= pst.qTail and work < maxWork and os.clock() < deadline do
			const part = pst.queue[pst.qHead]
			pst.queue[pst.qHead] = nil
			pst.qSet[part] = nil
			pst.qHead += 1
			work += 1
			refresh(part)
		end
		if pst.qHead > pst.qTail and pst.qTail > 0 then
			clearQueue()
		end
		if not active() then
			scan = nil
			if pst.qTail == 0 then NAlib.disconnect("partsizeFlush") end
			return
		end
		if work >= maxWork or os.clock() >= deadline then return end
		if not scan and os.clock() >= scanAt then
			scan = NAmanage.QueryDescendants(world, "BasePart")
			scanPos = 1
		end
		if not scan then return end
		local checked = 0
		while scanPos <= #scan and checked < maxScan and work < maxWork and os.clock() < deadline do
			const part = scan[scanPos]
			scanPos += 1
			checked += 1
			if not pst.qSet[part] and refresh(part, true) then
				work += 1
			end
		end
		if scanPos > #scan then
			scan = nil
			scanAt = os.clock() + 4
		end
	end

	const function updateWatch()
		if active() then
			if not NAlib.isConnected("partsizeWatch") then
				NAlib.connect("partsizeWatch", NAmanage.wsSub({
					classAdded = "BasePart",
					added = function(part)
						if active() then queue(part) end
					end,
				}))
			end
		else
			NAlib.disconnect("partsizeWatch")
		end
		if (active() or pst.qTail > 0) and not NAlib.isConnected("partsizeFlush") then
			NAlib.connect("partsizeFlush", Services.RunService.Heartbeat:Connect(flush))
		end
	end

	NAmanage.PST_UpdateActive = function(newOpts)
		setStyle(newOpts)
		for part in pst.orig do queue(part) end
		updateWatch()
	end

	const function addRule(rules, nameArg, sizeArg, invalidName)
		const term = Lower(tostring(nameArg or "")):match("^%s*(.-)%s*$") or ""
		if term == "" then DoNotif(invalidName, 2) return end
		local n = tonumber(sizeArg)
		if not n or n ~= n then DoNotif("Invalid size", 2) return end
		n = math.clamp(n, 0.1, 2048)
		rules[term] = Vector3.new(n, n, n)
		scanPos, scanAt = 1, 0
		updateWatch()
	end

	const function undo(rules, kind, title, desc, command)
		const buttons = {}
		const function remove(term)
			if term then rules[term] = nil else table.clear(rules) end
			for part, rec in pst.orig do
				if rec.kind == kind and (not term or rec.term == term) then
					queue(part)
				end
			end
			updateWatch()
			if term then
				DoNotif("Reverted "..command.." for '"..term.."'.", 2)
			else
				DoNotif("Cleared all "..kind.."-name partsize changes.", 2)
			end
		end
		for term in rules do
			Insert(buttons, { Text = term, Callback = function() remove(term) end })
		end
		if #buttons == 0 then
			DoNotif("No "..kind.."-name partsize changes are active.", 2)
			return
		end
		table.sort(buttons, function(a, b) return a.Text < b.Text end)
		Insert(buttons, 1, { Text = "All", Callback = function() remove() end })
		Window({ Title = title, Description = desc, Buttons = buttons })
	end

	cmd.register({
		name = "partsize",
		aliases = { "psize", "sizepart" },
		description = "Grow a part or model named exactly <name> to the cube size you choose.",
		usage = "partsize {name} {size}",
		requiresArguments = true,
		callback = function(nameArg, sizeArg)
			addRule(pst.sizeE, nameArg, sizeArg, "Invalid name")
		end,
	})

	cmd.register({
		name = "partsizefind",
		aliases = { "psizefind", "sizefind", "partsizef" },
		description = "Grow every part or model whose name contains <term> to the cube size you choose.",
		usage = "partsizefind {term} {size}",
		requiresArguments = true,
		callback = function(termArg, sizeArg)
			addRule(pst.sizeP, termArg, sizeArg, "Invalid term")
		end,
	})

	cmd.register({
		name = "unpartsize",
		aliases = { "unsizepart", "unpsize" },
		description = "Undo partsize—return those parts back to their original size and collision.",
		requiresArguments = true,
		callback = function()
			undo(pst.sizeE, "exact", "Undo Exact Partsize", "Select a name to restore original size (future spawns included).", "partsize")
		end,
	})

	cmd.register({
		name = "unpartsizefind",
		aliases = { "unsizefind", "unpsizefind" },
		description = "Undo partsizefind—return those resized parts back to their original size and collision.",
		requiresArguments = true,
		callback = function()
			undo(pst.sizeP, "partial", "Undo Partial Partsize", "Select a term to restore original size (future spawns included).", "partsizefind")
		end,
	})

	NAmanage.RegisterUnloadCleanup("partsize", function()
		NAlib.disconnect("partsizeWatch")
		NAlib.disconnect("partsizeFlush")
		table.clear(pst.sizeE)
		table.clear(pst.sizeP)
		clearQueue()
		scan = nil
		for part, rec in pst.orig do restore(part, rec) end
	end)
end

cmd.register({
	name = "breakcars",
	aliases = { "bcars" },
	description = "Breaks any car",
	usage = "breakcars (bcars)",
	callback = function()
		NAStuff = NAStuff or {}
		const CONN_KEY = "breakcars"
		if NAStuff._breakcarsEnabled then
			NAStuff._breakcarsEnabled = false
			NAlib.disconnect(CONN_KEY)
			if NAStuff._breakcarsFolder then
				pcall(function() NAStuff._breakcarsFolder:Destroy() end)
			end
			NAStuff._breakcarsFolder = nil
			DoNotif("Breakcars disabled", 2, "BreakCars")
			return
		end
		NAStuff._breakcarsEnabled = true
		NAlib.disconnect(CONN_KEY)
		if NAStuff._breakcarsFolder then
			pcall(function() NAStuff._breakcarsFolder:Destroy() end)
			NAStuff._breakcarsFolder = nil
		end

		DebugNotif("Car breaker loaded, sit on a vehicle and be the driver")

		const Player = Services.Players.LocalPlayer
		const Mouse = NAmanage.GetMouse(Player)

		const Folder = InstanceNew("Folder")
		Folder.Parent = Services.Workspace
		NAStuff._breakcarsFolder = Folder
		NAlib.connect(CONN_KEY, Folder.AncestryChanged:Connect(function(_, parent)
			if not parent then
				NAStuff._breakcarsEnabled = false
				NAStuff._breakcarsFolder = nil
				Defer(function()
					NAlib.disconnect(CONN_KEY)
				end)
			end
		end))

		const Part = InstanceNew("Part")
		Part.Anchored = true
		Part.CanCollide = false
		Part.Transparency = 1
		Part.Size = Vector3.new(1, 1, 1)
		Part.Parent = Folder

		const Attachment1 = InstanceNew("Attachment")
		Attachment1.Parent = Part

		const function getBreakcarsTarget()
			const cf = NAmanage.GetMouseWorldCFrame(Mouse, { Player and Player.Character, Folder }, 2048)
			if cf then
				return cf + Vector3.new(0, 5, 0)
			end
			return CFrame.new(Part.Position)
		end

		local UpdatedPosition = getBreakcarsTarget()

		SpawnCall(function()
			while NAStuff._breakcarsEnabled and Wait() do
				for _, player in __lt.cm("Players", "GetPlayers") do
					if player ~= Player then
						pcall(function() player.MaximumSimulationRadius = 0 end)
						pcall(function() if opt and opt.hiddenprop then opt.hiddenprop(player, "SimulationRadius", 0) end end)
					end
				end
				pcall(function() Player.MaximumSimulationRadius = math.pow(math.huge, math.huge) end)
				pcall(function() if setsimulationradius then setsimulationradius(math.huge) end end)
			end
		end)

		const function applyForceToPart(part)
			if not part:IsA("BasePart") or part.Anchored then return end
			if part.Name == "Handle" then return end
			const parent = part.Parent
			if getPlrHum(parent) or getHead(parent) then return end

			Mouse.TargetFilter = part

			for _, v in part:GetChildren() do
				if v:IsA("BodyAngularVelocity") or v:IsA("BodyForce") or v:IsA("BodyGyro")
					or v:IsA("BodyPosition") or v:IsA("BodyThrust") or v:IsA("BodyVelocity")
					or v:IsA("RocketPropulsion") or v:IsA("Torque") or v:IsA("AlignPosition")
					or v:IsA("Attachment") then
					v:Destroy()
				end
			end

			part.CanCollide = false

			const torque = InstanceNew("Torque")
			torque.Torque = Vector3.new(100000, 100000, 100000)
			torque.Parent = part

			const alignPosition = InstanceNew("AlignPosition")
			alignPosition.MaxForce = math.huge
			alignPosition.MaxVelocity = math.huge
			alignPosition.Responsiveness = 200
			alignPosition.Parent = part

			const attachment2 = InstanceNew("Attachment")
			attachment2.Parent = part

			torque.Attachment0 = attachment2
			alignPosition.Attachment0 = attachment2
			alignPosition.Attachment1 = Attachment1
		end

		for _, descendant in NAmanage.QueryDescendants(Services.Workspace, "BasePart") do
			applyForceToPart(descendant)
		end

		NAlib.connect(CONN_KEY, NAmanage.wsAdd(applyForceToPart))

		NAlib.connect(CONN_KEY, Services.UserInputService.InputBegan:Connect(function(input, isChatting)
			if input.KeyCode == Enum.KeyCode.E and not isChatting then
				UpdatedPosition = getBreakcarsTarget()
			end
		end))

		SpawnCall(function()
			while NAStuff._breakcarsEnabled and Wait() do
				pcall(function()
					Attachment1.WorldCFrame = UpdatedPosition
				end)
			end
			pcall(function()
				if Folder and Folder.Parent then
					Folder:Destroy()
				end
			end)
		end)
	end,
})

NAmanage.NetworkClaimGetState = function()
	local state = NAStuff._networkClaimState
	if type(state) ~= "table" then
		state = {
			enabled = false;
			radius = 200;
			all = false;
			lastScan = 0;
			changedRules = NAmanage.ensureWeakKeyTable(nil);
			previousPhysics = nil;
			radiusCaptured = false;
			previousSimulationRadius = nil;
			previousMaximumSimulationRadius = nil;
		}
		NAStuff._networkClaimState = state
	end
	state.changedRules = NAmanage.ensureWeakKeyTable(state.changedRules)
	return state
end

NAmanage.NetworkClaimGetHidden = function(inst, property)
	if type(gethiddenproperty) == "function" then
		local ok, value = pcall(gethiddenproperty, inst, property)
		if ok then
			return true, value
		end
	end
	local ok, value = pcall(function()
		return inst[property]
	end)
	return ok, value
end

NAmanage.NetworkClaimApplyRadius = function(state)
	if not state.radiusCaptured then
		state.radiusCaptured = true
		local okSim, simRadius = NAmanage.NetworkClaimGetHidden(LocalPlayer, "SimulationRadius")
		if okSim then
			state.previousSimulationRadius = simRadius
		end
		pcall(function()
			state.previousMaximumSimulationRadius = LocalPlayer.MaximumSimulationRadius
		end)
	end

	local radius = state.all and math.huge or math.max(25, tonumber(state.radius) or 200)
	pcall(function()
		opt.hiddenprop(LocalPlayer, "SimulationRadius", radius)
	end)
	pcall(function()
		LocalPlayer.MaximumSimulationRadius = radius
	end)
	if type(setsimulationradius) == "function" then
		pcall(setsimulationradius, radius)
	end
end

NAmanage.NetworkClaimRestoreRadius = function(state)
	if not state.radiusCaptured then
		return
	end
	state.radiusCaptured = false
	if state.previousSimulationRadius ~= nil then
		pcall(function()
			opt.hiddenprop(LocalPlayer, "SimulationRadius", state.previousSimulationRadius)
		end)
	end
	if state.previousMaximumSimulationRadius ~= nil then
		pcall(function()
			LocalPlayer.MaximumSimulationRadius = state.previousMaximumSimulationRadius
		end)
	end
	state.previousSimulationRadius = nil
	state.previousMaximumSimulationRadius = nil
end

NAmanage.NetworkClaimSetPhysics = function(state)
	if state.previousPhysics ~= nil then
		return
	end
	local backup = {}
	local okSettings, physics = pcall(function()
		return settings().Physics
	end)
	if not okSettings or not physics then
		state.previousPhysics = backup
		return
	end
	local okSleep, oldSleep = pcall(function()
		return physics.AllowSleep
	end)
	if okSleep then
		backup.allowSleep = oldSleep
		pcall(function()
			physics.AllowSleep = false
		end)
	end
	local okThrottle, oldThrottle = pcall(function()
		return physics.PhysicsEnvironmentalThrottle
	end)
	if okThrottle then
		backup.throttle = oldThrottle
		pcall(function()
			physics.PhysicsEnvironmentalThrottle = Enum.EnviromentalPhysicsThrottle.Disabled
		end)
	end
	state.previousPhysics = backup
end

NAmanage.NetworkClaimRestorePhysics = function(state)
	local backup = state.previousPhysics
	state.previousPhysics = nil
	if type(backup) ~= "table" then
		return
	end
	local okSettings, physics = pcall(function()
		return settings().Physics
	end)
	if not okSettings or not physics then
		return
	end
	if backup.allowSleep ~= nil then
		pcall(function()
			physics.AllowSleep = backup.allowSleep
		end)
	end
	if backup.throttle ~= nil then
		pcall(function()
			physics.PhysicsEnvironmentalThrottle = backup.throttle
		end)
	end
end

NAmanage.NetworkClaimScan = function(notify)
	local state = NAmanage.NetworkClaimGetState()
	NAmanage.NetworkClaimApplyRadius(state)

	local currentCharacter = getChar()
	local candidates = {}
	if state.all == true then
		candidates = NAmanage.QueryDescendants(Services.Workspace, "BasePart")
	else
		local characterRoot = currentCharacter and getRoot(currentCharacter)
		if not characterRoot then
			if notify then
				DoNotif("Network claim: character root unavailable", 2)
			end
			return 0, 0, 0
		end
		local overlap = OverlapParams.new()
		overlap.FilterType = Enum.RaycastFilterType.Exclude
		overlap.FilterDescendantsInstances = currentCharacter and { currentCharacter } or {}
		overlap.MaxParts = 1000
		local ok, parts = pcall(function()
			return Services.Workspace:GetPartBoundsInRadius(characterRoot.Position, tonumber(state.radius) or 200, overlap)
		end)
		if ok and type(parts) == "table" then
			candidates = parts
		end
	end

	local seen = NAmanage.ensureWeakKeyTable(nil)
	local processed = 0
	local changed = 0
	local owned = 0
	for _, part in candidates do
		if typeof(part) == "Instance" and part:IsA("BasePart") and not part.Anchored then
			local assembly = part.AssemblyRootPart or part
			if assembly and not assembly.Anchored and not seen[assembly] and (not currentCharacter or not assembly:IsDescendantOf(currentCharacter)) then
				seen[assembly] = true
				processed += 1

				local readable, rule = NAmanage.NetworkClaimGetHidden(assembly, "NetworkOwnershipRule")
				if readable and rule ~= Enum.NetworkOwnership.Automatic then
					if state.changedRules[assembly] == nil then
						state.changedRules[assembly] = rule
					end
					pcall(opt.hiddenprop, assembly, "NetworkOwnershipRule", Enum.NetworkOwnership.Automatic)
					local okAfter, afterRule = NAmanage.NetworkClaimGetHidden(assembly, "NetworkOwnershipRule")
					if okAfter and afterRule == Enum.NetworkOwnership.Automatic then
						changed += 1
					end
				elseif not readable then
					pcall(opt.hiddenprop, assembly, "NetworkOwnershipRule", Enum.NetworkOwnership.Automatic)
				end

				pcall(opt.hiddenprop, assembly, "NetworkIsSleeping", false)

				if type(isnetworkowner) == "function" then
					local okOwner, result = pcall(isnetworkowner, assembly)
					if okOwner and result == true then
						owned += 1
					end
				end
			end
		end
	end

	if notify then
		local scope = state.all and "all Workspace parts" or (tostring(state.radius).." studs")
		local ownerText = type(isnetworkowner) == "function" and (", owned "..tostring(owned)) or ""
		DoNotif("Network claim active ("..scope.."): scanned "..tostring(processed)..", changed "..tostring(changed)..ownerText, 4)
	end
	return processed, changed, owned
end

NAmanage.NetworkClaimStart = function(value)
	local state = NAmanage.NetworkClaimGetState()
	local text = tostring(value or ""):lower()
	if text == "all" then
		state.all = true
	else
		state.all = false
		state.radius = math.clamp(tonumber(value) or tonumber(state.radius) or 200, 25, 2048)
	end
	state.enabled = true
	state.lastScan = 0
	NAmanage.NetworkClaimSetPhysics(state)
	NAmanage.NetworkClaimScan(true)
	NAlib.reconnect("network_claim_loop", Services.RunService.Heartbeat:Connect(function()
		if not state.enabled then
			return
		end
		local now = os.clock()
		if now - (tonumber(state.lastScan) or 0) < 0.35 then
			return
		end
		state.lastScan = now
		NAmanage.NetworkClaimScan(false)
	end))
end

NAmanage.NetworkClaimStop = function(notify)
	local state = NAmanage.NetworkClaimGetState()
	local wasEnabled = state.enabled == true
	state.enabled = false
	NAlib.disconnect("network_claim_loop")
	for part, rule in state.changedRules do
		if typeof(part) == "Instance" and part.Parent then
			pcall(opt.hiddenprop, part, "NetworkOwnershipRule", rule)
		end
	end
	state.changedRules = NAmanage.ensureWeakKeyTable(nil)
	NAmanage.NetworkClaimRestoreRadius(state)
	NAmanage.NetworkClaimRestorePhysics(state)
	if notify ~= false then
		DoNotif(wasEnabled and "Network claim disabled and reversible changes restored" or "Network claim is already disabled", 3)
	end
end

NAmanage.RegisterUnloadCleanup("network_claim_restore", function()
	NAmanage.NetworkClaimStop(false)
end, 115)

