NAmanage.NoEffects = {}

do
	const post = {Enabled = false}
	const atmo = {Density = 0, Haze = 0, Glare = 0}
	const fog = {FogStart = 0, FogEnd = 786543}
	NAmanage.NoEffects.Props = function(inst)
		if inst:IsA("PostEffect") then return post end
		if inst:IsA("Atmosphere") then return atmo end
		if inst == Services.Lighting then return fog end
		return nil
	end
end

NAmanage.NoEffects.Stop = function()
	const st = _na_env._LState
	const ne = st and st.ne
	if not ne or not ne.stop then return false end
	ne.stop()
	return true
end

NAmanage.StartClearLighting = function(mode)
	const light, world = Services.Lighting, Services.Workspace
	if not (light and world) then return false end
	const st = NAmanage._ensureL()
	const fogOnly = mode == "nf"
	const field = fogOnly and "nf" or "ne"
	const current = st[field]
	if current and current.enabled then
		if current.scan then current.scan() end
		return true
	end
	if fogOnly then
		NAmanage.NoEffects.Stop()
	else
		NAmanage.NoFog.Stop()
		st.cancelFor("ne")
	end
	if st.disableNM then st.disableNM() end
	const ne = {enabled = true, sticky = fogOnly, cache = {}, conns = {}, camConns = {}}
	st[field] = ne
	const function scope(inst)
		return inst == light or inst:IsDescendantOf(light)
			or (ne.camera ~= nil and inst:IsDescendantOf(ne.camera))
	end
	const function drop(inst, restore)
		const rec = ne.cache[inst]
		if not rec then return end
		ne.cache[inst] = nil
		for _, conn in rec.conns do conn:Disconnect() end
		table.clear(rec.conns)
		const keepFog = fogOnly and inst == light and ((st.fb and st.fb.enabled) or (st.nb and st.nb.enabled))
		if restore and not keepFog then
			for prop, value in rec.saved do
				if st.safeGet(inst, prop) ~= value then
					st.safeSet(inst, prop, value)
				end
			end
		end
	end
	const function watch(inst)
		if not ne.enabled or ne.cache[inst] or not scope(inst) then return end
		const props = NAmanage.NoEffects.Props(inst)
		if not props then return end
		const rec = {saved = {}, conns = {}}
		ne.cache[inst] = rec
		for prop, target in props do
			const value = st.safeGet(inst, prop)
			if value ~= nil then
				rec.saved[prop] = value
				const function enforce()
					if not ne.enabled or ne.cache[inst] ~= rec then return end
					if not scope(inst) then
						drop(inst, true)
						return
					end
					if st.safeGet(inst, prop) ~= target then
						st.safeSet(inst, prop, target)
					end
				end
				rec.conns[#rec.conns + 1] = inst:GetPropertyChangedSignal(prop):Connect(enforce)
				enforce()
			end
		end
	end
	const function removed(inst)
		if not ne.cache[inst] then return end
		task.defer(function()
			if ne.enabled and ne.cache[inst] and not scope(inst) then
				drop(inst, true)
			end
		end)
	end
	const function scan(root)
		if not root then return end
		watch(root)
		for _, inst in NAmanage.QueryDescendants(root, "PostEffect, Atmosphere") do watch(inst) end
	end
	const function camera()
		if not ne.enabled then return end
		const cam = world.CurrentCamera
		if ne.camera ~= cam then
			for _, conn in ne.camConns do conn:Disconnect() end
			table.clear(ne.camConns)
			ne.camera = cam
			for inst in ne.cache do
				if not scope(inst) then drop(inst, true) end
			end
			if cam then
				ne.camConns[1] = cam.DescendantAdded:Connect(watch)
				ne.camConns[2] = cam.DescendantRemoving:Connect(removed)
			end
		end
		scan(cam)
	end
	ne.scan = function()
		if not ne.enabled then return end
		scan(light)
		camera()
	end
	ne.stop = function()
		ne.enabled, ne.sticky = false, false
		for _, conn in ne.conns do conn:Disconnect() end
		for _, conn in ne.camConns do conn:Disconnect() end
		table.clear(ne.conns)
		table.clear(ne.camConns)
		for inst in ne.cache do drop(inst, true) end
		ne.camera, ne.scan, ne.stop = nil, nil, nil
		if st[field] == ne then st[field] = nil end
	end
	ne.conns[1] = light.DescendantAdded:Connect(watch)
	ne.conns[2] = light.DescendantRemoving:Connect(removed)
	ne.conns[3] = world:GetPropertyChangedSignal("CurrentCamera"):Connect(camera)
	ne.scan()
	return true
end

NAmanage.NoEffects.Start = function()
	return NAmanage.StartClearLighting("ne")
end

NAmanage.NoFog = {}

NAmanage.NoFog.Start = function()
	return NAmanage.StartClearLighting("nf")
end

NAmanage.NoFog.Stop = function()
	const st = _na_env._LState
	const nf = st and st.nf
	if not nf or not nf.stop then return false end
	nf.stop()
	return true
end

NAmanage.NoEffects.Clear = function()
	if not Services.Lighting then return end
	const st = NAmanage._ensureL()
	const function clear(inst)
		for prop, target in NAmanage.NoEffects.Props(inst) or {} do
			if st.safeGet(inst, prop) ~= target then
				st.safeSet(inst, prop, target)
			end
		end
	end
	for _, root in {Services.Lighting, Services.Workspace.CurrentCamera} do
		if root then
			clear(root)
			for _, inst in root:GetDescendants() do clear(inst) end
		end
	end
end

