NAmanage.GetArceusFPS = function()
	const cached = type(shared) == "table" and rawget(shared, "__lt_arceus_fps")
	if type(cached) == "table" and type(cached.set) == "function" then return cached end
	const ok, src = NAmanage.HttpGet("https://ltseverydayyou.gitlab.io/uuuuuuu/ArceusFPS.luau", { timeout = 5 })
	if not ok then return nil end
	const compiled, fn = pcall(NAmanage.RawCompile, src, "@ArceusFPS.luau")
	if not compiled or type(fn) ~= "function" then return nil end
	const loaded, ctl = pcall(fn)
	if loaded and type(ctl) == "table" and type(ctl.set) == "function" then return ctl end
end

NAmanage.RegisterUnloadCleanup("fps_cap", function()
	NAStuff.fpsReq = (NAStuff.fpsReq or 0) + 1
	const ctl = NAStuff.fpsCtl
	NAStuff.fpsCtl = nil
	if ctl then ctl.set("NA", nil) end
end)

cmd.register({
	name = "fpscap",
	aliases = { "fpslimit" },
	description = "Set the FPS cap. Use 0 for unlimited",
	usage = "fpscap <number>",
	requiresArguments = true,
	callback = function(arg)
		const cap = tonumber(arg)
		if not cap or cap ~= cap or math.abs(cap) == math.huge then
			return DoNotif("Enter a valid FPS cap.", 3)
		end
		if type(setfpscap) ~= "function" then
			return DoNotif("FPS control is unavailable in this executor.", 3)
		end
		const limit = cap == 0 and 0 or math.clamp(math.floor(cap + 0.5), 1, 999)
		const req = (NAStuff.fpsReq or 0) + 1
		NAStuff.fpsReq = req
		const id = identifyexecutor or getexecutorname
		local okID, name = false, nil
		if type(id) == "function" then okID, name = pcall(id) end
		const v5 = okID and Lower(tostring(name)) == "arceus x v5"
		if v5 then
			const ctl = NAStuff.fpsCtl or NAmanage.GetArceusFPS()
			if NAStuff.fpsReq ~= req then return end
			if ctl then
				const ok, err = ctl.set("NA", limit)
				if ok then NAStuff.fpsCtl = ctl else DoNotif(tostring(err), 3) end
				return
			end
		end
		const ok, err = pcall(setfpscap, limit)
		if not ok then DoNotif(tostring(err), 3)
		elseif v5 then DoNotif("FPS cap applied once. Arceus V5 FPS control could not load.", 4) end
	end,
})

cmd.register({
	name = "unfpscap",
	aliases = { "unfpslimit" },
	description = "Release Nameless Admin's FPS override on Arceus V5",
	callback = function()
		NAStuff.fpsReq = (NAStuff.fpsReq or 0) + 1
		const ctl = NAStuff.fpsCtl
		NAStuff.fpsCtl = nil
		if not ctl then return DoNotif("No Arceus V5 FPS override is active.", 3) end
		const ok, err = ctl.set("NA", nil)
		if not ok then DoNotif(tostring(err), 3) end
	end,
})

cmd.register({
	name = "toolinvisible",
	aliases = { "tinvis" },
	description = "Be invisible while still being able to use tools",
	usage = "toolinvisible (tinvis)",
	callback = function()
		const offset = 1100
		invisible = false
		const grips = {}
		local heldTool
		local gripChanged
		local handle
		local weld
		HH = getHum().HipHeight

		function setDisplayDistance(distance)
			for _, player in __lt.cm("Players", "GetPlayers") do
				if getPlrChar(player) and getPlrHum(player) then
					getPlrHum(player).NameDisplayDistance = distance
					getPlrHum(player).HealthDisplayDistance = distance
				end
			end
		end

		const tool = InstanceNew("Tool", Services.Players.LocalPlayer.Backpack)
		tool.Name = "Turn Invisible"
		tool.RequiresHandle = false
		tool.CanBeDropped = false

		tool.Equipped:Connect(function()
			Wait()
			if not invisible then
				invisible = true
				tool.Name = "Visible Enabled"

				if handle then
					handle:Destroy()
				end
				if weld then
					weld:Destroy()
				end

				handle = InstanceNew("Part", Services.Workspace)
				handle.Name = "Handle"
				handle.Transparency = 1
				handle.CanCollide = false
				handle.Size = Vector3.new(2, 1, 1)

				weld = InstanceNew("Weld", handle)
				weld.Part0 = handle
				weld.Part1 = getRoot(getChar())
				weld.C0 = CFrame.new(0, offset - 1.5, 0)

				setDisplayDistance(offset + 100)
				Services.Workspace.CurrentCamera.CameraSubject = handle
				getRoot(getChar()).CFrame = getRoot(getChar()).CFrame * CFrame.new(0, offset, 0)
				getHum().HipHeight = offset
				getHum():ChangeState(11)

				for _, child in Services.Players.LocalPlayer.Backpack:GetChildren() do
					if child:IsA("Tool") and child ~= tool then
						grips[child] = child.Grip
					end
				end
				if getHum() then
					getHum():SetStateEnabled("Seated", false)
					getHum().Sit = true
				end
			else
				invisible = false
				tool.Name = "Visible Disabled"

				if handle then
					handle:Destroy()
				end
				if weld then
					weld:Destroy()
				end

				for _, child in getChar():GetChildren() do
					if child:IsA("Tool") then
						child.Parent = Services.Players.LocalPlayer.Backpack
					end
				end

				for tool, grip in grips do
					if tool then
						tool.Grip = grip
					end
				end

				heldTool = nil
				setDisplayDistance(100)
				Services.Workspace.CurrentCamera.CameraSubject = getHum()
				getRoot(getChar()).CFrame = getRoot(getChar()).CFrame * CFrame.new(0, -offset, 0)
				getHum().HipHeight = HH

				if getHum() then
					getHum():SetStateEnabled("Seated", true)
					getHum().Sit = false
				end
			end

			tool.Parent = Services.Players.LocalPlayer.Backpack
		end)

		NAmanage.childAdd(getChar(), function(child)
			Wait()
			if invisible and child:IsA("Tool") and child ~= heldTool and child ~= tool then
				heldTool = child
				local lastGrip = heldTool.Grip

				if not grips[heldTool] then
					grips[heldTool] = lastGrip
				end

				for _, track in getHum():GetPlayingAnimationTracks() do
					track:Stop()
				end

				getChar().Animate.Disabled = true
				heldTool.Grip = heldTool.Grip * (CFrame.new(0, offset - 1.5, 1.5) * CFrame.Angles(math.rad(-90), 0, 0))
				heldTool.Parent = Services.Players.LocalPlayer.Backpack
				heldTool.Parent = getChar()

				if gripChanged then
					gripChanged:Disconnect()
				end

				gripChanged = heldTool:GetPropertyChangedSignal("Grip"):Connect(function()
					Wait()
					if not invisible then
						gripChanged:Disconnect()
					end

					if heldTool.Grip ~= lastGrip then
						lastGrip = heldTool.Grip * (CFrame.new(0, offset - 1.5, 1.5) * CFrame.Angles(math.rad(-90), 0, 0))
						heldTool.Grip = lastGrip
						heldTool.Parent = Services.Players.LocalPlayer.Backpack
						heldTool.Parent = getChar()
					end
				end)
			end
		end, function(child)
			return child and child:IsA("Tool")
		end)
	end,
})

