cmd.register({
	name = "flingnpcs",
	description = "Flings NPCs",
	callback = function()
		const npcs = {}

		const function disappear(hum)
			if CheckIfNPC(hum.Parent) then
				Insert(npcs,{hum,hum.HipHeight})
				hum.HipHeight = 1024
			end
		end
		for _, hum in NAmanage.QueryDescendants(Services.Workspace, "Humanoid") do
			disappear(hum)
		end
	end,
})

NAmanage.NPCFollowStep = function()
	const char = getChar()
	const root = char and getRoot(char)
	if not root then return end
	const pos = root.Position
	for _, hum in NAmanage.QueryDescendants(Services.Workspace, "Humanoid") do
		if CheckIfNPC(hum.Parent) then
			hum:MoveTo(pos)
		end
	end
end

cmd.register({
	name = "npcfollow",
	description = "Makes NPCS follow you",
	callback = NAmanage.NPCFollowStep,
})

