cmd.register({
	name = "bringnpcs",
	description = "Brings NPCs",
	usage = "bringnpcs [distance]",
	callback = function(...)
		const char = getChar()
		const root = char and getRoot(char)
		if not root then return end
		const dist = NAmanage.parseBringDistance({...}, 0)
		const cf = NAmanage.bringOffsetCFrame(root.CFrame, dist)
		for _, model in NAmanage.NPCArgAll() do
			NAmanage.PivotRigRoot(model, cf)
		end
	end,
})

npcCache = {}
NAStuff._npcBringParts = {}
NAmanage.NPCBringStop = function()
	NAlib.disconnect("loopbringnpcs")
	for model, cache in NAStuff._npcBringParts do
		cache:Disconnect()
		NAStuff._npcBringParts[model] = nil
	end
	table.clear(npcCache)
end
NAmanage.RegisterUnloadCleanup("npc_bring_cleanup", NAmanage.NPCBringStop)

cmd.register({
	name = "loopbringnpcs",
	aliases = { "lbnpcs", "loopbnpcs", "lbringnpcs", "lbringnpc", "loopbringnpc" },
	description = "Loops NPC bringing",
	usage = "loopbringnpcs [distance] (lbnpcs, loopbnpcs, lbringnpcs)",
	callback = function(...)
		const args = {...}
		const distance = NAmanage.parseBringDistance(args, 0)
		NAmanage.NPCBringStop()
		for _, model in NAmanage.NPCArgAll() do
			Insert(npcCache, model)
			NAStuff._npcBringParts[model] = NAmanage.CreatePartCache(model)
		end
		NAlib.connect("loopbringnpcs", Services.RunService.PreSimulation:Connect(function()
			const char = getChar()
			const localRoot = char and getRoot(char)
			const cf = localRoot and NAmanage.bringOffsetCFrame(localRoot.CFrame, distance)
			local w = 1
			for _, model in npcCache do
				const cache = NAStuff._npcBringParts[model]
				const hum = model:FindFirstChildOfClass("Humanoid")
				if cache and cache.Connected and model:IsDescendantOf(Services.Workspace)
					and ((hum and hum.Health > 0) or (not hum and NAmanage.HasRigParts(model))) then
					npcCache[w] = model
					w += 1
					if model ~= char then
						if cf then NAmanage.PivotRigRoot(model, cf) end
						for part in cache.parts do
							if part.Parent and part.CanCollide then part.CanCollide = false end
						end
					end
				elseif cache then
					cache:Disconnect()
					NAStuff._npcBringParts[model] = nil
				end
			end
			for i = w, #npcCache do npcCache[i] = nil end
			for model, cache in NAStuff._npcBringParts do
				if not model:IsDescendantOf(Services.Workspace) or not cache.Connected then
					cache:Disconnect()
					NAStuff._npcBringParts[model] = nil
				end
			end
		end))
	end,
})

cmd.register({
	name = "unloopbringnpcs",
	aliases = { "unlbnpcs", "unloopbnpcs", "unlbringnpcs", "unlbringnpc", "unloopbringnpc" },
	description = "Stops NPC bring loop",
	usage = "unloopbringnpcs (unlbnpcs, unloopbnpcs, unlbringnpcs)",
	callback = NAmanage.NPCBringStop,
})

cmd.register({
	name = "gotonpcs",
	description = "Teleports to each NPC",
	callback = function()
		const npcs = NAmanage.NPCArgAll()
		SpawnCall(function()
			const char = getChar()
			if not char then return end
			for _, model in npcs do
				const root = model.Parent and getRoot(model)
				if root then
					NAmanage.PivotRigRoot(char, root.CFrame + Vector3.new(0, 3, 0))
				end
			end
		end)
	end,
})

NAStuff.NPCControl = {
	Enabled = false,
	Connection = nil,
	CurrentTarget = nil,
	MoveCooldown = 0
}

NPCControl = NAStuff.NPCControl

cmd.register({
	name = "actnpc",
	description = "Start acting like an NPC",
	callback = function()
		if NPCControl.Enabled then return end
		NPCControl.Enabled = true

		const function moveToRandom()
			const char = LocalPlayer.Character
			const hum = getHum()
			const root = getRoot(char)
			if not (char and hum and root) then return end

			const randomOffset = Vector3.new(math.random(-30, 30), 0, math.random(-30, 30))
			const targetPos = root.Position + randomOffset

			NPCControl.CurrentTarget = targetPos
			hum:MoveTo(targetPos)

			DebugNotif("Moving to: "..Format("X: %.0f, Y: %.0f, Z: %.0f", targetPos.X, targetPos.Y, targetPos.Z), 1.5)
		end

		NPCControl.Connection = NAlib.reconnect("actnpc_loop", Services.RunService.Heartbeat:Connect(function(dt)
			const char = LocalPlayer.Character
			const hum = getHum()
			const root = getRoot(char)
			if not (char and hum and root) then return end

			NPCControl.MoveCooldown=NPCControl.MoveCooldown - dt
			NPCControl._jumpCooldown = (NPCControl._jumpCooldown or 0) - dt
			NPCControl._moveTimeout = (NPCControl._moveTimeout or 0) + dt

			if hum.Sit then
				DebugNotif("Sitting detected — jumping to escape", 1.5)
				hum.Sit = false
				NAmanage.LaunchHumanoid(hum, root)
				NPCControl._jumpCooldown = 1.5
				return
			end

			if NPCControl.CurrentTarget and (root.Position - NPCControl.CurrentTarget).Magnitude < 2 then
				DebugNotif("Reached target", 1.5)
				NPCControl.CurrentTarget = nil
			end

			if not NPCControl.CurrentTarget or NPCControl._moveTimeout > 5 then
				if NPCControl._moveTimeout > 5 then
					DebugNotif("Stuck — retrying new path", 1.5)
				end
				if NPCControl.MoveCooldown <= 0 then
					moveToRandom()
					NPCControl.MoveCooldown = math.random(2, 4)
					NPCControl._moveTimeout = 0
				end
			end

			const forward = root.CFrame.LookVector
			const origin = root.Position + Vector3.new(0, 2, 0)
			const rayParams = RaycastParams.new()
			rayParams.FilterType = Enum.RaycastFilterType.Blacklist
			rayParams.FilterDescendantsInstances = {char}
			const result = Services.Workspace:Raycast(origin, forward * 3 + Vector3.new(0, -2, 0), rayParams)

			if result and NPCControl._jumpCooldown <= 0 then
				const part = result.Instance
				const model = part:FindFirstAncestorOfClass("Model")
				const isPlayerChar = model and __lt.cm("Players", "GetPlayerFromCharacter", model)

				if part.CanCollide and not isPlayerChar then
					if hum:GetState() == Enum.HumanoidStateType.Running then
						DebugNotif("Obstacle detected — jumping", 1.5)
						NAmanage.LaunchHumanoid(hum, root)
						NPCControl._jumpCooldown = 1.5
					end
				end
			end
		end))
	end,
})

